window.__D("text/igrot-rebbe/c033",{"p":[[1200870003,"ד'עדר\n\n<p>ב\"ה, אדר\"ח אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>לאחרי שתיקתו הארוכה נתקבל מכתבו מיום הראשון, ובמה שכותב אודות הזקן, מובן שדבריו מופרכים, כיון שנשיאנו הק' אומרים שי\"ג תקו\"ד הם צנור להשפעה לאדם ולבני ביתו והשפעה ברחמים וברחמים גדולים (יעוין בזה בפירוש המלות לכ\"ק אדמו\"ר הצמח צדק על הפסוק והוא רחום, נדפס ג\"כ במילואים לתהלים יהל אור)...</p>\n<p>בברכה להכרת מצבו האמיתי, היינו שהזן ומפרנס לכל יספיק לו כדי פרנסתו ופרנסת כל ב\"ב שיחיו ובאופן הכשר ובאופן חסידותי וביחוד ע\"י י\"ג תקו\"ד האמורים ובמילא גם הוא עצמו יתפלא וגם יצר לו על זה, וואס מען פאטערט ניערווין און געזונט על דאגות מבלי יסוד, ומובן שאין זה סתירה כלל למ\"ש, בכל אשר תעשה דוקא, אלא שצ\"ל כדיוק לשון רז\"ל, יגיע כפיך כי תאכל, היינו רק יגיעת כפים גם במובן הרוחני, היינו כח המעשה והשתדלות אבל לא יגיע ראשך, היינו דאגות וטרדות הראש בזה, ואין להאריך בדבר הפשוט ומבואר בכ\"מ...</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<h4><i><b>ד'עדר</b></i></h4>\n<p><b> שדבריו מופרכים</b><b>:</b> ראה גם לעיל ח\"י אגרת ג'שכג.</p>\n<p><b> יגיע כפיך</b><b>:</b> ראה גם לעיל חי\"ב אגרת ד'ט*, ובהנסמן בהערות שם.</p>"],[1200870004,"ד'ערה\n\n<p>ב\"ה, אדר\"ח אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... מצערים השמועות אשר כנראה לקוי' ההתאמה שבין המנהלים והמורים ומורות, עד שישנם מקומות שבא להסדר דאיש כל הישר בעיניו יעשה, ומוכרח להפסיק בלתי סדר זה בהחלט <b>הכי גדול</b><b>,</b> וכבר ידוע עד כמה הקפידו נשיאינו הק' על המשמעת בכגון דא, ובפרט שאי אפשר שלא יגע במשמעת של תלמידים-ות כלפי המורים ומנהל...</p>\n<p>מובן שכיון שגם המנהל או חברי הנהלה הכללית, בו\"ד הם עלולים גם הם לטעות.</p>\n<p>אבל כיון שפב\"פ נתמנה למנהל או להנהלה הכללית, וכל המאמין בדברי רז\"ל מאמין גם במאמרם אשר אפילו ריש גרגותא משמיא קא ממני לי' - במילא (יש לו להגיש תלונה על הוראת המנהל או ההנהלה העומדת על גביהם בצירוף כל הטענות לשלילת ההוראה וכיו\"ב, ולבקש לדון בזה בהקדם הכי אפשרי, אם הבעיא דחופה היא, אבל) אין להרוס מוסד כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע על ידי מלחמה במנהל, ועשי' היפך הוראותיו תומ\"י על דעת עצמו וכיו\"ב, ואין להאריך בדבר המובן ופשוט. ויה\"ר שיבשרוני טוב בתיקון הנ\"ל בהקדם הכי אפשרי...</p>\n<p>המחכה לבשו\"ט בכל האמור.</p>\n<p>בברכה.</p>"],[1200870005,"ד'רעו\n\n<p>ב\"ה, אדר\"ח אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... ועל העיקר באתי במ\"ש בהנוגע לתלמידים... שנוהגים אתם בנזיפות וכו', ועד כדי הכאה... פשוט שהנהגה האמורה מופרכת היא בנוגע לתלמידים הקשישים ולולי מסתפינא הייתי אומר גם לתלמידים שאינם קשישים, וכמדומה שאמרתי לו עד\"ז ג\"כ בפירוש בעת ביקורו כאן, ומהנכון שתומ\"י ישתנה הנ\"ל...</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<h4><i><b>ד'רעו</b></i></h4>\n<p><b> ועד כדי הכאה</b><b>:</b> בהמשך אליה - לקמן אגרת ד'תי.</p>"],[1200870006,"ד'רעז\n\n<p>ב\"ה, אדר\"ח אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו (בלי הוראת זמן הכתיבה) בו שואל אודות הוראות בדרכי החסידות.</p>\n<p>הנה מובן שתלויות הן בתכונות נפש השואל, כשרונותיו, ואופן הסתדרותו, ולכן טוב ונכון שיתקשר עם צעירי אגודת חב\"ד אשר בסביבתו ועל ידם יוודע מזקני אנ\"ש הנמצאים שם וכהוראתם יעשה, ומובן שזהו נוסף על הנקודות הכלליות (והם נוסף על שלשת השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע בחומש תהלים ותניא הידועים), לימוד בתורת החסידות לעיונא עכ\"פ איזה פעמים בשבוע והליכה בהדרכותי' ומנהגי', וכמו שקבלת התורה בכללותה היתה ע\"י הקדמת נעשה לנשמע, כן הוא גם בהנוגע לכל חלק וחלק מתוה\"ק היינו לא להתחיל מקושיות וכו' אלא לקבל מראש הוראות אלו המנוסים כבר לכגון דא ואז במשך זמן לא ארוך תבוא גם ההבנה, והשי\"ת יצליחו לבשר טוב בכל האמור.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ד'רעז</b></i></h4>\n<p><b> וכמו שקבלת התורה:</b> ראה גם לעיל חי\"א אגרת ג'תקנ, ובהנסמן בהערות שם. חי\"ב ג'תתסה. ד'נז. לקמן ד'שעא.</p>"],[1200870007,"ד'רעח\n\n<p>ב\"ה, א' אייר, תשט\"ז</p><p>ברוקלין.</p><p>מחו' הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה שמואל שי' שו\"ב</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת הפתקא של אנשי מעמד שלו מר\"ח אדר ולפלא שמאז לא נתקבל ממנו כל ידיעות, ובטח זהו סימן שהכל בסדר ובשלום וכן אצל כל ב\"ב שיחיו. ויה\"ר שלא יסתפק בזה אלא קיים מרז\"ל דמעלין בקדש ותקוים בהם הבטחת רז\"ל כל המוסיף מוסיפין לו ובפרט כשמתעסקים בעניני תורה ומצות עם הזולת ובפרטי פרטית עם הזולת דלית לי' מגרמי' כלום בודאי שאז במדתו של הקב\"ה מדה כנגד מדה אלא שכ\"פ ככה מתוסף להמשתדל ולב\"ב, כיון דקמי' של הקב\"ה כאו\"א הוא בבחי' דלית לי' מגרמי' כלום, וימים אלו ימי סגולה הם, וכמדובר באחת ההתועדות, שסגולה מיוחדה לימי חדש זיו, אשר כל יום ויום יש לו מצוה מיוחדת לגבי שאר חדשי השנה, והיא מצות הספירה של העומר, אשר כללותה היא דמבהמה (עומר שעורים מאכל בהמה) באים למדריגת אדם (שתי הלחם דשבועות, חטים מאכל אדם) וכמבואר בדרושי ספירת העומר בלקו\"ת וכו'.</p>\n<p>בברכה לבשר טוב בכל האמור, ממנו וכן מכאו\"א מאנ\"ש שי' אשר במחנו הט'.</p>\n<h4><i><b>ד'רעח</b></i></h4>\n<p><b> מו\"ה שמואל:</b> גרוסמן, לונדון. אגרת נוספת אליו - לעיל ח\"ב שפה.</p>\n<p><b> וכמדובר באחת ההתועדות</b><b>:</b> ענין זה נתבאר בהתוועדות כ\"ק אדמו\"ר שליט\"א בשבת ר\"ח אייר תש\"ט - כדלעיל ח\"ג אגרת תעח. וראה גם לקו\"ש ח\"א ע' 263. חי\"ב ע' 171.</p>"],[1200870008,"ד'רעט\n\n<p>ב\"ה, א' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ מלאכתו מלאכת שמים<br>\nמו\"ה מנחם ישראל שי'</p>\n<p> שלום וברכה!</p>\n<p>לפלא שמאז מכתבו עם תמונת הבנין המוסגר בו, לא נתקבל מהם כל ידיעות ובודאי נתקבל מכתבי מכבר כתוב ע\"ש הרה\"ח כו' הרח\"ש שי' ברוק ויענו עליו בפרטיות הדרושה.</p>\n<p>ובמ\"ש בהנוגע להמצב הכספי החובות וכו'. הנה אף שמובן שקשה הדבר ומבלבל, אבל לצערנו עד\"ז הוא המצב בישיבת תו\"ת אפילו בארצוה\"ב, וכפי סיפורי זקני החסידים מעין זה הי' המצב החומרי ברבות שנות קיום הישיבה, ובכ\"ז לא לבד שהחזיקו מעמד אלא אדרבה גדלה והתפתחה, ובודאי ע\"י התעוררות ר\"ר של נשיאי מנהלי הישיבה תתגדל ותתפתח עוד יותר וגם הסניפים שלה בכלל, ואשרי חלקו של כאו\"א המשתדל ועובד עבודת הקדש בכגון זה, וכמו שראו כבר הצלחה מופלגה שעלה בידם להתחיל בבנין אשר חלק חשוב ממנו כבר נגמר, ובודאי יוגמר כולו בעתיד לא רחוק, וגדול שכר המשתדלים מבואר בכ\"מ אשר הוא אין לשער שהוא במדתו של הקב\"ה מדה כנגד מדה אלא שכמה פעמים ככה ברוב נחת אמיתי שהוא נחת חסידותי בבנים ובנות.</p>\n<p>במ\"ש אודות הסכום הסמלי ששלחתי, הנה אינו שייך לקופות ישיבות ומוסדות חינוך, אלא הוא מאחת הקופות של כ\"ק מו\"ח אדמו\"ר שכותב באחד ממכתביו בענין כגון דא, שבהקופה שלו מתקיים ע\"ד מרז\"ל, כל הנוטל פרוטה מאיוב מתברך ומזה מובן שריבוי הכמות אינו נוגע כלל וכלל, ואפשר שגם כו'...</p>\n<p>תקותי שניצלו ימי הפסח נוסף על ימי הסגולה שלפני זה באופן המתאים, וכן מכינים תכנית מתאימה לנצל יום הל\"ג בעומר בהשפעה על התלמידים ויה\"ר שיצליחו בעבודתם בקדש לעשותם חסידים יראי שמים ולומדים.</p>\n<p>בברכה לבשו\"ט בכל האמור ופ\"ש כאנ\"ש שי' ובפרט הרה\"ג והרה\"ח וכו' וכו' הרחש\"ב שי'.</p>\n<h4><i><b>ד'רעט</b></i></h4>\n<p><b> מו\"ה מנחם ישראל</b><b>:</b> מלוב, ראשון לציון. אגרת נוספת אליו - לעיל חי\"א אגרת ג'תרנג.</p>\n<p><b> תמונת הבנין</b><b>:</b> של ישיבת אחי תמימים בראשון לציון. ראה לעיל חי\"א אגרות ג'תקמח.</p>\n<p>ג'תרנג-ד. לקמן ד'שסב. ד'תז. ד'תשה. חנוכת הבית התקיימה בכ\"ה מנ\"א - כדלקמן אגרת ד'תרנג.</p>\n<p><b> מכתבי מכבר</b><b>:</b> דלעיל חי\"ב ד'לט.</p>\n<p><b> שכותב</b><b>:</b> ראה גם לעיל ח\"ה אגרות א'רסח. א'תכג.</p>"],[1200870009,"ד'רפ\n\n<p>ב\"ה, א' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>זיינער צייט האב איך באקומען אייער בריף צוזאמען מיט דעם בריף פון הוו\"ח אי\"א נו\"נ עוסק בצ\"צ רב פעלים למצות וחסידות מו\"ה... שי' און צוליב פערשידענע סיבות האט זיך אפגעהאלטען דער ענטפער ביז איצטער.</p>\n<p>בנוגע די פראבלעמען וואס איר שרייבט אין אייער בריף, איז פון איצטער אן און ווייטער, דארפט איר זיך אריינטראכטען אין דעם אמת, - וואס עס איז אנווענדבאר פאר <b> יעדער</b> אידן - אז בתוך כלל ישראל איז <b>יעדער</b> פון אונז א שליח פון השם יתברך בורא עולם, דורכפירן א הייליקע ארבעט אין עולם הזה, וואס די עבודה אין אלגעמיין איז שוין אנגעוויזען געווארען אין משנה, אני נבראתי לשמש את קוני, און ווי דאס קען געטאן ווערען, איז דער דין אין שולחן ערוך, אז - בכל דרכיך דעהו, (או\"ח סי' רל\"א) אז יעדער זאך וואס מ'מעג און מ'טוט, קען מען עי\"ז דעהו, מיט א גוטער כוונה,</p>\n<p>און כדי צו וויסען וואס מען מוז טאן און וואס מען טאר ניט טאן, איז דאס אנגעוויזען געווארען בתורתנו תורת חיים, פון דעם איז פארשטענדליך אויך, אז די שליחות וועלכע איז געגעבען יעדערען פון אונז איז ניט קיין איינהייטליך גלייכע, וויילע יעדערער דארף אויסניצען זיינע כחות און מעגליכקייטען, און לויט די כחות און מעגליכקייטען, אונטערשיידען זיך אויך די שליחות'ן.</p>\n<p>און היות השם יתברך האט מצליח געווען דעם אידישן קהל אין... אז פון א געוויסער צייט איז דארט געגרינדעט געווארען די ישיבת... איז איינע פון די הויפט שליחות'ן פון יעדער אידן וואס געפינט זיך אין... צו טאן אלץ וואס מעגליך, ניט נאר צו פארשטארקען די ישיבה נאר אויך זעהן אז זי זאל פארגרעסערט ווערן מער און מער, און זי זאל קענען ארייננעמען און ארומנעמען דעם גאנצען יוגענט און קינדער, און דורך זיי אויך בעאיינפלוסען די עלטערן מיט אידישע ווארימקייט און אידישע ליכטיקייט.</p>\n<p>און אין איינקלאנג מיט דאס אויבען געזאגטע, דארפט איר זיך צונויפריידין מיט דער הנהלה פון דער ישיבה, וואס איז דאס בעסטע און אין וועלכען אופן, וואס איר קענט לייסטען פאר דער ישיבה,</p>\n<p>און אז איר וועט זיך <b>אריינווארפען</b> אין דער ארבעט, - (און זעלבסט פארשטענדליך אז צוליב דער נוצליכקייט פון דער ארבעט זעלבסט, דארף דאס געטאן ווערען אין א אופן, אז עס זאל ח\"ו ניט שאדען צום געזונט, און אויך צו אנהאלטען די פרנסה ענינים וואס השי\"ת וועט אייך געבען, ווארום השי\"ת גיט גענוג כחות אין צייט אז מען זאל קענען טאן זיין שליחות, מיט א געזונטען גוף ובפרנסה כדבעי), - איז דענסטמאל אלס שליח פון בורא עולם, און ווי א זעלנער אין מיליטער נעמט איבער אויף זיך די אויבערמאכט זיינע פריוואטע זארג און פארזארגונג, אזוי אויך זייענדיק אין דינסט פון השם יתברך, וועט פון אייך באזייטיגט ווערן די ענינים וועלכע שאפען אייך זארג.</p>\n<p>אום צו אפווישען דעם רושם פון דעם עבר, דארפמען פאר צען אידען בעטען מחילה בא די, וואס איר האט אפגעלאזט דעם שידוך - ניט אנגעבענדיק זיי אויב די שולד איז פון אייער זייט אדער ניט אינגאנצען פון אייער זייט, אויך גלייך געבען בודק זיין אייערע תפילין און די ציצית פון טלית גדול וטלית קטן, און די מזוזות בא אייך אין דירה, און אין די חדרים אדער אפיס פון פעקטארי די מזוזות, אויב מען עסט דארט אמאל, און איר זאלט זעהן צו שלאפען אין א טלית קטן, און יעדער וואכען טאג פארן דאוונען אין דער פריה און פאר תפלת מנחה, געבען א פאר קליינע מטבעות אין א צדקה פושקע, און טאן דאס ביז קומענדען ראש השנה הבע\"ל, און יעדער טאג נאכן דאוונען זאגען דעם שיעור תהלים, ווי פארטיילט אויף די טעג פון חדש.</p>\n<p>זעלבסט פארשטענדליך, אז א חוץ דאס אויבען געזאגטע דארפט איר האבען א קביעות עתים פון לערנען, און דער לערנען חסידות איינגעשלאסען, ונכון יהי' לבו בטוח בבורא עולם ומנהיגו, אז ער איז משגיח אויף אייך בהשגחה פרטית און היטן אייך אין אלע אייערע ענינים, און האט גארניט וואס צו איבערטראכטען, און השי\"ת זאל העלפען אז בקרוב ממש זאל איך באקומען פון אייך גוטע בשורות אין דאס אלץ אויבען דערמאנטע.</p>\n<p>בברכה.</p>"],[1200870010,"ד'רפ*\n\n<p>ב\"ה, א' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ מלאכתו מלאכת שמים<br>\nמו\"ה זאב צבי שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מר\"ח אדר והקודם לו, שנתארך בדרך הילוכו, ובודאי ניצל ימי הסגולה דהיו\"ט ומועדים כדי להוסיף בתלמידיו רוח יראת שמים ואהבת שמים והליכה בדרכי תורת החסידות והנהגותי' והשי\"ת יצליחו.</p>\n<p>מוסג\"פ המחאה להוצאתו הפרטית.</p>\n<p>בברכה לבשו\"ט,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<p>בהערתו א) מ\"ש לחילוק דרז\"ל י\"א מיכאל הציל את לוט וי\"א רפאל (ב\"מ פו, ב.</p>\n<p>ב\"ר פ\"נ, ב). - אפ\"ל דמתאים לשני דרז\"ל י\"א דלוט צדיק הי'. וא\"כ שייך למיכאל המקריב נשמתן של צדיקים (עי' חגיגה יב, ב. ועוד. זח\"א קז, ב. מדרש הובא ברש\"י יט, יז) ולמ\"ד רשע הי' שייך לרפאל תשובה שמביאה רפואה (עייג\"כ זח\"ב קמז סע\"א). ולכן בפירש\"י דלוט רשע הי' ורפאל המצילו.</p>\n<p>ב) מש\"כ דויוציאוהו וגו' קאי אמלאך שנתהווה ממצות דלוט - אאפ\"ל כן כי אמר קרא שני המלאכים בה\"א הידיעה.</p>\n<h4><i><b>ד'רפ*</b></i></h4>\n<p><b> מו\"ה זאב צבי שי</b><b>':</b> ובר, ירושלים. אגרות נוספות אליו - לעיל חי\"ב ג'תתנב, ובהנסמן בהערות שם.</p>"],[1200870011,"ד'רפא\n\n<p><i> [ד' אייר, תשט</i><i>\"</i><i>ז</i><i>]</i></p>\n<p>הרב גרליק, כפר חב\"ד</p>\n<p>מאשר מברקו, התענית ביום החמישי עד לאחר חצות היום לגדולים בריאים.</p>\n<p>ומהנכון שכן יעשו גם הגדולים בריאים אשר בכל מוסדות חנוך וישיבות חב\"ד שבאה\"ק תובב\"א. והשי\"ת ישמרם כל אחד ואחת כדברי רבנו הזקן במדת הרחמים שהיא גדולה ממדת החסד נחלה בלי מצרים מבריח מן הקצה כו'.</p>\n<p>בברכה,</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ד'רפא</b></i></h4>\n<p><b> הרב גרליק</b><b>:</b> אגרות נוספות אליו - לעיל חי\"א ג'תקסד, ובהנסמן בהערות שם. חי\"ב ד'קמו. לקמן ד'שפא. ד'תקח*. ד'תרנא.</p>\n<p><b> התענית ביום החמישי:</b> בתום השבעה לרצח חמשה מתלמידי ביה\"ס למלאכה בכפר חב\"ד, יחד עם מדריכם הת' שמחה זילברשטרום, באור ליום ב' דר\"ח אייר, בעת עמדם בתפלת שמונה עשרה של תפלת ערבית, הי\"ד.</p>\n<p>על הנ\"ל ותוצאותיו ראה בארוכה במבוא.</p>\n<p>בהמשך לזה ראה לקמן אגרות ד'רצב. ד'רצז. ד'שג-ד'שיב. ד'שיח-ט. ד'שלא. ד'שלד-ו.</p>\n<p>ד'שמה. ד'שסט. ד'שעז-ח. ד'ת. ד'תא. ד'תד. ד'תכז. ד'תמא. ד'תעג. ד'תקו. ד'תקיב.</p>\n<p>ד'תרטו.</p>\n<p><b> כדברי רבנו הזקן</b><b>:</b> ראה לקמן אגרת ד'שז, ובהנסמן בהערות שם.</p>"],[1200870012,"ד'רפב\n\n<p>ב\"ה, ד' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה יחיאל מיכל יהודא ליב שי'</p>\n<p> שלום וברכה!</p>\n<p>נעם לי לקרות במכתבו אודות חלוקת השמורה, אף שלפלא קצת שלא חלקו כמות יותר גדולה, ואף שבפנימיות הדברים הכמות בכגון דא אינה נוגעת כ\"כ ובפרט בעניני פסח, אשר מרובה מדה טובה וכו' שהחמץ הוא במשהו, מזה מובן שאפילו משהו טוב מועיל, בכ\"ז בהנוגע להסדרים, הרי השיעור הוא עכ\"פ כזית ובפרט כשהמקבל עדיין אינו יודע ע\"ד האיכות הבלתי תלוי' בכמות.</p>\n<p>לפלא מ\"ש שכיון שזהו בין הזמנים בישיבות לכן נתמעט מספר המשתתפים בשיעורי דא\"ח, כי הרי אדרבה, כשהוא בין הזמנים פנוים הם יותר וביכולתם להרבות בשיעורים אלו אם במקום דעד אתה או במקום שלשם נוסעים ע\"י שיקשרום שם עם אנשים המתאימים, והרי כמו דמשהו דימים אלו נוגע ביותר, שכן הוא בגשמיות מפני שכן הוא בענינים הרוחנים, ובמילא מובן עד כמה נוגע הנ\"ל היינו שינצלו ימי הפסח בלימוד המחזק את כח האמונה, ואף שלכאורה אין הענין נוגע עתה, בכ\"ז יש עד\"ז מזמן לזמן ביומא דפגרא וכו' והדברים האמורים הנ\"ל יכולים לשמש לימוד גם אז אפילו קודם חג הפסח הבע\"ל.</p>\n<p>בודאי עושים הכנות הכי נמרצות ליום ל\"ג בעומר הבע\"ל לנצלו במדה</p>\n<p>המקסימלית, ואעורר את אנ\"ש להשתתף בהוצאות הכרוכות בזה במדה מסוימת.</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<p>בטח ממשיך וגם מוסיף בפעולות במסגרת נשי ובנות חב\"ד.</p>\n<h4><i><b>ד'רפב</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ב ע' 157 והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> מו\"ה יחיאל מיכל יהודא ליב שי':</b> זלמנוב, בני ברק. אגרות נוספות אליו - לעיל חי\"ב ג'תתקלא, ובהנסמן בהערות שם. לקמן ד'תפג. ד'תקעג.</p>"],[1200870013,"ד'רפג\n\n<p>ב\"ה, ד' אייר, תשט\"ז</p><p>ברוקלין.</p><p>מר שלמה שי' המכונה ד\"ר אידלברג</p>\n<p> שלום וברכה!</p>\n<p>בנועם קבלתי מכתבו מכ\"ח ניסן ביחד עם ספרי תשובות רבנו גרשון מאור הגולה וכן החוברת של הד\"ר מר חיים ביינארט שי' וכבקשתו יאשרו להנ\"ל קבלת החוברת, ותודה לכ' על טרחתו בזה.</p>\n<p>כפי רשיון הזמן להיות[ו] מילי דחביבותא עברתי בין דפי הספר תשובות רגמ\"ה, אשר ניכר שהשקיע בו כ' יגיעה ועמל רב, ויה\"ר שיקוים בו מאמר רז\"ל גדול תלמוד שמביא לידי מעשה, וכיון שהתלמוד וגם המעשה ארוכה מארץ מדה ורחבה מצותך מאד, הרי ככל שיהי' ההווה טוב בשניהם, יש עוד מהלך בלי גבול ואין סופי להוספה ולטוב עוד יותר, ובטח למותר לעוררו לנהוג טוב עין שתהי' עינ[ו] טובה בשל אחרים להשפיע גם עליהם בלימוד תורתנו לימוד ע\"מ ללמד לשמור לעשות ולקיים, ובפרט שדוקא בתקופתנו זו נראית התעוררות לחפש אחרי האמת לאחרי האכזבה בהא[י]דאלים של המפלגות השונות ועמים אחרים, ואין לך שע[ת] הכושר כשעה זו, ובפרט למי שחונן בכח השפעה על הסביבה.</p>\n<p>בטח שמע המסופר בפי העולם, וכבר נדפס בכ\"מ בשם גדול אחד, הטעם דדוקא רבנו גרשון נקבע עליו התואר מאור הגולה, משום דשתי התקנות של רבנו גרשון הן מאירות לישראל בגלות, וזהו מאור הגולה \"כי הוא תיקן שלא לישא אשה על אשתו, ושלא לגרש בע\"כ, וא\"כ לא נירא שיחליף השי\"ת אותנו באומה אחרת, כי אין לגרש בע\"כ, וכמאמר הנביא איזה ספר כריתות אמכם, ובכן בטוחים אנחנו במה שכתב והייתם לי סגולה וגו' שלא יבחור עוד אחרת, כי אין לישא אשה על אשתו כביכול וזה וארשתיך לי לעולם\".</p>\n<p>אשר בזה ג\"כ נקודת הטעות של חכמת ישראל בתקופה הידועה, שהגישה היתה ע\"ד חקירת כתב היתדות, חוקי חמורבי ותרבות מתה, ובמילא מובן שאי אפשר הי' לבוא למסקנות נכונות, כיון שפשוט שדבר חי גישה שונה נדרשת בשבילו, וגם הכנה אחרת.</p>\n<p>אף שלכאורה ע\"פ שכל אין שני הענינים שייכים זה לזה, אבל רואים במוחש את ההיפך: וכנרמז ג\"כ בפתגם חז\"ל קצר, אשר מפני מה הלכה כמותו, לא מפני העמקות המיוחדת והבנה והסברה יותר מאשר לחבירו, אלא מפני שהוי' עמו (סנהדרין צג, ב) עד שאפילו בקדושי ישראל עצמן אמרו אף שאלו ואלו דא\"ח, הנה הזוכה לקבוע הלכה כמותו הם אלו שנוחים ועלובים אף שהצד השני חריפי טפי (עירובין יג, ב) ועפ\"ז מובנת הוראת רז\"ל התמוה לכאורה, אשר לימוד התורה צ\"ל לאחר התפלה (ברכות ה, ב) אף שהתורה היא תורת חיים ותורת אמת, ונתבאר בלקוטי תורה לרבנו הזקן בעל התניא והשו\"ע, ספר דברים צו, ג.</p>\n<p>בברכת הצלחה בכל האמור ולבשו\"ט בזה.</p>\n<h4><i><b>ד'רפג</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 340 והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> החוברת של הד\"ר מר חיים ביינארט:</b> ראה לקמן אגרת ד'תסג.</p>\n<p><b> אשר בזה</b><b>:</b> לכאורה נמשך לקטע שלפני פניו.</p>"],[1200870014,"ד'רפד\n\n<p>ב\"ה, ד' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה חיים זוסיא שי'</p>\n<p> שלום וברכה!</p>\n<p>לאחרי שתיקתו הארוכה נתקבל מכתבו שהתחיל לכותבו ג' אדר, בו כותב על איזה מהענינים, ולפלא שהשמיט ענינים אחדים, ואפשר הטעם מפני שאחרים התעסקו בזה, וכבר ידועה בקשתי לאנ\"ש אשר נוסף על מה שכותבים הם מצדם בהנודע להם, נכון שיעוררו לשאר העסקנים שיודיע כאו\"א במקצוע שלו...</p>\n<p>במ\"ש אודות הנחיצות להרבות מספר התלמידים בתומכי תמימים ובכלל במוסדות חינוך חב\"ד, הוא נחוץ עוד הרבה יותר מאשר משערים, וכבר כתבתי כ\"פ בזה שצריכים אריינחאפען, כי כעבור זמן קצר יחפשו תלמידים-ות מיט ליכט, און מען וועט רייסין זיך איבער זיי, ובמילא מאבדים עתה הזדמנות להוסיף מאות תלמידים במוסדות חינוך חב\"ד, ורק מפני רשלנות והעדר שימת לב אפילו לענינים הפשוטים ביותר מודגשים ומובלטים.</p>\n<p>במ\"ש אודות שאלת את\"ה, כבר ענו ע\"ז, ויה\"ר שיבוא לפו\"מ. תקותי אף שאינו מזכיר עד\"ז, שעשו פאטא מכנוס דעניני מל\"ח, וכן נרשמו הדבורים או עכ\"פ ירשמו אותם עתה, ובמילא יוכלו לפרסם עד\"ז באופן המתאים ולאחרי שאראה החומר ואקבל הצעות עד\"ז, אפשר כדאי להדפיסו שיהי' בציור חוברת או להדפיס בבטאון או בקובץ דכאן...</p>\n<p>מבהיל ומצער מה שמתארך כ\"כ ענין בניית המקוה, ואיני יודע מה עוד אפשר לעשות בזה.</p>\n<p>במ\"ש אודות עבודתו הוא ביחוד הנה צריך הי' להתעסק ראשו ורובו בענין ההפצה, אבל ביחד עם זה לעורר את כל השייכים לעסקנות הדרושה ומתאימה בכל שאר הענינים, והתעוררות כדבעי פירושה, אשר כעבור זמן קצר מההתעוררות באים ושואלים ודורשים מה נעשה בזה, ולמחר עוה\"פ ולמחרתיים עוד הפעם, ואשר אז סוכ\"ס פועלים.</p>\n<p>הפ\"נ המוסגר במכתבו יקרא בעת רצון על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, ויהי רצון שיבשר טובות.</p>\n<p>בברכה</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ד'רפד</b></i></h4>\n<p><b> מו\"ה חיים זוסיא:</b> ווילימובסקי, תל-אביב. אגרות נוספות אליו - לעיל חי\"ב ג'תתפ, ובהנסמן בהערות שם. לקמן ד'תק.</p>\n<p><b> שאלת את\"ה:</b> איגוד תלמידי הישיבות.</p>\n<p><b> כנוס דעניני המל</b><b>\"</b><b>ח</b><b>:</b> ביום א' דחוה\"פ התקיימה בכפר חב\"ד אסיפה רבת משתתפים מטעם הסניף הארצישראלי של \"מרכז לעניני חנוך\" - לחפש דרכים איך להפיץ מעיינות החסידות חוצה, כמסופר ב\"בטאון חב\"ד\" חוב' יא ע' מה.</p>\n<p><b> בניית המקוה</b><b>:</b> בכפר חב\"ד. ראה גם לעיל חי\"א ג'תצח. חי\"ב אגרת ד'רעא. לקמן ד'שיח.</p>\n<p>ד'תקח*. ד'תרנא. ד'תשלד.</p>\n<p><b> בענין ההפצה:</b> של ספרי קה\"ת. ראה לעיל חי\"ב אגרת ג'תתפ.</p>"],[1200870015,"ד'רפה\n\n<p>ב\"ה, ד' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ כו'<br>\nמו\"ה מנחם זאב שי' הלוי</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מא' ובדר\"ח אייר עם המוסגר בהם, וכיון שבא שוב פעם בקישור מכתבים עם הריא\"ז שי' מרגלית, כדאי הי' לעוררו אשר בהקדם יתפרסם באה\"ק ת\"ו מכתב מבוסס בשלילה מוחלטת של הסברות המבהילות של הרב הרוצה להתיר פינוי הקברים וכאילו זהו ע\"פ הזהר וכתבי האריז\"ל כו' ומובן שמכתב השולל צ\"ל בציונים ומראה מקומות כו' וכו'...</p>\n<p>מכתבו שרוצה להתיר נדפס בקול תורה המתפרסם בירושת\"ו ובודאי נודע שם לכל הרוצה לדעת ובאמת פלא שע\"ע לא הדפיסו המענה ע\"ז כדרוש.</p>\n<p>ת\"ח על הבשו\"ט מאלו שכתב פ\"נ אודותם כן יצליחו השי\"ת לבשר טובות תמיד כל הימים וגם בהנוגע לעצמו ולב\"ב ולמושפעיו שיחיו.</p>\n<p>בברכה לבשר טוב בכל האמור.</p>\n<h4><i><b>ד'רפה</b></i></h4>\n<p><b> מו\"ה מנחם זאב שי':</b> גרינגלס, מונטריאל. אגרות נוספות אליו - לעיל חי\"ב ג'תתטז, ובהנסמן בהערות שם. לקמן ד'תכג.</p>\n<p><b> שבא שוב פעם:</b> ראה לעיל חי\"א אגרות ג'תקנא. ג'תשמא.</p>\n<p><b> פינוי הקברים</b><b>:</b> בהמשך לזה - לקמן אגרת ד'תכד.</p>"],[1200870016,"ד'רפו\n\n<p>ב\"ה, ד' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"ט ניסן, כבר ידוע ומבואר בכ\"מ שגירוש הרע ברוחניות הוא ע\"ד מ\"ש מעט מעט אגרשנו מפניך ובפרט בדורנו אשר צדיקים מועטים הם והלואי שיהיו במדריגת בינונים אשר בהנוגע אליהם האריך רבנו הזקן בתניא פרק כ\"ז ואילך, שאדרבה צריך לשמוח, והעצבות בזה הוא מפני שאינו מכיר מקומו כו' כי זאת היא מדת הבינונים ועבודתם, וכשילמד פרק זה בהתבוננות הדרושה אליבא דנפשי' יראה במוחש שהמצב רוח שלו אודותו כותב הוא מתחבולות היצה\"ר למונעו ח\"ו מעבודת השי\"ת מתאים למצבו, וירבה בהתמדה ושקידה בלימוד תורתנו הק' ובקיום מצותי' בהידור, וכלך מדרכי שקו\"ט שכותב במכתבו זה, ויזכהו השי\"ת להשפיע גם על הזולת למשכו לחסידות בכל עניני' שעל ידי זה תתרבה במדת השי\"ת שהיא מדה כנגד מדה אלא שכ\"פ ככה, בהמצטרך לו.</p>\n<p>בברכה</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>"],[1200870017,"ד'רפז\n\n<p>ב\"ה, ד' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>נעם לי לקבל מכתבו מכ\"ה ניסן עם הקטע המוסגר בו, ומה שכותב שכנראה פירשתי דבריו שמתענה עד חצות לילה, לא כן הוא, שהבנתי שמתענה עד חצות היום, ובכל זה לא זוהי דרך החסידות וכמו שכתבתי לו במכתבי הקודם, וגם כתבתי במה אפשר להחליף התעניות ואדרבה וכו' ותקותי שיתנהג כן ויהי' בהצלחה. מובן אשר האמור לעיל אודות התעניות הוא רק בתעניות שרוצים להוסיף על דעת עצמו ולא התעניות שמצווים בהם בשולחן ערוך, ופשוט.</p>\n<p>במה שכותב אודות הרב גולדשמיד שי', הנה עד כמה שנחוץ ונכון ללמוד תורת החסידות עם אחד בתור רב, הנה נחוץ ועוד יותר למצוא אחדים ועכ\"פ אחד שיכול להסתדר עמדו בלימוד בתור חבר, ועל כל פנים תלמיד חבר, וכדיוק חכמנו ז\"ל במשנה, עשה לך רב וקנה לך חבר, היינו שלרכוש חבר צריך להיות על דרך קני' שבא על ידי בזבוז ממון, וכן נחוץ לבזבז כחות ובלבד לרכוש חבר. בהזדמנות אפנה, גם להרב גולדשמיד שי' אבל ביחד עם זה הנה נכון במאד מאד שימצא חבר ע\"ד הנ\"ל, ואז תתרבה ההצלחה בלימודו.</p>\n<p>לפלא שאינו כותב במה מתעסקת זוגתו תחי' ואשר ממשיכה בשטח החינוך הכשר, ויה\"ר שתצליח להחדיר יראת שמים אמיתית בהתלמיד'.</p>\n<p>בברכה להצלחה בכל האמור לעיל, ולבשורות טובות בהנוגע לעצמו לזוגתו ולכל המשפחה שיחיו.</p>\n<h4><i><b>ד'רפז</b></i></h4>\n<p><b> שמתענה עד חצות</b><b>:</b> לעיל חי\"ב אגרת ד'קצו.</p>"],[1200870018,"ד'רפח\n\n<p>ב\"ה, ד' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>אף שחזקה שליח עושה שליחותו ובפרט כשקשור בסדרי המלוכה כעניני הדואר, בכ\"ז מאשר הנני בפירוש קבלת מכתבו עם המוסגר בו אשר קראתיו בער\"ח זיו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, ויה\"ר שבקרוב ממש תתמלאנה משאלות לבבו ולבב זוגתו תי' לטובה בהנוגע לשידוך עבור בתם שתליט\"א, ויה\"ר שיהי' שידוך חסידותי בדרך אבותיו ואבות אבותיו ובאורח חיים מתאים לרצונם ויראו מהם רוב נחת מתוך בריאות והרחבת הדעת.</p>\n<p>וכבר ידוע המבואר בכ\"מ אשר אייר* הוא ר\"ת המרכבה (מתאים לדרוש רז\"ל זיו מלשון וע\"ש זיותני עולם) וכמבואר עבודה בדרך מרכבה בכ\"מ.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'רפח</b></i></h4>\n<p>*) דבי' קיימינן. וראה זח\"ג קיז, ב: יברך כו' אהרן דאינון מברכין כו' בית אהרן הכי נמי נשין (דילהון) כו' חודש השני דאיהו זיווא דברכאן דעלמא דמיני' נפיק כו' דזיווא דכולא נפיק מיני' כו'.</p>\n<p><b> ר\"ת המרכבה:</b> אברהם יצחק יעקב רחל. ראה גם לעיל ח\"ג אגרת תעט.</p>\n<p><b> מתאים לדרוש רז</b><b>\"</b><b>ל</b><b>:</b> ראה גם לעיל חי\"א אגרות ג'תכו. ג'תלו. ג'תנה.</p>"],[1200870019,"ד'רפט\n\n<p>ב\"ה, ד' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מפני חג הפסח בו כותב שמקבל עליו ללמוד בהתמדה ובשקידה ולשמור סדרי הישיבה כאן (אף שלכאורה סותר את עצמו לתחלת מכתבו שמודה שאינו שומר סדרי לימוד הישיבה ובפרט בזמן האחרון כו' והרי חוששני שגם כשיסע משם יסע גם היצר הרע ובטח ימשיך בהסתות שלו גם אחרי זה, ואם בארץ אשר עיני ה' אלקיך בה מראשית השנה ועד אחרית שנה, אינו משתדל נגדו כדבעי, הנה מה יהי' בחו\"ל? וכבר נודע פסק הרמב\"ם (הל' מלכים פ\"ה) שאסור לצאת לחו\"ל, וכשמתירים מפני תלמוד תורה, הרי צ\"ל התלמוד באופן שהתורה אומרת שזהו ת\"ת, בכל זה) אם באמת ובתמים והחלטה תקיפה ביותר יקיים את האמור, יכול להתחיל ההשתדלות בזה, והשי\"ת ינחהו באופן הטוב לפניו בגשמיות וברוחניות גם יחד.</p>\n<p>בברכה.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>"],[1200870020,"ד'רצ\n\n<p>ב\"ה, ד' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>לאחר שתיקתו הארוכה נתקבל מכתבו ממוצש\"ק, ויה\"ר שבעתיד הקרוב יבשר טוב מקירוב הלבבות והאחדות שביניהם ההולכת וגדולה וכמים הפנים, וכשמוותרים על מדות עצמו ועניני עצמו כן הוא לב האדם לאדם שגם הזולת מתחיל להרגיש באופן כזה ומתקרבים איש אל רעהו ביותר, שאז מתקיים הבטחת תורתנו הק' שהשלום הוא כלי מחזיק ברכתו של הקב\"ה ברכה בלי גבולית ואין סופית, כיון שמקורה הוא הבלי גבול האמיתי שבמילא נמשכה תוספת ברכה בהפעולות והמושפעים, ויה\"ר שיבשר טוב בזה בקרוב ממש.</p>\n<p>בברכת הצלחה ולבשו\"ט בכל האמור.</p>"],[1200870021,"ד'רצא\n\n<p>ב\"ה, ד' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... ומ\"ש אודות פירוד הלבבות, הנה כ\"פ כתבתי, שיעיינו בדרושי רבנו הזקן והנשיאים שלאחריו, ובמילא ידעו מאין בא פירוד הלבבות, וכן יראו עד כמה נוגעים הדברים, ואם נוגע זה בשעת שלום בתכלית, עאכו\"כ וכו' וכשישנם שני צדדים הרי בעוה\"ז כמעט אי אפשר שיהי' אחד צודק מאה אחוז והשני אשם מאה אחוז, אלא כאו\"א אשם עכ\"פ במקצת, ובפרט ע\"פ המבואר בחסידות פירוש הכתוב דכמים הפנים לפנים וכו', וברור הדבר אשר עד עתה השחיתו כמה טוב ע\"י העדר דקירוב הלבבות בשביל ענינים דכבוד המדומה וכו' ואל יטעו את עצמם שזהו מפני יראת שמים או מפני שפיץ חב\"ד כו' כיון שרבנו הזקן וכ\"א מהנשיאים בדורו כתבו להיפך, וכמבואר בדרוש החלצו מרבנו הזקן כו' עד למאמר נשיאנו כ\"ק מו\"ח אדמו\"ר... הנדפס בהשלמה לקונטרס החלצו, יעו\"ש, ודא עקא אשר למרות שמתעוררים, הנה ישנם אחדים אשר לפעמים אפילו לאחרי ההתעוררות מחליפים הקוים, ומה שצריכים לעשות תשובה על ענינים שלו, ולדון את חבירו לכף זכות עד כדי כך, שיקוים והוי שפל רוח בפני כל האדם, וכלשון רבנו הזקן והוי באמת לאמיתו (וכמבואר במקום אחר שהביא בזה רבנו הגירסא האדם בתוספת ה\"א), והם עושים ההיפך, שמצוים על אחרים בהתלהבות שיעשו תשובה, ובהתלהבות לא פחותה מזה מלמדים זכות על עצמם ובהידור ע\"ד הכתוב על כל פשעים תכסה אהבה, ותובעים בהסביבה שיהיו שפל רוח נגדם, וכבר ידוע דבר משנה שבענינים שבין אדם לחבירו, העלפט ניט דאס וואס מען עסט פסח דוקא קיילעכדיקע מצה שמורה, און וואס מען איז אוף שבועות א גאנצע נאכט וכו', עד שירצה את חבירו, אשר אז מועילים ענינים אלו.</p>\n<p>ומסיימים בדבר טוב, אשר ע\"פ הכתוב, והביאו רבנו הזקן פסק דין הלכה למעשה בהלכות ת\"ת, שבל ידח ממנו נדח, ודאי הדבר, ויה\"ר שיהי' זה בקרוב ובחסד וברחמים, אשר בקרוב ממש יעזוב רשע דרכו ואיש און מחשבותיו, וכמובא בדרושי חתונה מאמר הצ\"צ בזה, אשר כמו רשע כפשוטו צריך לעזוב דרכו, הרי כן ממש, איש און מחשבותיו, און מלשון און וכח, [יעו\"ש בהענין, דכאשר מתפשטים בכל בית המדרש, הנה בכל מדרך רגל דוחקים עליו], ובמילא יתאחדו כולם כאיש אחד, ועי\"ז - עם נשיאינו הק' - העומדים - באופן דממוצע המחבר - בינינו ובין ה' אלקינו, והשלום ואחדות זו יגינו על כאו\"א ובני ביתו בתוך כלל ישראל כחומה בצורה, וכמ\"ש ברכנו אבינו כולנו כאחד באור פניך, ובאור פני מלך חיים.</p>"],[1200870022,"ד'רצב\n\n<p>ב\"ה, ד' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה יוחנן שי' שו\"ב<br>\nגבאי ביהמ\"ד דליובאוויטש בליובאוויטש.</p>\n<p> שלום וברכה!</p>\n<p>נעם לי לקבל הפתקא שלו ביחד עם המצורף אליו, ומוסגר בזה קבלה ממוסדות אשר על שם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע אשר באה\"ק ת\"ו, ארץ אשר ה' אלקיך דורש אותה מראשית השנה עד אחרית שנה אשר הם הן - וכדוגמתם - המגינים עלי', ועל כל המחזיק בהם ומשתדל בהוספה עליהם הן במספר התלמידים והן בשעות הלימוד הם הגורמים וממשיכים אשר ה' יבנה בית וה' ישמר עיר וגו' וכאשר פתח ההסברה בזה רבי אבא בר כהנא וביארו הדבר ר' אסי ור' אמי, אשר הסופרים ומשנים שהם הוגים ומשנים את התורה ביום ובלילה כו' (מדרש איכה רבה בתחלתו) ויה\"ר שבקרוב ממש ובחסד וברחמים יערה רוח ממרום על כאו\"א בתוך כלל ישראל ואז יראה בעיניו ובאזניו ישמע ולבבו יבין, אשר אנחנו בשם ה' אלקינו נזכיר והוא ישלח עזרתו מקדש ויקוים הבטחתו, יעננו ביום קראנו בגאולה האמיתית והשלימה.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'רצב</b></i></h4>\n<p><b> מו\"ה יוחנן:</b> גורדון, ברוקלין. אגרות נוספות אליו - לעיל חי\"ב ג'תתמד, ובהנסמן בהערות שם.</p>\n<p><b> ה' ישמר עיר וגו':</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>"],[1200870023,"ד'רצג\n\n<p>ב\"ה, ה' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מאמצע החורף, וכיון שלא קבלתי ממנו עוד ידיעות בזה, תקותי חזקה שממשיך בלימודו בישיבה ומזמן לזמן נתחבב עליו הדבר יותר ויותר, אשר בדרך ממילא מתחזקת אצלו ההחלטה להמשיך בלימודים אלו לכל הפחות משך אותו הזמן שיעצתיו במכתבי הקודם, ומה שכותב שאין בדעתו להיות רב וכיו\"ב וגם אין מוכשר לזה, הנה לא זה הי' טעמי שילמוד עוד הזמן שכתבתי לו בישיבה דוקא בכדי שיהי' רב, אלא בכדי שיהי' יהודי מתאים לתוכן תואר זה ובתקופתנו זו תקופ[ת] ערבוב ובלבול המוחות אשר שמים אור לחשך וחשך לאור, רוחות אי מצוית נגד היהדות האמיתית מנשבות בעולם, צריך כל אחד ואחת לחסן את עצמו בכל הדרוש, והמקום לזה בד' אמות של תורה ובד' אמות של תפלה, ותקותי שכשישאר בד' אמות אלו משך הזמן הנ\"ל הרי בעזר השי\"ת יוכל לעמוד איתן נגד הנחשולים אשר בחוץ ולהנהיג עצמו באורח חיים אמיתי מסורתי.</p>\n<p>בודאי מתחזק בשמירת שלשת השיעורים חומש תהלים ותניא הידועים ויש לו נוסף על זה שיעור קבוע בלימוד תורת החסידות, והשי\"ת יצליחו לבשר טוב.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'רצג</b></i></h4>\n<p><b> במכתבי הקודם:</b> דלעיל חי\"ב ג'תתקנב.</p>"],[1200870024,"ד'רצד\n\n<p>ב\"ה, ה' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה שמואל אלעזר שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מכ\"ט ניסן והקודמים לו וכן קבלת קטעי העתונים, ות\"ח ת\"ח על שימת לבו בשילוח הקטעים וכן על רוח ואופן כתיבת מאמרו בהמודיע בחום בהתעוררות כו' ובודאי גם להבא ינצל אפשריתו זו של בימת המודיע להפצת המעינות חוצה תורת החסידות הדרכותי' ומנהגי', שכל פעולה בזה הנה נוסף על שמקרבת את הגאולה וכמבואר באגה\"ק של הבעש\"ט, לכשיפוצו מעינותיך חוצה קאתי מר, הנה מקשרת היא פנימיות וסתים נשמת איש הישראלי עם הסתים דקוב\"ה וכמאמר הזוהר הק' הידוע.</p>\n<p>כבקשתו יזכירו את כל אלה שכותב אודותם בעת רצון על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, ויה\"ר שיבשר טובות בהנוגע לכאו\"א מהם...</p>\n<p>תקותי שעושים הכנות הדרושות לנצל את ל\"ג בעומר הבע\"ל במסגרת צעירי אגו\"ח. כדי לנצל במילואו האפשרי בהפצת תורת הרשב\"י בעל השמחה שנתגלתה בדורות האחרונים בתורת החסידות ובהבנה והשגה בתורת חסידות חב\"ד, והשי\"ת יזכם שיהי' בהצלחה מופלגה.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'רצד</b></i></h4>\n<p><b> מו\"ה שמואל אלעזר:</b> שאולזון, ירושלים. אגרות נוספות אליו - לעיל חי\"ב ג'תתקמו, ובהנסמן בהערות שם.</p>"],[1200870025,"ד'רצה\n\n<p>ב\"ה, ה' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מאז - שנתאחר דרך הילוכו - בו כותב אשר המנהג במשפחתם להשתדל לקיים מרז\"ל בן שמונה עשרה לחופה וכיון שכבר עבר גיל זה, מציעים לו נכבדות ועומד בספק אם להתעסק בזה כיון שרוצה ללמוד במנוחה עוד משך זמן.</p>\n<p>לדעתי נכון שיתענין בהאמור ובודאי בתנאים דירושלים עיה\"ק ת\"ו יוכל ללמוד גם לאחרי החתונה משך זמן חשוב, וכבר ידוע עד כמה הפליגו רז\"ל במעלת לימוד תורה בטהרה, ומה שחושש שהנשואין יפריעו בהתמדת הלימוד, הרי אין זה תלוי אלא ברצונו, ואם ירצה באמת אזי יצליח בלימוד תורת הנגלה ותורת החסידות קודם החתונה וגם לאחרי החתונה, ויזמין לו השי\"ת שידוך המתאים לפניו בגשמיות וברוחניות גם יחד עד שהענינים אשר נגדו תעזור לו להפכם לטוב.</p>\n<p>בודאי למותר לעוררו על ההכרח הכי גדול לקבוע לימוד בכל יום בפנימיות התורה אשר בדורנו זה נתגלתה בתורת החסידות, והוא נוסף על שלשת השיעורים בחומש תהלים ותניא הידועים, ובפרט שנמצא הוא בעיה\"ק ירושלים ת\"ו יראה שלם שלימות היראה, אשר אי אפשר לבוא אלי' כ\"א ע\"י התבוננות בגדולתו ית' הבאה ע\"י הלימוד בתורת החסידות וכנראה במוחש, והשי\"ת יצליחו לבשר טוב בכל האמור וכן מהשפעתו על חבריו שיחיו לקרבם לתורה ולמאור שבתורה זוהי תורת החסידות הדרכותי' ומנהגי'.</p>\n<p>בברכה.</p>"],[1200870026,"ד'רצו\n\n<p>ב\"ה, ה' אייר תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג וו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה דוד<br>\nשי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מיום הראשון, ונעם לי לקרות בו ע\"ד השיעורים בבית הכנסת.</p>\n<p>וארשה לי להעיר בזה, אשר בכל הזמנים ובכל המקומות מוכרחת היתה ידיעה ובמילא שיעור לימוד בהלכות הצריכות בחיי היום יומי, וכמו שהאריך בזה רבנו הזקן בעל השו\"ע והתניא בהלכות תלמוד תורה, ובפרט בזמננו ומדינתנו זו אשר על הבית הכנסת למלאות תפקיד של בית המדרש ולא רק בלימוד תורה לשמה אלא גם בהנוגע לדעת המעשה אשר יעשון ואשר לא תעשינה, ובהתאם להאמור הנה פלא שבביהכ\"נ שלהם אין שיעור כזה, ומהנכון ונחוץ וגם מוכרח שעכ\"פ מכאן ולהבא יסדרו שיעור מתאים, וכיון שזמן הלימוד לפ\"ע מוגבל הוא, הנה לדעתי - וכמ\"ש לכמה מאנ\"ש - בתחלה יש ללמוד סימנים מלוקטים מקיצור שו\"ע, כוונתי לא הסימנים על הסדר אלא לעבור פעם ושתים על הסימנים הדנים בענינים השכיחים בחיי היום יומים, ודוקא בקיצור שו\"ע ששם באים הדברים בקיצור (ואם לפעמים נצרכת הסברה ה\"ז על לומד שיעור, לאומרה בע\"פ), בכדי לנצל הזמן העומד לרשותם להלכה למעשה בפועל וכמ\"ש את האלקים ירא כו' כי זה כל האדם, היינו שצריך להיות הלימוד המביא לידי יראת אלקים ולימוד התורה המביא לידיעת המצות וגדול תלמוד שמביא לידי מעשה, ויה\"ר שיבשר טוב גם בזה נוסף על שאר הענינים שכותב אודותם.</p>\n<p>בברכה לתוספת אומץ בעבודת הקדש בבית הכנסת להחזקת היהדות בכלל</p>\n<p>ובהפצת המעינות (עד שיגיעו גם) חוצה ביחוד מתוך בריאות הנכונה.</p>\n<h4><i><b>ד'רצו</b></i></h4>\n<p><b> מו\"ה דוד:</b> ווינשסטר, שיקגו. אגרת נוספת אליו - לקמן ד'שסד.</p>"],[1200870027,"ד'רצז\n\n<p>ב\"ה, ה' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מבדר\"ח אייר עם המוסגר בו. הנה בטוחני אשר מייסד הכפר ומנהלו הוא כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע מעורר רחמים רבים השומרים ומגינים על הכפר ועל כל אחד ואחת מתושביו, וביתר שאת וביתר עז מכאן ולהבא וכלשון רבנו הזקן המועתק גם בהמברק שלי: \"במדת הרחמים שהיא גדולה ממדת החסד שבתחלה נחלה בלי מצרים מבריח מן הקצה כו'\" (עיין דרך מצותיך דף קי\"ד ע\"ב).</p>\n<p>ודא עקא כמו שכתבתי כ\"פ אשר העדר הקירוב לבבות ועוד יותר מזה פירוד הלבבות מפריע ח\"ו להמשכת הברכה והצלחה האמורה למטה מעשרה טפחים...</p>\n<p>בודאי קבל מכתבי מענה על מכתביו הקודמים שגם זה שייך להנ\"ל, ומובן שאיני בא להצדיק את הצד השני, כיון שאיני יודע פרטי הסכסוך אשר קרוב לומר שיסודו בכבוד המדומה ועכ\"פ בענינים של מה בכך ועכ\"פ שאין ערכם גדול כ\"כ עד כדי להפסיד כלשון רבנו הזקן בתניא קדישא (פל\"ב) השראת הקב\"ה וכמ\"ש ברכנו אבינו כולנו כאחד באור פניך, יעוין שם, והוא מבואר ע\"פ דרושי החלצו והאותיות המבהילות בענין זה אשר בספר המצות להצ\"צ, מצות אהבת ישראל, וברור הדבר אשר בסכסוכים כגון אלה במדה מסוימת אשמים שני הצדדים אף שחלוקים בנוגע לריבוי ומיעוט, וד\"ל... ואין הדבר תלוי אלא ברצונו כי הכחות ניתנו לו והחפץ ג\"כ ישנו כי החפץ (פנימיות הרצון) כבר נפסק אשר כל אדם מישראל חפץ באמת לאמיתו לגמרי בכל לב וכו' לדבקה בה' כו' (תניא פרק מ\"א עיי\"ש) שקליפת מדין המנגד לזה, וכמבואר בדרושים הנ\"ל, שתומשך הברכה וההצלחה למטה מעשרה טפחים ויבשרני טוב תכה\"י בטוב הנראה והנגלה.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'רצז</b></i></h4>\n<p><b> עם הפ\"נ המוסגר בו:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>\n<p><b> בהמברק שלי</b><b>:</b> דלעיל שם.</p>"],[1200870028,"ד'רחצ\n\n<p>ב\"ה, ו' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nאיש רב פעלים רא\"ש שי'</p>\n<p> שלום וברכה!</p>\n<p>איך בין געווען צופרידען צו באקומען אייער בריף פון כ\"ג ניסן אין וועלכען איר שרייבט וועגען די התועדות'ן פון די ימי הסגולה, אז זיי זיינען געווען ברוב עם בכמות און התרוממות הרוח באיכות, און השי\"ת זאל העלפען אז לויט ווי ערקלערט אין לקוטי תורה באריכות, זאל פון די מועדים לשמחה נמשך ווערען די שמחה אויף אלע טעג פון יאר, און בפרט שחג המצות יציאת מצרים וועלכעס ווערט יעדען מאל דערמאנט און בפרט שבת קדש ובפרטי פרטית בכל יום טוב וואס דאס איז דער ארויסגאנג און באפרייאונג פון עבדות לחירות, הכנה למ\"ת, וואס די הכנה דארף זי[ין] אויף דעם פאסענדען אופן צו דעם וואס מען שטרעבט, זאל יעדער איינער טאן דאס ואס עס ווענדעט זיך אן עם צו באפרייען זיך פון דאגות און טרדות, און דאס וועט מעגליך מאכען די קבלת התורה אין דעם קומענדען יום-טוב שבועות בשמחה און נאך מער בפנימיות, און דער זכות וואס איר נעמט אויף זיך חלק ההוצאות פון הפצת המעינות הדרכת תורת החסידות ותורתה (ביז עס זאל דערגרייכען אויך) חוצה, זאל בריינגען נאך מער הצלחה אין דער ליבליכער ארבעט עבודה קדושה, און מיר אלע זאלען זוכה זיין צו פייערן די אמת'ע באפרייאונג פון גלות האחרון על ידי משיח צדקנו.</p>\n<p>בברכה ופ\"ש כל המתפללים וחברי בית הכנסת שי'.</p>\n<h4><i><b>ד'רחצ</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ז ע' 457 והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> רא\"ש:</b> ר\"א שקלובסקי, פתח תקוה. אגרות נוספות אליו - לעיל חי\"א ג'תקפה, ובהנסמן בהערות שם. לקמן ד'תרט.</p>"],[1200870029,"ד'רצט\n\n<p>ב\"ה, ו' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה דובער שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מעש\"ק. נעם לי לקרות בו ע\"ד קריאת השם של בנם שליט\"א ושכיוונו לדעתי, אף שכאמור במכתבי הקודם אין נוהגים להורות בזה, ואכפול ברכתי שיגדלוהו הוא וזוגתו שיחיו לתורה ולחופה ולמעשים טובים מתוך הרחבת הדעת.</p>\n<p>במ\"ש אודות הטאנסילס וכו' הרי ע\"ד הרגיל אפילו אלו המצטננים לפעמים והסיבה היא הטאנסילס, במה דברים אמורים בימי הסתיו וחורף; משא\"כ בקיץ, ולכן לכאורה אין נוגע עתה לדון על שאלה זו, ויתייעצו בזה עוה\"פ עם הרופא שלהם, ובאם גם דעתו כנ\"ל יהי' מקום לשאלה וכתיבה עד\"ז רק בעוד כמה חדשים ובינתים הנה כל אחד ואחת מהם וכלם יחד זאלען האבען א געזונטען זומער.</p>\n<p>נהניתי מ\"ש אודות חלוקת מצה שמורה, ובמה שמסיים בענין זה שכל התחלות קשות, קשה קצת, מה הם הקישוים, כיון שזהו שלא עמל\"פ, והנקודה השני' הרי זהו התחלת הטור ושו\"ע (בהגהות רמ\"א) אל יבוש מפני המלעיגים ובפרט שהרי בתקופתנו הולכים המנגדים ופוחתים הן במספרם והן בחשיבותם.</p>\n<p>בודאי לא יסתפק בהשיעורים שכותב אלא שיוסיף עליהם כסיום מכתבו עד\"ז, ובהם שיעורים לנוער ובכלל דער ריידין ארום חסידות, שלפעמים עי\"ז עושים רבות, ובאותו ענין הוא גם עבוד תכנית מתאימה איך לנצל יום הל\"ג בעומר ובפרט שחל השתא ביום שהתלמידים פנוים מלימודי חול וכו' והשי\"ת יצליחו לבשו\"ט. ובכל הנ\"ל.</p>\n<p>וגם מפעולות זוג' תי'.</p>\n<p>בשאלתו ע\"ד מקום לימוד השיעור בדא\"ח - ידועה שיחת כ\"ק מו\"ח אדמו\"ר שטוב יותר במקום שרבים נמצאים או עוברים בו ובדוגמת עסק גשמי כו', ובודאי וועלן זיך זייטיקע ניט מישן אין בעה\"ב'טישקייט. ובאם ינסו - הרי תמיד היכולת בידו להעביר השיעור לביתו. ובטח ההפחדה בזה תספיק לבטל ההתערבות. וד\"ל.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'רצט</b></i></h4>\n<p><b> מו\"ה דובער</b><b>:</b> לוין, זונדרלנד. אגרות נוספות אליו - לעיל חי\"ב ד'קע, ובהנסמן בהערות שם. לקמן ד'תקצ.</p>\n<p><b> קריאת השם:</b> יוסף יצחק, ע\"ש כ\"ק אדמו\"ר מוהרי\"צ, אע\"פ ששם זקנו היה יצחק אלחנן - שגלוב, שנאסר ברוסיה בשנת תרצ\"ז ומאז נעלמו עקבותיו, ובאותה שעה עדיין לא ידעו בבירור אם הוא עדיין בחיים.</p>\n<p><b> ידועה שיחת</b><b>:</b> ראה לעיל ח\"י אגרת ג'קמח.</p>\n<p><b> ובדוגמת עסק גשמי</b><b>:</b> ראה גם לעיל חי\"ב אגרת ד'קי, ובהנסמן בהערות שם. לקמן ד'תמט. ד'תפז.</p>"],[1200870030,"ד'ש\n\n<p>ב\"ה, ז' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מששי באייר, בו כותב אודות הנער בן י\"ג שנה וחצי אשר יש לו הפרעות להנהגתו ביראת שמים וכו'.</p>\n<p>הנה בכגון דא היותר טוב לקיים הוראת המשנה, הוי גולה למקום תורה שאז אין החיכוכים בין הצדדים יום יום, אלא רק פעם אחת בכדי שיסכימו לנסיעתו למקום תורה, וכנראה במוחש התועלת שבהנ\"ל ובכמה פרטים ובפרט בארצוה\"ב שכבר רגיל הוא ומוצא חן בעיני הנוער לנסוע מבית הוריהם למשך זמן, ובודאי יש למצוא אנשים שיש להם השפעה על ההורים בכדי שסו\"ס יסכימו להאמור, והשי\"ת יצליח אותו לראות פרי טוב בעמלו ולעשותו ירא שמים חסיד ולמדן.</p>\n<p>בברכה לבשו\"ט בהאמור.</p>"],[1200870031,"ד'שא\n\n<p>ב\"ה, ז' אייר, תשט\"ז</p><p>ברוקלין.</p><p>מר שניאור זלמן שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מי\"ג ניסן. ובהזדמנות זו אכפול תודתי חמה על הביכלעך כת\"י מאמרי חסידות שהגיעו לידי ע\"י בנו שי' וזכות הרבים שיהנו מאור תורה הגנוז בביכלעך אלו אשר בהם גם מאמרים שלא נדפסו עד עתה, תעמוד לבנו ולכל המשפחה להמצטרך לכל אחד מהם,</p>\n<p>ומובן אשר בזה נכלל וכשיחתנו עם בנו בזה, אשר מביא הביכלעך הוא בנו וכן הוריו דודיו וכל המשפחה יהיו בין לומדי ועוסקי בתורה זו אשר כחלק מתורתנו בכלל נאמר גם בזה, גדול תלמוד שמביא לידי מעשה ובפרט שזכות אבותם וצור מחצבתם מסייעים להצלחה נוספת בזה.</p>\n<p>בפ\"ש כל המשפחה ובסיום מעין הפתיחה בתודה עבור הביכלעך ששלחו בעבר והביכל ששולח עתה.</p>\n<h4><i><b>ד'שא</b></i></h4>\n<p><b> שניאור זלמן</b><b>:</b> שמרלינג, תל אביב.</p>"],[1200870032,"ד'שב\n\n<p>ב\"ה, ז' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבך.</p>\n<p>הנה תדקדק באמירת קריאת שמע קודם שתלך לישון וכן גם בעת השינה תהי' לבוש בטלית קטן ושתבדוק הציציות שלו שכשרות הן ושמונה חוטים בכל אחת ואחת, ולפני אמירת הקריאת שמע הרי מלבד ליל שבת ולילי יום טוב, תרשום לעצמך אם חסרת מה בלימודך במשך היום שלא לשכח למלאות החסר למחר, וכשתעשה כל זה תשכב ולא תפחד ושכבת וערבה שנתך.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>"],[1200870033,"ד'שג\n\n<p><i> [ז' אייר תשט</i><i>\"</i><i>ז</i><i>]</i></p>\n<p>לכל אחד ואחת מאנ\"ש, תושבי כפר חב\"ד, המוסדות אשר שם, וביחוד בתי ספר למלאכה וחקלאות, התלמידים, המורים, המנהלים, העסקנים וההורים:</p>\n<p>תקותי חזקה, אשר בעזר השי\"ת, השומר בעינא פקיחא ומשגיח בהשגחה פרטית, תתגברו על כל מונע, תתחזקו בבנינים הפרטיים והציבוריים, תרחיבו כל המוסדות בכמות ובאיכות, ומתוך מנוחה והרחבת הדעת יתגדל ויתאדר לימוד תורתנו חומתנו, תורת חיים ודברי אלקים חיים, וקיום מצוותי' בשמחה ובטוב לבב וחי בהם, ומכפר חב\"ד יפוצו מעינות החסידות תורת ומעשי נשיאינו הקדושים עד שיגיעו גם חוצה, לקרב לאבינו שבשמים את כל אחינו בני ישראל בחסד וברחמים, ולהביא הגאולה האמתית והשלימה על ידי משיח צדקנו בקרוב.</p>\n<p>המשתתף בתפלתם ותעניתם, ומובטחני בהשי\"ת שבקרוב ממש גם בשמחתם</p>\n<p>אמתית פנימית ושלימה בגשמיות וברוחניות גם יחד.</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ד'שג</b></i></h4>\n<p>נדפסה בבטאון חב\"ד חוב' יא בתחלתה. ומועתקת באגרת המזכירות מל\"ג בעומר ולקמן ד'שט.</p>\n<p>לתוכנה ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>"],[1200870034,"ד'דש\n\n<p><i> [ז' אייר תשט</i><i>\"</i><i>ז</i><i>]</i></p>\n<p>ישיבה, לוד.</p>\n<p>במענה לשאלתם יתחילו במרץ בבנין החדש של הישיבה ובשאר הבנינים בכפר.</p>\n<p>המגבית על שם המוסדות שלמדו בהם הנרצחים הי\"ד להתפתחותם וכו'. בהתאמה עם המשרדים המתאימים יש לסדר שהתלמידים ילונו בפרדס בשמירה.</p>\n<p>בברכה,</p>\n<p><b> מנחם שנאורסאהן</b></p>\n<h4><i><b>ד'דש</b></i></h4>\n<p><b> בכפר:</b> ראה לעיל חי\"ב ד'לז, ובהנסמן בהערות שם. לקמן ד'שיט. ד'שפה.</p>\n<p><b> הנרצחים</b><b>:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>"],[1200870035,"ד'שה\n\n<p>ב\"ה, ז' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה פנחס שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מאדר\"ח אייר ושלאחריו וכן המברקים, ובודאי כבר נודע לו מכבר מהמברק ששלחתי לכפר וכן לישיבת תו\"ת, שמהם מובנת השקפתי אודות הצעה המוזרה להעתיק מלוד וכו' אבל לאידך גיסא מוכרח שיבואו תיכף בקישור עם המשרדים והאנשים המתאימים בהנוגע לתוספת שמירה, ושאלוני כאן מפני מה אין גדר תיל סביבות הכפר או זרק-אור נמצא במקום היותר גבוה בכפר, כלבים שמשתמשים בהם לשמירה וכיו\"ב, כן כדאי הי' להעלות השאלה אודות הפרדסים, כיון שכמה מקומות העירו אשר משמשים הם מקום מחבוא מקשים על החפוש.</p>\n<p>במ\"ש אודות מכ' בעתונות העולמית וכו' תמיהני גם על ההצעה בזה, כיון א) ע\"פ הנסיון שבעבר אין בזה כל תועלת <b>ממשית</b> בהנוגע לפועל; ובמכש\"כ וק\"ו שאישים מאלו שהציעו לפנות אליהם, לא שמו לב להנעשה בשנים האיומות דתש\"א וכו'. ב) יש מקום לומר שהלחץ באופן כזה, אדרבה יגדיל מדת הנצחון של הצד שכנגד. ג) והוא העיקר, שכנראה שוכחים לגמרי שישנם אלפים ואלפים תלמידים-ות בבתי ספר חב\"ד, להם כמה מורים ומשגיחים וכמו הרבנים מתוסוף, ליפסקר, פינסן וכו' שי' ופני' בעתונות הנ\"ל בודאי תגיע לשם תומ\"י ומובן החשש לענינים ח\"ו שיכולה לגרום. באופן בלתי פרסומי כ\"כ עשו כאן כמה פעולות בפני' להראשים כאן בתגובה חזקה ונמרצה; אבל לא ברשות הרבים, ומאידך גיסא בלחץ יותר חזק מאשר לחץ של עתונים וד\"ל...</p>\n<h4><i><b>ד'שה</b></i></h4>\n<p><b> מו\"ה פנחס</b><b>:</b> אלטהויז, תל אביב. אגרות נוספות אליו - לעיל חי\"ב ג'תתקח, ובהנסמן בהערות שם.</p>\n<p><b> מכתבו מאד\"ח אייר:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>\n<p><b> מהמברק ששלחתי</b><b>:</b> דלעיל ד'שג-ד.</p>"],[1200870036,"ד'שו\n\n<p><i> [ח' אייר תשט</i><i>\"</i><i>ז</i><i>]</i></p>\n<p>רב ראשי הרצוג</p>\n<p>ירושלים</p>\n<p>תודה עבור מברק כהדר\"ג והשתדלותו בעידוד תושבי כפר חב\"ד ובודאי ימשיך ויוסיף בעזר להתפתחות הכפר והמוסדות שבו ות\"ח.</p>\n<p>נפוצה השמועה שמשתדלים שכהדר\"ג ישלח הסכמה ברכה למוסדות באמריקה שגם שמם מוכיח שמתימרים להיות נושאי דגל דת ישראל ומיצגיה ומורכבים גם מבאי-כח ושלוחי שיטות הקונסרבטיבים והרפורמים בדת כגון נ.י. בארד אף ראבייס וסינאגאג קאונסיל אף אמריקה.</p>\n<p>כל ענין כהנ\"ל גם אם אפשר יהיה לבאר הנוסחה בתרי אפי יכניס במצב העכשוי כאן בלבול בדעת אלפי יהודים ועלול להמשיכם להשפעת שיטת הקונסרבטיבים והרפורמים.</p>\n<p>מהכרתי חוגים שונים ובפרט מהנוער נוכחתי שמצב הדיון כאן אודות ההשתתפות בהנ\"ל מכריח עמדה ואיסור ברור של ההשתתפות ונוגע לדורות ולארצות.</p>\n<p>בכבוד ובברכה,</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ד'שו</b></i></h4>\n<p><b> רב ראשי הרצוג</b><b>:</b> אגרות נוספות אליו - לעיל ח\"י ג'שיט, ובהנסמן בהערות שם. לקמן ד'תיד. ד'תקיט*. ד'תקנה. ד'תקפ. ד'תקפג.</p>\n<p><b> בעידוד תושבי כפר חב\"ד:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>\n<p><b> ואיסור ברור</b><b>:</b> ראה לעיל חי\"ב אגרות ד'קסב. ד'רד. לקמן ד'שי. ד'תיד. ד'תנח.</p>"],[1200870037,"ד'שז\n\n<p>ב\"ה, ח' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמו\"ה אליעזר שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מעש\"ק.</p>\n<p>תמוה ומצער איך שכל המכתבים המתקבלים מזקני אנ\"ש אשר באה\"ק ת\"ו, תוכנם - ניסה מן המערכה, וגם מכתבו זה הוא כהנ\"ל. ויתאר בעצמו באיזה מצב היו עתה עניני תורה בכלל ועניני חסידות בפרט, אם היו אוחזים בשיטה זו, בדור שלפנינו ובדור האחרון.</p>\n<p>וכבר הודעתי דעתי ברורה במברק, שאדרבה - צריך להרחיב כל הענינים בכפר חב\"ד, ואם בכל מקום ומקום, הנה לא ינום ולא יישן שומר כל אחד ואחת מישראל, עאכו\"כ בכפר חב\"ד שנתייסד ע\"י כ\"ק מו\"ח אדמו\"ר נשיא ישראל ומנהלו גם עתה. והוא הדין לישיבת תומכי תמימים בלוד.</p>\n<p>ומובן שהירוס הישיבה בלוד ע\"מ לבנותה במקום אחר, ה\"ז הירוס. ולא זו הדרך להגנה ולשמירה על התלמידים, ולפלא, שכל בני ישראל מאמינים בני מאמינים, ואנ\"ש והחסידים והתמימים הרי נתוסף בהם הענין דאמונת צדיקים. ובפרט ע\"פ המבואר במכילתא עה\"פ ויאמינו בה' ובמשה עבדו, יעו\"ש. אבל כשבא ונוגע הדבר לפועל, ובהנוגע לעצמו, הנה לפתע פתאום נשמטות מזכרונם כל הוראות רבותנו הק' בזה, הוראת רבנו הזקן, הוראת רבנו האמצעי, הוראת הצמח צדק וכו' אשר דוקא במקום זה אשר כו' מתגלית מדת הרחמים שהיא גדולה ממדת החסד שלפני' נחלה בלי מצרים ומבריח מן הקצה אל הקצה.</p>\n<p>והנה אין מעניני להפחיד ח\"ו. אבל מהמקום המשומר עתה ביותר באה\"ק ת\"ו, הוא כפר חב\"ד. והרשות בידו לפרסם דעתי זו ברורה, לכל שימצא לנכון. וגם אנ\"ש בכלל.</p>\n<p>בברכה לבריאות ולמנוחת הנפש ולבשר טוב בכל האמור.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ד'שז</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ד ע' 387 והושלמה ע\"פ צילום האגרת.</p>\n<p><b> מו\"ה אליעזר:</b> קרסיק, תל אביב. אגרות נוספות אליו - לעיל חי\"ב ב'תתקח, ובהנסמן בהערות שם.</p>\n<p><b> המכתבים המתקבלים:</b> לאחר המאורעות דלעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>\n<p><b> במברק</b><b>:</b> דלעיל ד'שג.</p>\n<p><b> הוראת רבותינו</b><b>:</b> ראה לעיל ח\"י אגרת ג'רסב. לעיל ד'רפא. ד'רצז. לקמן אגרות ד'שח.</p>\n<p>ד'שיא. ד'שיב. ד'שיח. ד'שסט. ד'שעח. ד'שפא. ד'ת. ד'תא. ד'תה. ד'תנה.</p>"],[1200870038,"ד'שח\n\n<p>ב\"ה, ח' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג וו\"ח אי\"א נו\"נ כו'<br>\nמו\"ה נחום שי'</p>\n<p> שלום וברכה!</p>\n<p>בנועם קבלתי מכתבו מיום השלישי בו כותב אשר נכנסו לדור בביתם החדש בכפר חב\"ד, ויה\"ר שיהי' משנה מקום משנה מזל לטובה ולברכה בטוב הנראה והנגלה הן בגשמיות והן ברוחניות ומתוך מנוחת הנפש והרחבת הדעת יוסיפו ככל התלוי בהם בהנוגע להתפתחות כפר חב\"ד ולהגדלתו בכל הענינים מתאים לרצון מיסדו ומנהלו הוא כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע. ומובן אשר בכלל הנ\"ל הוא התעסקות בהענין הכי גדול וחשוב הוא הסמינר לבנות, ומדתו של הקב\"ה מדה כנגד מדה אלא שכ\"פ ככה להרבות הצנורות וגם הכלים של כל אחד ואחת מתושבי הכפר חב\"ד ובמילואו וכמ\"ש והוא יכלכלך הרחב פיך ואמלאהו. ובודאי למותר לעוררו להסביר לכל מושפעיו בכפר חב\"ד דברי רבנו הזקן אשר עתה הזמן שיושפע שם ממדת הרחמים נחלה בלי מצרים מן הקצה אל הקצה.</p>\n<p>בברכה ובפ\"ש כל תושבי הכפר שליט\"א כ\"א ואחת הקטנים עם הגדולים - יוסף ה' עליהם - ה' עליהם יחיו.</p>\n<h4><i><b>ד'שח</b></i></h4>\n<p><b> מו\"ה נחום:</b> טרבניק, כפר חב\"ד.</p>\n<p><b> דברי רבנו הזקן</b><b>:</b> ראה אגרת שלפנ\"ז, ובהנסמן בהערות שם.</p>"],[1200870039,"ד'שט\n\n<p>ב\"ה, ח' אייר, ה'תשט\"ז</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצרכי ציבור<br>\nענף עץ אבות וכו' הרש\"ז שי'</p>\n<p> שלום וברכה!</p>\n<p>באשר כותב אני ברוב צער בקשר ובהמשך להמאורעות בכפר חב\"ד ולבי לבי על חלליהם, אפשר שיימצא במכתבי בטוי שיוצא מכפי הרגיל, אבל אין אדם נתפס על צערו, וכ' בטח יבין לשיחי.</p>\n<p>בודאי ידוע לכ' ע\"ד המברק ששלחתי אתמול לכפר חב\"ד, וז\"ל:</p>\n<p>\"לכל אחד ואחת מאנ\"ש, תושבי כפר חב\"ד, המוסדות אשר שם, וביחוד בתי ספר למלאכה וחקלאות, התלמידים, המורים, המנהלים, העסקנים וההורים: תקותי חזקה, אשר בעזר השי\"ת, השומר בעינא פקיחא ומשגיח בהשגחה פרטית, תתגברו על כל מונע, תתחזקו בבנינים הפרטיים והציבוריים, תרחיבו כל המוסדות בכמות ובאיכות, ומתוך מנוחה והרחבת הדעת יתגדל ויתאדר לימוד תורתנו חומתנו, תורת חיים ודברי אלקים חיים, וקיום מצוותי' בשמחה ובטוב לבב וחי בהם, ומכפר חב\"ד יפוצו מעינות החסידות תורת ומעשי נשיאינו הקדושים עד שיגיעו גם חוצה, לקרב לאבינו שבשמים את כל אחינו בני ישראל בחסד וברחמים, ולהביא הגאולה האמתית והשלימה על ידי משיח צדקנו בקרוב.</p>\n<p>המשתתף בתפלתם ותעניתם, ומובטחני בהשי\"ת שבקרוב ממש גם בשמחתם</p>\n<p>אמתית פנימית ושלימה בגשמיות וברוחניות גם יחד - מ.ש.\"</p>\n<p>מהנ\"ל השקפתי ברורה בהנוגע לתושבי הכפר. אבל עד כמה יפעול המברק ודברי התעודדות להרגיע הרוחות שנזדעזעו בעטיו של האסון הנורא, תלוי בעיקר במעשה, כיון שאין כאן שאלת הטבת הנוחיות, אלא שאלה של פיקוח נפשות, והיא היא המעסיקה ומדאיגה את תושבי הכפר.</p>\n<p>כשאני לעצמי, הרי היתה השקפתי ברורה גם קודם לכן, ועל יסוד השקפתי זו הצעתי ודרשתי זה מכבר תכנית מסוימת בשביל התפתחות הכפר, וכמו שהדגשתי כמה פעמים, לא הי' בזה שאלה של נוחיות אלא צורך עקרי וחיוני לכל התפתחותו ועתידו של כפר חב\"ד ושאר מוסדות חב\"ד המושפעים ממנו במישרין או בעקיפין. ואם היו כאלה שפקפקו בהכרחיות ביצוע התכנית שהצעתי - במילואה, הרי עכשו בטח ברור לכל, כי בדברים בעלמא, ואפילו בהבטחות ואפילו במעשים מקוטעים לא נוכל להוציא הדאגה מלבות תושבי הכפר, ורק מילוי התכנית שהצעתי, במילואה ויותר, הוא אשר יוכל להשיב רוחם להמשיך אורח חייהם לא מתוך אתכפיא אלא ברצון וחפץ לב ומתוך מנוחה והרחבת הדעת כו' כאמור במברק הנ\"ל.</p>\n<p>ואחזור בזה בקיצור על הנקודות העקריות שהצעתי ודרשתי, אבל לדאבוננו עדין לא הוצאו לפועל, והן:</p>\n<p>א. כל העת השתדלתי שינקטו בכל האמצעים להרבות אוכלוסי הכפר ומקורות הפרנסה אשר שם, שלכן דרשתי וזרזתי בהקמת בתי ספר למלאכה ולחקלאות וכו' באופן הכי רחב ובהקדם הכי גדול. אבל לדאבוני ולתמהוני ולצערי, הנה מסיבות שאינן תלויות בי התנהלו הענינים לאטם ובעצלתיים במדה הכי גדולה. ועד כמה שמכאיב הדבר, מוכרח אני לומר שסיבת הדבר היא, שהמוסדות והמשרדים המתאימים באה\"ק ת\"ו אשר בידם ביצוע הדבר, שקלו וטרו בדבר כדרך התגרים בעניני ממונות, איזה סכום להלוות, ובאיזה תנאים, וכמה אפשר לקמץ וכו' וכו'. ויתר מכן, למרות ההבטחות שניתנו לי כאן (אם אמנם לא באופן רשמי) לא עמדו בדיבורם וקפצו ידם במקום שהי' צריך לפתוח, ובהרחבה...</p>\n<p>לא נעלמה ממני טענת המצב הכספי הדחוק בהמשרדים. אבל בידעי ובראותי אשר בהנוגע לפעולות <b>בחו</b><b>\"</b><b>ל</b> ועל ענינים שאינם עולים בחשיבותם - ולא רק מהשקפתי לחוד - על עניני בתי הספר למלאכה וחקלאות בכפר חב\"ד באה\"ק ת\"ו, אינם מצמצמים, בה בשעה אשר בעניני הכפר הולכים בצמצומים, הרי טענת אין לי נופלת מאלי'. ובפרט אשר הצורך להתחשב עם העובדא אשר הרחבת חדר האוכל והקמת בניני בתי הספר הנ\"ל אינם רק ענינים לעצמם אלא הכנה והקדמה להתפתחות כל הכפר, שכן היו מביאים חיזוק הרוח ועידוד לכל תושבי הכפר, הגברים הנשים והטף, וכל הסביבה.</p>\n<p>ב. ועל דרך האמור לעיל הוא גם בשאלת הבנינים בכפר החדש, שהגישה לזה צריכה להיות כזו, וכן הוא המצב באמת, אשר אין כאן שאלה של זריזות בבנין ונוחיות בלבד, אלא הענין נוגע לעצם התפתחותו של הכפר. ומלבד זה, הרי סוף סוף גם הבנינים הישנים היו מתיישבים והיו נתוספים עוד תושבים בכפר. ואילו היו ניגשים לענין מתוך השקפה זו ושלא בקמצנות וצמצום, כבר היינו זוכים למו\"מ בהנוגע לשלב השלישי.</p>\n<p>ג. ובקשר עם סעיף ב' הנ\"ל, היינו טעמא ג\"כ שדרשתי אשר יסדרו הכפר השני בסמיכות מקום לזה של עכשו, כי מלבד שזה הי' מקיל ההסתדרות בכפר החדש באורח חיים דומה לזה של הכפר הישן, הרי גם לתושבי הכפר הישן הי' זה עידוד גדול בראותם כי משמשים נקודה אשר סביבתה מתרכזים ישובים אחרים המסתדרים באורח חיים כמותם ואיש לרעהו יאמר חזק. למותר לומר שמבין אני בכל המאה אחוז השיטה וההשתדלות ליישב הכפר החדש דוקא בחבל לכיש או בדומה לו, אבל אילו היו מחשבים ההפסד לחב\"ד כנגד השכר של התיישבות מאה משפחות (שזה הי' המדובר בשלב ראשון) באיזורים הנ\"ל, היו מכירים שאינו בערך כלל. גם זוכר אני ההסברה שהשטח מסביב לכפר חב\"ד נמצא ברשות אחרים, מהדרין וכו', אבל הן ידוע שעיכובים מסוג זה נידחים בכל יום ובפרט במצב העכשוי באה\"ק ת\"ו, ובלי קושי ביותר.</p>\n<p>ד. עלי להוסיף עוד נקודה, אף שאינני יודע עד כמה צודקת, אבל כיון שגם בזה באו אלי בטענות, מוסרה הנני, והוא, אשר אין השמירה על הכפר מספיקה, כי הכפר הוא כמו שדה פרזון, ונוסף על זה מוקף פרדסים המשמשים מקום מחבוא למסתננים וכו'.</p>\n<p>והנה אין כוונתי בכל הנ\"ל, ובטח גם לא יחשדני בכך, לענין של, ח\"ו, הוכחה ומוסר, וידוע ששיטת המוסר אינה שיטת חב\"ד וליובאוויטש. אבל הכוונה בהנ\"ל היא, אשר על כל פנים מכאן ולהבא, והעיקר תיכף ומיד, יתחילו להרגיש מפנה עקרי בכל האמור לעיל, והעיקר אשר כל תושבי הכפר, הם ונשותיהם ובניהם ובנותיהם, גם כן יראו בעיני בשר, שחולל מפנה חדש ביחס להכפר. וכשיראו ויווכחו אשר גם המשרדים והאוהדים התעוררו על אתר במעשים בפועל להגדיל סיועם כמה פעמים ככה, הרי זה יוסיף בהתקשרותם אל הכפר, באופן אשר המאורע המזעזע לא רק שלא יגרום ח\"ו נפילת רוח ורפיון ידים, אלא אדרבה יעורר פנימיות נפשם, נפש החב\"דית, לראות בזה ירידה צורך עלי' גם עלה. ומובן אשר התנאי לזה, כאמור, הוא מעשים בפועל ובזריזות בהגדלת מוסדות ואוכלוסי הכפר, הרחבת עניני פרנסתם, והגדלת עניני בטחון שמירה והגנה.</p>\n<p>כמובן ידוע לי שחלק מהענינים הנ\"ל אין להם שייכות באופן ישר למשרדים אשר כ' פעיל בהם במישרין. אבל מכיון שההשגחה העליונה זיכתה את כ' להיות מהגורמים הראשיים בהקמת הכפר ופעל לטובת הכפר במרץ, הרי התייסדות הכפר התפתחותו ועתידו קשורים עם כ' באופן ישר. ולכן הנני בטוח, אשר יש לכ' גם היכולת לעשות ולפעול בכל הענינים הנ\"ל, שהרי שותף הוא בדבר, ואין הקב\"ה מבקש אלא לפי כוחו של כל אחד ואחד.</p>\n<p>ואם ישאל השואל, במה נשתנה כפר חב\"ד אשר יש לעשות בשבילו לפנים משורת הדין ולגדלו ולטפחו יותר מהכלל, הנה התשובה בצדה, אשר, ראשית, אין כל הסעיפים הנ\"ל יחד ובמילואם דורשים סכום גדול אשר יבצר מהם, והשנית, והוא העיקר, אשר כפר חב\"ד הוא אמנם יוצא מן הכלל, ותושבי הכפר אף הם מיוחדים במינם, שהרי אחרי יותר על 25 שנה של שעבוד אצל הקומוניסטים יצאו שלימים באמונתם ותקיפים ברוחם, ויכלו להסתדר באה\"ק ת\"ו באופן של הגברת הצורה על החומר, שלכן משמשים דוגמא ומופת לדורנו זה דור יתום. ובטח זוכר כ' מה שדברנו בהיותו כאן, עד כמה נצרך הנוער הארצי ישראלי להשפעה ועדוד רוחני שלא ליפול ברשת האידיאולוגיות המהרסות המתנקשות בנפש הדור הצעיר, בפרט באה\"ק ת\"ו, שגם זה ענין להתגדר בו.</p>\n<p>ויש גם להוסיף, אשר כפר חב\"ד הוא מהישובים היחידים, אם לא היחידי, אשר תושביו נשארו נאמנים למושבם, למרות כל העיכובים העלמות והסתירים, והראו בזה משמעת מופתית, אף על פי שרובם ככולם לא מכירים אותי פנים אל פנים. תקותי, אשר גם להבא יהי' כן, אבל אין להתעלם מהמציאות אשר המצב בכפר חב\"ד הוא כעת רציני ביותר. ואם להביא בחשבון שלהרבה מהם יש קרובים וידידים שהסתדרו במדינות אחרות באופן נוח וקל יותר שלא בערך, ועומדים עמהם בקישור מכתבים וביקורים, הרי הנסיון עוד יותר גדול.</p>\n<p>תקותי אשר גם להבא, בעזר השי\"ת, יעלה בידי לשמור על שלימות הכפר והתפתחותו והרחבתו, אבל - כל אחד מאתנו מתפלל בכל יום ובתחלת היום אל תביאנו לידי נסיון.</p>\n<p>ואסיים בהדגשה שאין כוונתי בהנ\"ל ח\"ו ענין של לחץ, וכמוכח מהמברק ששלחתי עוד קודם שכתבתי לכ' או קבלתי תשובתו; זאת אומרת, אשר בין כך ובין כך אעשה בעזר השי\"ת כל התלוי בי במלוי האחריות אשר עלי. אבל ביחד עם זה תקותי חזקה, אשר כל אוהדי חב\"ד על אתר, ועל אחת כמה וכמה מגזע חב\"ד, ועל אחת כמה וכמה אלה שגזע צור מחצבתם פועם בהם ובאופן של רגש המתבטא במעשים בפועל ההולכים וגדלים מיום ליום, אשר גם הם יכירו ביכלתם היתרה ובצו השעה ויעשו כל האפשרי ועוד יותר, ומובטחני שאז יהי' הכל בהצלחה ובשובה ונחת, וכל אחד ואחת יוכל לומר בפה מלא ובלב שמח אודך ה' כי אנפת בי גו' כי גאות עשה גו'.</p>\n<p>המצפה לבשו\"ט וחותם בהוקרה ובברכה.</p>\n<h4><i><b>ד'שט</b></i></h4>\n<p><b> הרש</b><b>\"</b><b>ז</b><b>:</b> שזר. אגרות נוספות אליו - לעיל חי\"ב ג'תתקיט, ובהנסמן בהערות שם. לקמן ד'תקנד. ד'תשכח.</p>\n<p><b> להמאורעות:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>\n<p><b> המברק</b><b>:</b> דלעיל ד'שג.</p>"],[1200870040,"ד'שי\n\n<p>ב\"ה, ח' אייר, ה'תשט\"ז</p><p>ברוקלין, נ.י.</p><p>כבוד הרב הגאון הנודע לתהלה, וו\"ח אי\"א<br>\nנו\"נ עוסק<br>\nבצ\"צ וכו' וכו' הרש\"י שי'</p>\n<p> שלום וברכה!</p>\n<p>מוסג\"פ העתק ממכתבי למר שזר שי'. וכיון שיצא המכתב ארוך יותר ממה שרגיל לקבל, ומרבוי הטרדות יש שמניחים מכתב ארוך לעת מצוא, הנה בטח יחפש כת\"ר הזדמנות להפגש אתו בהקדם בענין תוכן המכתב ולהוסיף הסברה מדילי' כפי שימצא לנכון. ולמותר להדגיש שיש לנצל ההתעוררות בחוגים השונים לרגלי המאורע, ולאידך גיסא צריך להשתדל בכל עוז למנוע נפילת הרוח ח\"ו אצל תושבי כפר חב\"ד, בעוד מועד, אשר הכל לפי רוב המעשה והזריזות שבזה. והשי\"ת יהי' עם פיו ויצליחו. ות\"ח אם יודיעני ממהלך הענינים.</p>\n<p>בכבוד ובברכה.</p>\n<p><b>מ. שניאורסאהן</b></p><p>באשר ימים אלו יוצאים לירושלים רבנים צעירים מכאן וישתדלו להשפיע על הרבנות הראשית בכלל והרב הרצוג שליט\"א בפרט בהנוגע לבעי' וסכסוך שנתעורר כאן מסביב לשאלה אם מותר לשומרי תורה ומצוה להשתתף בארגונים שיש להם אופי דתי ובהם באי כוח תנועת השמרנים והריפורמים, ולמרות פסק האיסור על זה שהוציאו הרבנים וראשי הישיבות, יש משתדלים להמשיך בהשתתפות זו, ומהם בין הנוסעים הנ\"ל, צריך להשתדל בכל עוז אשר לא רק שלא ימצאו סיוע ח\"ו לדעתם הכוזבת, אלא אדרבה גם הרבנים הראשים באה\"ק ת\"ו יביעו דעתם ועמדתם ברורה באיסור גמור ומוחלט על זה. וכיון שבמכתב קשה לבאר כל הפרטים שבזה, הנה מוסג\"פ פוטו של הפסק דין של הר\"מים, וגם של מכתבי ובקשתי את הרב וו\"ח אי\"א נו\"נ רב פעלים ובעל מרץ מוה\"ר דוד שי' האללאנדער לבקר את כת\"ר בהזדמנות ראשונה, ולמסור לכת\"ר את השתלשלות הענין וכל הפרטים שבזה.</p>\n<p>מובן שהרשות לכת\"ר למסור להרב הראשי שכתבתי לכת\"ר עד\"ז ותוכן מכתבי, ות\"ח מראש אם יודיעני בשו\"ט בכל הנ\"ל.</p>\n<p>שאלוני איך עמדתי בענין הנ\"ל מתאימה לעמדתי בהנוגע להבחירות באה\"ק ת\"ו, שגם בין המועמדים לבחירות היו כאלה שאם היו בארה\"ב היו משתייכים לתנועת השמרנים או וכו'. ועניתי שהחילוק פשוט, שבהנוגע לבחירות - אין ההשתתפות של שומרי תומ\"צ מכריזה שהם מכירים בהם כמו באי כח של תנועה <b>דתית</b><b>,</b> משא\"כ ההשתתפות בארגון \"הרבנים\" דניו-יורק (\"ניו-יורק בארד אוו ראבייס\") וארגון בתי הכנסיות (\"סינאגאג קאונסיל אוו אמעריקא\"), <b>שמודגש</b> בשמם שהם ארגונים דתיים, ולכן איש החרדי המשתתף בהם ביחד עם ראביי ריפורמי או שמרני או ב\"כ טעמפל שלהם, הרי השתתפותו אומרת שגם זה \"בית כנסת\" וגם זה \"רב\" - בניגוד לפסק תורתנו, וכל' הרמב\"ם, כמובא במכתבי, ופשוט.</p>\n<p>כמובן, אם יוכל להכיר את הרב האללאנדער הנ\"ל שי' עם אלה שיש להם השפעה בזה, בטח יעשה כן, ות\"ח מראש.</p>\n<h4><i><b>ד'שי</b></i></h4>\n<p><b> הרש</b><b>\"</b><b>י</b><b>:</b> זוין. אגרות נוספות אליו - לעיל חי\"ב ג'תתלד, ובהנסמן בהערות שם. לקמן ד'שמז. ד'תב. ד'תע. ד'תקנו. ד'תריז. ד'תרצו.</p>\n<p><b> מסביב לשאלה:</b> ראה גם לעיל אגרת ד'שו, ובהנסמן בהערות שם.</p>\n<p><b> מכתבי</b><b>:</b> דלעיל חי\"ב ד'קסב.</p>"],[1200870041,"ד'שיא\n\n<p>ב\"ה, ח' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג וו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה<br>\nיעקב שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו ממוצש\"ק בו כותב בהנוגע לסדר קביעות המזוזה במה ששמע מפי כ\"ק אדמו\"ר נ\"ע, ות\"ח ת\"ח על הפרטיות שבה, וכיון שלפעמים נזכרים כעבור זמן עוד פרטים, בטח אם יעלה בזכרונו עוד בהנוגע לזה, יודיעני ות\"ח מראש...</p>\n<p>בודאי למותר לעורר את כאו\"א מאנ\"ש אשר המאורע העבר ל\"ע ול\"ע צריך לגלות בהם כחות הנעלמים אשר בהם גדולה ההתקשרות עם רבותנו נשיאנו הק' ובמילא יוסיפו כל אחד ואחת ככל יכולתו בהתפתחות מוסדות חב\"ד אשר באה\"ק ת\"ו ודוקא במקומם עתה, וכמובן ממאמרי רבנו הזקן, רבנו האמצעי, והצמח צדק הידועים ומוסג\"פ העתק ממ\"ש לאחד כו' אשר אפשר יענין גם את כת\"ר, ומובן שלא לדרשא קאתינא, אלא שתקותי שגם הוא ינצל כל השפעתו בכיון האמור.</p>\n<p>בברכה לבשר טוב בכל הנ\"ל.</p>\n<h4><i><b>ד'שיא</b></i></h4>\n<p><b> מו\"ה יעקב:</b> לנדא. אגרות נוספות אליו - לעיל חי\"ב ד'רנא, ובהנסמן בהערות שם. לקמן ד'תמג. ד'תקצז.</p>\n<p><b> סדר קביעות המזוזה:</b> ראה לעיל שם.</p>\n<p>בהמשך לזה ראה לקמן אגרת ד'תמג.</p>\n<p><b> המאורע העבר:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>\n<p><b> וכמובן ממאמרי</b><b>:</b> ראה לעיל אגרת ד'שז, ובהנסמן בהערות שם.</p>"],[1200870042,"ד'שיב\n\n<p>ב\"ה, ח' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ מלאכתו מלאכת שמים<br>\nמו\"ה אורי שי'</p>\n<p> שלום וברכה!</p>\n<p>לאחרי שתיקתו הכי ארוכה נתקבל סו\"ס מכתבו מד' אייר ובמ\"ש אודות החלישות ח\"ו בעניני כפר חב\"ד בטוח אני במיסד הכפר ומנהלו הוא כ\"ק מו\"ח אדמו\"ר נשיא ישראל אשר אדרבה תתרבה העבודה ומנוחת הנפש ותתרבה ברכת השי\"ת לא רק בענינים הכללים אלא גם הפרטיים של כל אחד ואחת ובטוב הנראה והנגלה דוקא וכפסק רבנו הזקן רבנו האמצעי והצ\"צ בזה, וכמ\"ש במכתבי מאז.</p>\n<p>ת\"ח על הבשו\"ט שכבר מחפש מגרש מתאים עבור ביה\"ס אבל מובן שמה שמתברך שיבוא לפועל בשנת הלימודים תשי\"ח אין זה מספיק כלל וכלל, כי בעניני החינוך הרי כל חדש שבוע ואפילו יום, רב ערך הוא ביותר ובודאי בהשתדלות ומרץ המתאים מצדם תתרבה ג\"כ ההשתדלות מצד המשרדים המתאימים, ויה\"ר שבקרוב יבשר טוב בזה.</p>\n<p>לפלא שעד עתה לא הודיע איש אודות התחלת הרישום עד למכתבו זה שכנראה הותחל שלשום ויה\"ר שיהי' בהצלחה מרובה, ובודאי יגייסו מבין צעירי אגו\"ח ותלמידי תו\"ת כפי הדרוש לעבודה זו...</p>\n<p>בברכה שבקרוב ממש יסתדר ענין הדירה שלהם באופן טוב ויוכל להוסיף מרץ ככל הדרוש בעבודתו בקדש ברשת אהלי יוסף יצחק ליובאוויטש באה\"ק ת\"ו.</p>\n<h4><i><b>ד'שיב</b></i></h4>\n<p><b> מו\"ה אורי שי':</b> בן שחר, תל אביב. אגרות נוספות אליו - לעיל חי\"ב ג'תתקיא, ובהנסמן בהערות שם. לקמן ד'תקכח.</p>\n<p><b> בעניני כפר חב\"ד:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>\n<p><b> במכתבי מאז</b><b>:</b> לעיל ח\"י ג'רסב. וראה גם לעיל אגרת ד'שז, ובהנסמן בהערות שם.</p>"],[1200870043,"ד'שיג\n\n<p>ב\"ה, ח' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג וו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה<br>\nיצחק שי'</p>\n<p> שלום וברכה!</p>\n<p>... במ\"ש אודות מסירת מפתח במכירת חמץ, בודאי ידוע לו אשר בכ\"מ ועיירות אפילו המדקדקים במצות, הנה בזמן האחרון אין עושים זאת, ואפשר כוונתו במכתבו הוא רק לפלפולא ולא בהנוגע להפועל...</p>\n<p>בברכה ופ\"ש כל הדו\"ש.</p>\n<h4><i><b>ד'שיג</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ב ע' 289 והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> מו\"ה יצחק</b><b>:</b> דובאוו. אגרות נוספות אליו - לעיל חי\"ב ג'תתקסח, ובהנסמן בהערות שם.</p>\n<p>לקמן ד'תכא. ד'תרכא.</p>"],[1200870044,"ד'שיד\n\n<p>ב\"ה, ח' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... מ\"ש בהנוגע לבנו וב\"ג - שיחיו, בודאי מחפש הזדמנות שבאופן דיפלומטי יוכל לעורר עוה\"פ בהנוגע לעניני תורה ומצות. ואין לך דבר העומד בפני הרצון, והרי ידוע דחזקה לתעמולה שאינה חוזרת ריקם. ובודאי ידבר באופן שהוא יותר מתעמולה בעלמא. והשי\"ת יהי' עם פיהו ויצליח בזה.</p>\n<p>בברכה ופ\"ש כל הדו\"ש,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ד'שיד</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ב ע' 436.</p>"],[1200870045,"ד'שטו\n\n<p><i> [ט' אייר תשט</i><i>\"</i><i>ז</i><i>]</i></p>\n<p>... טוב עושה ששומע להוראתם של הר\"מ ור\"י שלו, ובפרט שהתחיל להתעסק בשטח חינוך הכשר והקדוש. ובטח מזמן לזמן יתרגל יותר לזה, יתמעטו ההעלמות וההסתרים ותתרבה ההצלחה. ויה\"ר שבקרוב ממש יודיע בשורות טובות בכל האמור.</p>\n<h4><i><b>ד'שטו</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ב ע' 365.</p>"],[1200870046,"ד'שטז\n\n<p>ב\"ה, ט' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>נעם לי לקבל מכתבו בו כותב אשר ההשגחה העליונה הפגישה אותו עם החכם...</p>\n<p>ועורר בו הרגשי איש הישראלי אשר כמאמר חכמינו זכרונם לברכה, ער הוא הקב\"ה לתורתו ומצותיו, ומובן ופשוט שאין מספיקה כלל התעוררות לפי שעה אלא שצריך להמשיכה גם בימים שאחרי זה ובחיי היום יומים, כי הרי בכל יום ויום צריך לפעול ולעשות דבר טוב שלא יהיו ימים ערטילאין וערומים, והרי זהו יתרון האדם על הבהמה שאין לה אלא אכילה ושתי' וכיוצא בזה, מה שאין כן האדם בחיר הבריאה אשר נפש שכלית לו ונפש אלקית לו שצריך להאיר סביבתו, ועל אחת כמה וכמה את עצמו בנר מצוה ותורה אור, וכשרוצים באמת אין לך דבר העומד בפני הרצון ומצליחים בזה...</p>\n<p>המחכה לבשורות טובות בכל האמור,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>"],[1200870047,"ד'שיז\n\n<p>ב\"ה, ט' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג וו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה דוב יהודא שי'</p>\n<p> שלום וברכה!</p>\n<p>... נראה לי הסברא לארגן אגודת חב\"ד בטרונטה, ובטח גם אגודת נשי ובנות חב\"ד תכנס בכלל זה כמחלקה או באופן אחר מתאים לחוקי המדינה ויה\"ר שתלך עבודתם מעלה מעלה הן בכמות והן באיכות.</p>\n<p>ובאותו ענין, תמוה קצת על מה שמתארך כ\"כ ענין הו\"ל החוברת בקשר עם אסיפת נשי חב\"ד דטרונטה, ובענינים כגון דא, ככל שקודם פרסום הדברים קודמות גם התוצאות מהפרסום מתאים למאמר קנאת סופרים תרבה חכמה.</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<h4><i><b>ד'שיז</b></i></h4>\n<p><b> מו\"ה דוב יהודא</b><b>:</b> שוחאט. אגרות נוספות אליו - לעיל חי\"א ג'תפה, ובהנסמן בהערות שם.</p>\n<p><b> הו\"ל... דטרונטה:</b> ראה לעיל חי\"ב אגרות ד'קמח. ד'קפד. לקמן ד'תיז.</p>"],[1200870048,"ד'שיח\n\n<p>ב\"ה, י\"א אייר, תשט\"ז</p><p>ברוקלין.</p><p>הנהלת כפר חב\"ד באה\"ק ת\"ו<br>\nד' עליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבם מח' אייר וכן המברקים שנתקבלו, ובהמשך להמברק מענה שלי.</p>\n<p>א) לדעתי מוכרח הדבר, וכמו שכתבתי זה כמה וכמה פעמים, שירחיבו כל המוסדות אשר בכפר חב\"ד ככל האפשרי, ובודאי יעשו בזה אנשי הכפר והנהלתו התלוי בהם, והנהלת המוסדות יעשו את התלוי בהם.</p>\n<p>ב) לדעתי מוכרחת הזריזות הן בענין בנין בנינים הפרטים וכן בניני הצבורים, וביחוד בית כנסת ולהבדיל בית הטבילה, ובודאי כנ\"ל יעשו כל התלוי בהם, ויוסיפו בהשתדלות במשרדים המתאימים שיעשו גם מצדם התלוי בהם.</p>\n<p>ג) כופל הנני עוד הפעם על מה שכתבתי זה כמה שנים, שמוכרח להרבות מספר התושבים (מתאימים) בכפר חב\"ד, ופשיטא לסייע לכל אלו שמשתדלים שיקבלום בין תושבי הכפר, וכשישתנה היחס לקליטת מתיישבים חדשים מצדם, בודאי ימצאו פתרון לשאלת החלקות וכו' וכו'.</p>\n<p>ד) פשוט ומובן והוא העיקר מכל ובכל הנקודות האמורות, שצריך קירוב הלבבות שביניהם להיות גדול והולך, וכיון שרז\"ל אמרו בזה, הלשון דמעביר על מדותיו, ה\"ז הוראה ברורה, שאפילו אם נדמה לאחד שצודק הוא בטענות שלו, ואפילו אם אין זה דמיון אלא האמת, בכל זה עליו להעביר על מדותיו, וגדול השלום שימשיך ומחזיק ברכותיו של הקב\"ה שהם עד בלי די להמשיכם למטה מעשרה טפחים ולהחזיקה גם בכלים גשמיים היינו בהנוגע לענינים גשמים בבני חיי ומזוני רוויחא, אשר פשיטא שלזה דרושה ובמילא ניתנת גם הרחבת הדעת ומנוחת הנפש, ובידי תושבי הכפר כל זה ובבחירתם חפשי, ובודאי יקויימו ציווי תורתנו תורת חיים והוראת נשיאנו הק', וכפתגם כ\"ק אדמו\"ר הצמח צדק ששמענוהו מפי כ\"ק מו\"ח אדמו\"ר, \"אחדות פון חסידים וועט זי[י] פירן ביז משיח'ן\" ומתאים לדברי בהמברק, תקותי ובטחוני חזקים שבקרוב ממש אוכל להשתתף בשמחתם אמיתית ופנימית - אף אם מרחוק במקום - אבל בקירוב אמיתי ברוח, ומתוך מנוחת הנפש והרחבה שלהם ושל כל בני ביתם, ד' עליהם יחיו בכפר חב\"ד, מקום אשר התגלה ותתגלה מדת הרחמים שהיא גדולה ממדת החסד שלפני' נחלה בלי מצרים מבריח מן הקצה אל הקצה.</p>\n<p>בברכה לכל טוב בגו\"ר, טוב הנוהנ\"ג - המצפה לבשו\"ט ומפורטות.</p>\n<p>נ.ב.</p>\n<p>בודאי ישתתפו גם אנשי הכפר המתאימים לזה בנסיעה למירון ביום ל\"ג בעומר הבע\"ל, ואלו הנשארים בכפר (או בשבת שלפני ל\"ג בעומר - גם הנ\"ל - ובסמיכות לל\"ג בעומר) ימשיכו ג\"כ שמחה זו בכפר חב\"ד ע\"י התועדויות בדברי חסידות ובדברי התעוררות ומהם התועדות גם נשי ובנות חב\"ד, ד' עליהם תחיינה.</p>\n<h4><i><b>ד'שיח</b></i></h4>\n<p><b> במענה על מכתבם</b><b>:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>\n<p><b> מברק מענה שלי</b><b>:</b> דלעיל ד'שג.</p>\n<p><b> בית הכנסת</b><b>:</b> ראה לעיל חי\"א ג'תצח. לקמן ד'תקח*. ד'תרנא.</p>\n<p><b> בית הטבילה</b><b>:</b> ראה לעיל אגרת ד'רפד, ובהנסמן בהערות שם.</p>\n<p><b> בנסיעה למירון</b><b>:</b> ראה גם לעיל חי\"א אגרת ג'תלט. לקמן ד'שכ.</p>"],[1200870049,"ד'שיט\n\n<p>ב\"ה, י\"א אייר, תשט\"ז</p><p>ברוקלין.</p><p>הנהלת ישיבת תומכי תמימים<br>\nד' עליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתביהם, מכ\"ה שבט, א' ד' יו\"ד ט\"ז י\"ח אדר, ח' ט' כ\"ז ניסן, ה' וז' אייר עם המוסגרים, כן נתקבלו בעתם התמונות של בתי הספר אשר בכפר חב\"ד והמפות, וכן נתקבל המכתב על גליונות ביה\"ס למלאכה מב' אדר.</p>\n<p>ונוסף על מה שכתבתי בהמברק שלי, הנה במ\"ש אודות המגבית לבתי ספר למלאכה וחקלאי, נכונה היא סברתם לעשותה - אבל באופן שלא יהי' חשש פון צו-להכעיס הערבים, וישנם כמה אופנים בפרסום ששוללים חשש זה. ובמ\"ש אודות המגבית לבנין החדש דישיבת תו\"ת בכפר, גם זה נכון הוא, אבל צ\"ע אם יש מקום לשתי מגביות בב\"א, כי צע\"ג אם יכפלו בנדבות המנדבים את תרומתם, ובכגון דא מובן שדין קדימה לבתי ספר מלאכה וחקלאי, כיון שזהו ענין שהזמן גרמא, משא\"כ הבנין הנ\"ל הרי גם כעבור זמן יכולים לפרסם, שלמרות כל המאורעות החליטו להקים עוד בנין חדש בכפר חב\"ד כו' וכו'. מובן שאין זה אלא נקודה כללית ועליהם להתבונן על אתר אם צירוף שתי המגביות יחד יביא תועלת נוספת, היינו פשוט בסכום. וכבר נאמר ותשועה ברוב יועץ.</p>\n<p>זה כשנתים שהנני מנצל כל הזדמנות לעוררם הן ישר והן מן הצד - על ההכרח <b> הכי</b> גדול בריבוי תלמידים, וגם כפשוטו בכמות. ולדאבוני ולצערי לא שמו לב לזה, ולמרות שכתבתי שהגדלת מספר התלמידים יגדיל עוד יותר צנורות ההכנסה, באו לידי סברא שההיפך נכון, היינו שככל שיצמצמו מספר התלמידים יקטינו הדעפיציט, ועכ\"פ לא תתרבה ההוצאה אף שתתקטן ההכנסה, ואפשר עוד מאיזה טעמים, אבל בכל אופן בהנוגע לפועל - נתמעט מספר התלמידים, ומובן שכל הטעמים והתירוצים שכתבו לי בזה - שסוג זה אינו מתאים וסוג זה עלול לקלקל, ואפילו את\"ל שהתירוצים מתאימים, הלואי היו משתדלים ברכישת תלמידים מסוגים שאפילו לדעתם מתאימים ככל הדרוש - שהי' מספר תלמידים בישיבה עתה עכ\"פ בכפלים.</p>\n<p>... ולפלא שסיום מכתבם אודות עז[ובה] גדולה... אינם מקשרים את זה כלל לשיטתם והנהגתם זה כמה ותולים את זה בהנהגת אנשים בלתי בעלי בחירה - למרות שבאמת כאו\"א וביחוד הנהלת תו\"ת צריכים היו לחפש בכל דבר לכל לראש הוראה בעבודת השי\"ת, ורק לאח\"ז פירוש הדברים בדרכי ועניני עוה\"ז שקליפת נוגה בו רובה מצד כו', ובמילא כל ענינים רוחנים ועאכו\"כ הוראות בעבודת השי\"ת - מעלימים ומסתירים עליהם בכל היכולת. <b>וברור</b> הדבר, שלו הי' מוחלט בדעתם שבנוגע לתלמידי תו\"ת באה\"ק ת\"ו, הרי כמו שמייסדיהם ומנהליהם, הם רבותינו הק', יכולים להספיק ההוצאה הדרושה למאתים תלמידים - א[ף] שבדרך הטבע לא הי' לזה מקום בשכל כלפני שנתים - יכולים הם להספיק ג\"כ ההוצאה לארבע מאות לשש מאות ועד לאלף תלמידים - הי' כן בפועל ובלי כל גוזמא. ו\"החילוק\" הוא - שהי' לעוד שמונה מאות תלמידים חלק ונחלה בתורת הבעש\"ט רבנו הזקן וכו'. וע\"י הנהגה בצמצום ובמדת הדין - אין נותנים להם האפשריות לזה. ועוד דבר נוסף - שעי\"ז יש אחיזה לצמצום מבחוץ, שאפילו במספר מאתיים תלמידים ג\"כ תהי' נתינת מקום למיעוט.</p>\n<p>קשה לי להאריך בדבר שהוא סברות הפוכות, כי בעיני פשוט הדבר, שאם הי' מוסיפים מספר התלמידים הי' מתמעט הדעפיציט לפ\"ע, ובעיניהם פשוט הדבר להיפך - שמוכרח שיהי' מספר תלמידים מסוים בכדי שתוכל לקרא בשם ישיבה אבל - נוסף על מספר זה - צריך לצמצם כיון שכל תלמיד דורש הוצאה של סכום לירות לחדש ומה לנו להוצאה נוספת.</p>\n<p>ולא באתי בשורותי הנ\"ל אלא לעורר עוה\"פ - שהנהגת כ\"ק מו\"ח אדמו\"ר היתה והיא, להרחיב המוסדות שלו ככל האפשרי, וכידועה שיחתו הק' בהנוגע להמוסדות שלו, \"איך בין אלעמאל געווען א בעל חוב און בין קיינמאל ח\"ו קיינעם ניט געבליבן שולדיג\".</p>\n<p>ועוד הפעם הנני מדגיש בזה, שאל יאמר האומר שאין זה אלא דבור בתור דברי התעוררות ולא בהנוגע לפועל, אלא שכוונתי כפשוטה: במשך שנים שעברו הנה הודות להנהגת ההנהלה במדת הצמצום שללו ח\"ו ממאות בני ישראל היכולת ללמוד תורת הדא\"ח, וגדול ההעלם וההסתר עי\"ז - עד שאפילו אלו שכבר נכנסו בכותלי תומכי תמימים, יצאו אחדים משם. וכמבואר בדא\"ח באריכות ובכמה מקומות מה בא בהשתל' מגבורות דקדושה וד\"ל.</p>\n<p>ויה\"ר שעכ\"פ תיכף לקבלת מכתבי הזה, זאל זיך כל אחד ואחד</p>\n<p>אריינווארפען - מתאים לתפקידו בהנהלת הישיבה - לרכוש מספר תלמידים מתאימים הכי גדול, ולהקל במדת ההתאמה, אשר אז יש לקוות שאפילו תלמידים שיצאו מכותלי תו\"ת - מפני סיבות שנראו בעיניהם לאמיתיות - יכירו את האמת לאמיתו, כמו שהנהלת הישיבה תכיר גם היא את האמת לאמיתו.</p>\n<p>ומשלש הנני עוה\"פ, שכל האמור איז דאס גאר כפשוטו, שישיבת לוד היתה עתה כוללת כו\"כ מאות תלמידים יותר מאשר לה. ומה לעשות שאמרו רז\"ל אין צועקין על העבר. ועכ\"פ ינצלו הימים הבע\"ל ככל היכולת, ואז יש לקוות שלתחלת זמן הבע\"ל יתוספו מאות תלמידים, ובלי גוזמא יותר ממאתים, על המספר בעבר. וכמ\"ש ובחנוני נא בזאת.</p>\n<p>בטח יכתבו בפרטיות הדרושה ע\"כ האמור במכתבי זה ובהמברק שלפניו ות\"ח.</p>\n<p>בברכת הצלחה מופלגה</p>\n<p>בכהנ\"ל,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ד'שיט</b></i></h4>\n<p><b> מברק שלי</b><b>:</b> דלעיל ד'שג.</p>\n<p><b> להכעיס הערבים</b><b>:</b> ראה גם לעיל אגרת ד'שה.</p>\n<p><b> תו\"ת בכפר</b><b>:</b> ראה לעיל ד'דש, ובהנסמן בהערות שם.</p>\n<p><b> זה כשנתים</b><b>:</b> ראה לעיל ח\"ט אגרת ב'תשלא. חי\"ב ד'לז. בהמשך לזה גם לקמן אגרת ד'שמא.</p>\n<p><b> וכידוע שיחתו:</b> ראה גם לעיל ח\"ו אגרת א'תרחצ.</p>"],[1200870050,"ד'שכ\n\n<p>ב\"ה, י\"א אייר, תשט\"ז</p><p>ברוקלין.</p><p>צעירי אגודת חב\"ד אשר בעיה\"ק ירושלים<br>\nת\"ו<br>\nה' עליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>בנועם קבלתי ז\"ע מכתבם מכ\"ד ניסן עם המצורפים בו, ותנוח דעתם כאשר הניחו את דעתי בבשורתם הטובה מפעולותיהם ביהדות בכלל ובהפצת המעיינות ביחוד, ובודאי יוסיפו בזה הלוך והוסיף, וכדרישת השעה, וע\"פ המבואר ומובא בכ\"מ אשר ככל שמתקרב לרגע הגאולה האמיתית והתחלתה, הרי כל רגע ורגע יקר מתגדל ערכו ונעשה יקר ויקר עוד יותר, כיון שצריך למהר להכין לביאת מר הוא מלכא משיחא, ולכן צריך לנצלו ככל האפשרי, והאריכות בדבר הפשוט למותר.</p>\n<p>ומזה מובן ג\"כ המענה על שאלתם בהנוגע לל\"ג בעומר, אשר פשוט ופשיטא שהשייכים לזה צריכים לסדר נסיעה למירון, ובל\"נ אשתתף במדה מסוימת בהוצאות הכרוכות בהענין, ואלו שמאיזה סיבות נכונות לא יוכלו לנסוע, בודאי יארגנו דבר המתאים והתועדות בירושת\"ו, ויתאימו הפעולות עם כל הסניפים והחברים ותהי' בהצלחה. ואחכה לבשו\"ט ומפורטות בכל האמור.</p>\n<p>בברכת הצלחה מופלגה.</p>\n<p>נ.ב.</p>\n<p>בטח אם יהיו עוד ענינים בהמשך למבצע המצה שמורה יודיעו, וכמדומני שעוררתי באיזה ממכתבי מלפנים שכדאי להחזיק הקשר עם אלו שבאים במגע ע\"י הפעולות איזה שתהיינה, וסו\"ס נתקיים פסק המשנה מצוה גוררת מצוה.</p>\n<h4><i><b>ד'שכ</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ז ע' 513 והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> לסדר נסיעה למירון</b><b>:</b> ראה גם לעיל אגרת ד'שיח, ובהנסמן בהערות שם.</p>"],[1200870051,"ד'שכא\n\n<p>ב\"ה, י\"ב אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>קבלתי מכתבו המהיר (נוסף על השלוח באוירון), וצריך עיון על המהירות בזה.</p>\n<p>וכנראה שהוא בשלו ואני בשלי, היינו שהנני כותב עוד הפעם חוות דעתי ברורה, שאין לבזבז הוצאות ולעשות היפך ענין של בנין, ע\"י העתק מ... כי עבודה רבה שם בהפצת המעינות (עד שיגיעו גם) חוצה. ובמלות פשוטות, רצונו להעתיק משם הוא עצת היצר, שאין דעתו נוחה מעבודת התפשטות החסידות באיזה אופן, וכיון שדעתי ברורה שצריך להתעסק בהפצת המעינות ב... מזה מובן שאין ענין כלל בנסיעת...</p>\n<p>וכבר אמרתי לו בהיותו כאן, שראיתי מכ\"ק מו\"ח אדמו\"ר, אז ער האט ניט געהאלטען פון דער שיטה \"דזיענגי ניע פאטשאם\" אפילו בהנהגת עשירים בכסף וזהב גשמים, עאכו\"כ שלא היתה דעתו נוחה מהנהגה כזו של איש צבורי, היינו אדם שמביטים עליו בשבע עינים, וכשמוציא שקל אחד אומרים שהוציא עשרה, וה\"ה בהנוגע אליו ולהנהגתו הבלתי נכונה לפי דעתי בהנוגע להאמור (לא הי' הכרח דוקא שידברו בתלפון בקשר עם... ועוד ועוד)...</p>\n<p>מצאתי לנחוץ להשתמש באותיות כהנ\"ל, אף שלא הורגלתי בהם, כיון שרואה אני שלמרות שרמזתי ואח\"כ דברתי איזה פעמים שמוכרח להיות דו\"ח בהנוגע לההוצאה של כל המתעסקים בצ\"צ, ואין כוונתי חשבון כלפי אחר, אלא כפי עצמו, היינו לדעת שבתוך עמי אנכי יושבת, וכמו שהם מוגבלים ומתחשבים עם היכולת הרי גם אני במדה והגבלה זו, ואף שמוכרחת ההתרחבות וההתפשטות, צריכה היא להיות בענינים רוחנים, והנהגתו הוא בפועל היא דוקא להיפך, היינו שמצמצם בהנוגע להפצת המעינות, ווארום מען זיצט אויף די טשעמאדאנעס און מען טראכט וועגען אמעריקא, ובהנוגע להגשמיות הוא כנ\"ל.</p>\n<p>ואף שלמותר הוא, בכ\"ז הנני כופל עוד הפעם, שאין ח\"ו כוונתי שאנ\"ש צריכים לחיות בדוחק גשמי ח\"ו וח\"ו, והמסתכל אפילו לשעה קלה רואה הוא ששיטתי היא דוקא להיפך, אבל חיים מסודרים שלא בצמצום אין פירושם חיים בלי סדר ובזבוז <b>בלי</b> כל הצדקה בשכל הבריא...</p>\n<p>בברכה לקליטת כל האמור לעיל מתוך שמחה ובמילא בפנימיות.</p>\n<p>נ.ב.</p>\n<p>אינני שולח מכתבי מהיר, ויה\"ר שמכאן ולהבא גם אנ\"ש יתנהגו באופן כזה מלבד במקרים נחוצים ביותר וביותר.</p>\n<h4><i><b>ד'שכא</b></i></h4>\n<p><b> דזיענגי ניע פאטשאם</b><b>:</b> כסף זוהי לא בעיה.</p>"],[1200870052,"ד'שכב\n\n<p>ב\"ה, י\"ב אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>נעם לי לקבל פ\"ש ממנו ע\"י הרה\"ח אי\"א נו\"נ עוסק בצ\"צ רב פעלים מוהר\"ש זלמן שי' העכט, וכן הפ\"נ אשר בעת רצון יקרא על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, ויה\"ר שיבשר טוב בכל האמור בו.</p>\n<p>כהנהגתנו עד עתה איש עם רעהו הנה הוא מצדו אינו מזכיר דבר על דבר קביעות לימוד החסידות, ואני בכל פעם מעורר אותו על אודות הכרח גמור בזה ההכרח על כל אחד מישראל בדורנו זה, דור יתום, ואף שתקותי שמפעם לפעם רואה גם בספר חסידותי, אבל חושש אני שאין זה בדרך קביעות, ובפרט לא קביעות, כביאור רבנו הזקן בעל התניא והשו\"ע, שקביעות אמיתי היא לא רק בזמן אלא גם קביעות בנפש, וכבר ידוע פסק המשנה אשר עשיר שהקריב קרבן עני לא יצא, וה\"ה בענינים רוחנים, דאין עשיר אלא בדעת ואין עני אלא בדעת, שמי שהיכולת בידו ללמוד בעיון היינו בתוספת באיכות ופשיטא בתוספת בכמות, אינו יוצא בקרבן של עני בדעת, והנמשל מובן, ואין הדבר תלוי אלא ברצונו, כי החפץ (היינו פנימיות הרצון) ישנו אצלו, כי ישנו אצל כל אחד מישראל, ובפרט אצל שומר תורה ומצות אשר מצוה גוררת מצוה.</p>\n<p>והשי\"ת יזכהו ויזכני לקבל ממנו בשורה טובה שעכ\"פ מכאן ולהבא יש לו - בלי נדר - קביעות בנפש וקביעות בזמן ללימוד פנימיות התורה אשר בדורנו זה נתגלתה בתורת החסידות.</p>\n<p>בברכה.</p>"],[1200870053,"ד'שכג\n\n<p>ב\"ה, י\"ב אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על הודעתו מקנין הבית.</p>\n<p>הנה יה\"ר שיהי' בשעה טובה ומוצלחת בגשמיות וברוחניות גם יחד, היינו שיהי' קנין בית (וכמבואר בדא\"ח ענין הקנין, שדוקא בעולם האצי' נקרא קנין מפני דאיהו וחיוהי וגרמוהי חד, ועי\"ז קונים בית) ברוחניות כמבואר בדרושי מזמור שיר חנוכת הבית בלקו\"ת ובסידור, ועד\"ז בסופו של המשך מים רבים ועוד. שבד\"מ ישתלשל ג\"כ בקנין הבית כפשוטו, בית מאושר בכל הפרטים.</p>\n<p>ויהי רצון שיוכל לבשר טוב בקרוב גם ע\"ד שידוך מתאים ובנין בית בישראל של בתו מרת... תחי'.</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ד'שכג</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ח ע' 449.</p>\n<p><b> מקנין הבית</b><b>:</b> ראה גם לעיל ח\"ג אגרת תרח. ח\"י ג'קנד.</p>"],[1200870054,"ד'שכד\n\n<p>ב\"ה, י\"ג אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>לאחרי שתיקתו הארוכה נתקבל מכתבו מי\"ט לעומר (שכן הוא הנוסחא של רבנו הזקן בסידורו הק', וידועה השקו\"ט בזה, ויעוין ג\"כ אגה\"ק סו\"ס י\"ג). וכבקשתו יזכירוהו ואת זוגתו שיחיו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע להמצטרך להם.</p>\n<p>ומה שמזכיר במכתבו שלומד בספר התניא הקדוש וגם מעט לקו\"ת כמו שנצטוה בשנת תער\"ב, הנה מובן שכיון מאז עברו כו\"כ שנים, הרי אין זה מספיק כלל וכלל, כיון שציווי תורתנו היא מעלין בקדש (וי\"א שזהו דאורייתא, ואפילו את\"ל שזהו דרבנן, וכן משמע דעת רבנו הזקן בשולחנו הטהור או\"ח סו\"ס ל\"ד, הרי חמורים ד\"ס וערבים עלי ד\"ס), ובודאי מכאן ולהבא יוסיף בהאמור, ובטוח השי\"ת לקיים הבטחתו, כל המוסיף מוסיפין לו.</p>\n<p>בודאי משתתף בהתועדויות אנ\"ש, וגדולה לגימה שמקרבת ומאחדת בני ישראל, ממשיכה ברכות השי\"ת בהפלגה, וכמ\"ש ברכנו אבינו כולנו כאחד באור פניך, ועיין תניא פרק ל\"ב וספר המצות להצ\"צ מצות אהבת ישראל ועוד.</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><p>במה שהקשה על מש\"כ בסהמ\"צ להצ\"צ מצות ספה\"ע פ\"ב שמשיח יהי' גבוה ממשה, והרי כתב הרמב\"ם (תשובה פ\"ט) שמשיח יהי' נביא קרוב למשה רבנו - מש\"כ בסהמ\"צ <b>מפורש</b> כן במד\"ת תולדות: ונשא מן משה (כצ\"ל. וכ\"ה ביל\"ש ישעי'). - ומש\"כ ברמב\"ם, יל\"פ שהוא רק בנוגע למעלת הנבואה, ועפמש\"נ ולא קם נביא. ועייג\"כ רמב\"ם יסוה\"ת פ\"ז. וראה לקו\"ת להאריז\"ל עה\"פ עד כי יבוא שילה. מנחות כט, ב. לקו\"ת לרבנו הזקן שה\"ש בסופו. ואכ\"מ.</p>\n<h4><i><b>ד'שכד</b></i></h4>\n<p>חלקה נדפס בלקו\"ש חי\"ב ע' 174 חלקה בחט\"ז ע' 491 וחלקה בח\"כ ע' 596 והושלמה ע\"פ צילום האגרת.</p>\n<p><b> הנוסחא של רבנו הזקן</b><b>:</b> ראה גם לעיל חי\"א אגרת ג'תקצט.</p>\n<p><b> וי\"א שהוא מדאורייתא</b><b>:</b> ראה גם לעיל ח\"ה אגרות א'רלט. א'תקכז. ח\"ז א'תתקסח.</p>\n<p>לקמן ד'תנט.</p>\n<p><b> שמשיח יהי' גבוה ממשה:</b> ראה גם לעיל ח\"ד אגרת תתקכג.</p>"],[1200870055,"ד'שכה\n\n<p>ב\"ה, י\"ג אייר, ה'תשט\"ז</p><p>ברוקלין, נ.י.</p><p>לכבוד מר אליעזר שי' שטיינמאן, תל אביב</p>\n<p> שלום וברכה!</p>\n<p>קבלתי מכתבו מכ\"ג אדר, ושמחתי לקרא בו שבספריו העתידים להופיע יהיו ג\"כ ציוני מקורות, וכמו שעמדתי על תועלתם במכתבי הקודם.</p>\n<p>בהנוגע לנקודה ב' של מכתבי ומענהו, וכמו שקורא לזה \"ענין המדרש והמעשה\", בודאי צודק במה שכותב אשר שיחה פנים אל פנים טובה הרבה יותר מאשר דברים שבכתב. אבל מובן ג\"כ שגם דברים שבכתב כוחם גדול, ויש בהם גם מה שאינו בדברים שבע\"פ, ולא לבד כמו שהעיר גם במכתבו אשר אותיות מחכימות, אלא עוד זאת, שאפשר לעבור על דברים שבכתב כמה פעמים, משא\"כ בדיבור. ופשיטא על פי מה שנתבאר בתורת החסידות אשר השתלשלות והמשכת ענין ממחשבה לדיבור ואפילו מדיבור למעשה, נותן לו קיום יתר ושייכות יותר לעולם, לסביבה הקרובה, ועל ידי זה גם לסביבה הרחוקה.</p>\n<p>אינני יודע איך עלי לפרש מה שכ' עבר בשתיקה על הנקודה העקרית בנקודה שני' האמורה, והיא אורח חיים חסידותי בחיי היום יומיים. ולכאורה הביאור היותר קרוב הוא שכיון שלעת עתה חושש הוא שהמענה שלו לא יתאים כל כך להצעתי במכתבי, הרי אפשר שאחשוב זה לעלבון וכיו\"ב. ואם זהו הביאור הנכון, הנני לשלול חשש זה, כיון שמביט אני על ענין דברי התעוררות בעניני תורה ומצוה מאחד לחברו - כפשוטו, שבזה מעוררים הנקודה הפנימית - של השומע - הקיימת בתוך כל אחד ואחת מישראל, ורק צריך להוציאה מן ההעלם אל הגלוי. ולכן כשמתאחרת הוצאה זו, הנה העדר ההצלחה של המעורר אינו תופס מקום לגבי הצער של הנקודה פנימית האמורה, שהיא עצם נשמת האדם הישראלי, אשר כל ירידתה לעולם הזה, ירידה מאיגרא רמה לבירא עמקתא, (כיון שהנשמה חצובה תחת כסא הכבוד של ממהקב\"ה - והעולם הזה, כלשון הקבלה והועתק ע\"י רבינו הזקן (תניא סוף פ\"ו), הוא עולם הקליפות וסטרא אחרא, ולכן כל מעשה העוה\"ז קשים ורעים והרשעים גוברים בו), וכל זה הוא בשביל העלי' ע\"י התורה והמצוות שמזה מובן שכל רגע שהנצוץ האלקי נמצא בעולם הקליפות וסט\"א ואינו מנצל את הרגע לעלי' המפליאה, הרי הצער עמוק ביותר. ומבוארים הדברים קצת יותר במכתבי לפני זמן, אשר העתקתו מוסגרה בזה.</p>\n<p>ותקותי חזקה, שבכתבו אשר נכנס בגן החסידות מאהבת ישראל ומחמדת סוכת דוד, כלומר נשמת ישראל, הנה בודאי כולל בזה גם את עצמו ונשמתו, אשר כלן מתאימות ואב אחד לכלנו, רק שהגופים מחולקים (תניא פל\"ב) וגם הענינים הבאים מצד הגוף.</p>\n<p>ובימים אלו, שבין זמן חירותנו לזמן מתן תורתנו - שלמות החירות, הרי נצטוינו ונתנה היכולת לעלות בכל יום ויום מחירות דשעבוד מצרים לחירות האמתית הבאה לעם ישראל בקבלת התורה - וכרמז רז\"ל חרות על הלוחות, חירות על (ידי) הלוחות.</p>\n<p>וכמו בימים ההם כן הוא גם בזמן הזה, אשר אין לך בן חורין אלא החי בבטחונו בבורא עולם - תכלית הצדק והטוב ומנהיגו מתאים לזה, אף שלא תמיד מובנים דרכיו, כי לא מחשבותינו מחשבותיו ולא דרכיו דרכינו.</p>\n<p>בכבוד וברכה.</p>\n<h4><i><b>ד'שכה</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"א ע' 396 והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> מר... שטיינמאן</b><b>:</b> אגרות נוספות אליו - לעיל חי\"ב ד'קלד. לקמן ד'תקו.</p>\n<p><b> במכתבי לפני זמן</b><b>:</b> ראה לעיל ח\"ו אגרת א'תשכו*.</p>"],[1200870056,"ד'שכו\n\n<p>ב\"ה, י\"ג אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה צבי שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מיום החמישי, בו כותב אודות הסדר בהת\"ת ובית הכנסת שבהנהגתו, והעיקר אשר מתוסף ומתפתח בזה, ובודאי מנצל ימי הסגולה באופן המתאים, וכמבואר גודל הערך בזה במכתבי כללי שלפני הפסח שבטח הגיעו, ומזה מובן שינצל יום הל\"ג בעומר ככל הדרוש ובפרט שחל ביום שפנוים ממלאכתם.</p>\n<p>בטח בעוד מועד מתכוננים לסדר דעי קעמפ, ויה\"ר שגם זה יהי' בהצלחה, ובודאי למותר לעוררו על הכתוב הלא פרוס לרעב לחמך וגו' ומבשרך לא תתעלם, וע\"פ המבואר באלי' רבא, שהכוונה הוא גם בהנוגע לתורה ומצות, ומזה מובן שסיום הכתוב הוא גם בהנוגע לעצמו בתומ\"צ שצריך להוסיף בזה מזמן לזמן, וכל המוסיף מוסיפין לו.</p>\n<p>בברכה לבשו\"ט בכל האמור לעיל.</p>\n<h4><i><b>ד'שכו</b></i></h4>\n<p><b> מו\"ה צבי שי':</b> שוסטרמן, שיקגו. אגרות נוספות אליו - לעיל חי\"ב ג'תתצב, ובהנסמן בהערות שם.</p>\n<p><b> במכתבי הכללי:</b> דלעיל חי\"ב אגרת ד'קצז.</p>"],[1200870057,"ד'שכז\n\n<p><i> [י\"ד אייר, תשט</i><i>\"</i><i>ז</i><i>]</i></p>\n<p>לאחרי ההפסק - נתקבל מכתבו מי\"א אייר מבשר טוב מהטבת מצב בריאותו. ויה\"ר עס זאל גיין פון גוט צו נאך בעסער, ולא רק בענינים הגשמים אלא גם בענינים הרוחניים, אף שאינו מזכיר עד\"ז במכתבו זה. ומובן שבזה נכללות גם הפעולות בהנוגע להזולת, ובפרט בימי הסגולה מועדים ורגלים ויומי דפגרא הבאים לקראתנו לשלום.</p>\n<p>הנוסח שמסגיר במכתבו, בכלל נכון הוא, אלא שצ\"ע אולי כדאי להחליף הלשון ערב יוכ\"פ בלשון ערב יום הקדוש, כיון שזהו סימן טוב יותר (עיין כתובות קג, ב).</p>\n<h4><i><b>ד'שכז</b></i></h4>\n<p><b> הנוסח:</b> ממצבה של א' שנפטר בערב יוהכ\"פ.</p>"],[1200870058,"ד'שכח\n\n<p>ב\"ה, י\"ד אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה סעדי' שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מט' אייר, ולפלא שאינו מזכיר דבר ע\"ד הכנות מתאימות ליום הל\"ג בעומר הבע\"ל, שבכלל ידוע יחס המיוחד של אחינו הספרדים לרשב\"י וכו'. והרי בשנה זו חל ביום שפנוים הנערים מלימודי חול וכו'. ותקותי שעכ\"פ בפועל ינצלו את היום כדבעי, וכן יתדברו ביניהם בכגון דא בהנוגע לזמן מ\"ת הבע\"ל. והשי\"ת יצליחו להגדיל תורה ולהאדירה וכמ\"ש לאחד שענין זה (דיגדיל תורה ויאדיר) הוא שייך ומקומו בעומק תחת ועד עומק רום. וכדמוכח גם בנגלה דתורה מזה שהרמב\"ם הביא כתוב זה למלמד תינוקות (בידו החזקה הלכות ת\"ת ספ\"ב), ומובא ג\"כ בענין תורה שלמעלה ממעשה (חולין סו, ב).</p>\n<p>בברכת הצלחה ולבשו\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ד'שכח</b></i></h4>\n<p><b> מו\"ה סעדי':</b> ליברוב, צפרו. אגרות נוספות אליו - לעיל חי\"ב ד'קכא, ובהנסמן בהערות שם. לקמן ד'תסה. ד'תקפט.</p>\n<p><b> וכמ\"ש לאחד:</b> ראה לעיל ח\"י אגרת ג'קעה, ובהנסמן בהערות שם.</p>"],[1200870059,"ד'שכט\n\n<p>ב\"ה, פסח שני, ה'תשט\"ז</p><p>ברוקלין, נ.י.</p><p>צו אלע חובבי תורה ומצוה<br>\nאון שטיצער פון מוסדות חינוך הכשר<br>\nד' עליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>דער הילפס-רוף פון די בית-רבקה סקולס פון בראנזוויל און איסט-ניו-יארק, דארף ארויסרופן א באלדיגען אפקלאנג אין יעדער אידישער הארץ.</p>\n<p>דער מוסד וואס איז געגרינדעט געווארען דורך כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע מיט פופצן יאר צוריק, וואו עס לערנען זיך אידישע טעכטער, און וואס האט שוין ב\"ה ארויסגעגעבען פיל הונדערטע תלמידות, דערצויגען אין תורה גייסט מיט יראת שמים, צו פארנעמען זייער ארט אלס <b>עקרת-הבית</b> - דער דאזיגער מוסד שטעהט היינט אין אן ערנסטע לאגע, צוליב שוועריקייטן וועלכע זיינען פארבונדן מיט דעם בנין פון דער סקול, וואס מוז פארריכט און אויסגעברייטערט ווערן, כדי צו באקומען די נויטיקע באשטעטיקונג פון דער שטאט פארוואלטונג.</p>\n<p>עס איז זיכער איבעריג מאריך צו זיין וועגן דער וויכטיקייט פון חינוך הבנות על טהרת הקדש בכלל, און בפרט וועגן דער לעבנס-וויכטיקייט פון די דערמאנטע בית-רבקה סקולס, וועלכע זיינען גוט באקאנט דער ברייטן אידישן עולם.</p>\n<p>איך ווענדע זיך דעריבער צו יעדן איינעם, בא וועמען תורה און תורה-אידישקייט איז טייער און הייליק, אפצורופן זיך ברייטהערציק אויף דעם ערנסטן הילפס-רוף פון די בית-רבקה סקולס פון בראנזוויל און איסט-ניו-יארק, סיי מיט דער גרעסטער אייגענער שטיצע, סיי דורך פערזענלעכער באמיאונג צוציען און מזכה זיין אויך אנדערע מיט דער גרויסער מצוה פון העלפן אין דעם חינוך הכשר פון אידישע טעכטער על טהרת הקדש.</p>\n<p>והשם יתברך, וואס מדתו איז מדה כנגד מדה, און נאך כמה פעמים ככה, וועט בענטשן די אלע שטיצער און עסקנים מיט אידישן נחת פון קינדער שיחיו און פון זיך אליין - מתוך הרחבה, בגשמיות וברוחניות.</p>\n<p>בברכת כל טוב,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ד'שכט</b></i></h4>\n<p><b> מיט פופצן יאר צוריק:</b> ראה ס' \"תולדות חב\"ד בארה\"ב\" פרק נח.</p>"],[1200870060,"ד'של\n\n<p>ב\"ה, פסח שני, ה'תשט\"ז</p><p>ברוקלין, נ.י.</p>\n<p> שלום וברכה!</p>\n<p>בעתו קבלתי מכתבו מי\"ז בניסן, ולא היו עתותי בידי לאשרו מקודם לכן. ואתו הסליחה.</p>\n<p>אמנם חבל שלא היתה הזדמנות להפגש את כ' פא\"פ בשעת ביקורו האחרון באמריקה, כי יתרון הדבור על הכתב הוא גם בזה שבשעת הדבור הכרת הפנים תעיד במדה חשובה עד כמה הדברים מתקבלים על הלב ומה יש להוסיף או לשנות, ועוד זאת אשר גם בעל השיחה השני יש לו אפשרות לענות על אתר, במילא אין מקום לטינא בלב, אם גם אין הדברים לפי רוחו.</p>\n<p>אבל מכיון שלא אסתייעא מילתא משתמש אני בכתב, בהמשך למה שכותב במכתבו שעבד כחייל לחיזוק מערכות ישראל, ואסתפק בנקודות אחדות כיון שלדכוותי' האריכות אך למותר, והוא:</p>\n<p>בכל מערכה יש תפקידים שונים, וההצלחה והנצחון תלויים בזה שכל אחד ואחד ינצל כל כוחותיו במלוי תפקידו במקום פלוני ובענין פלוני אשר נמסר לכאו\"א בפרט, וביחוד כשהוא ענין שאי אפשר לעשותו על ידי אחרים, וכמו שמובן גודל כח תנאי זה ממה שפסקו רז\"ל (מועד קטן ט, ב) דברי תורה, אפילו חפצי שמים - הן המצוות - לא ישוו בה, ואם היא מצוה שאי אפשר לעשותה על ידי אחרים לא רק שווה היא לדברי תורה, אלא גם דוחה אותה.</p>\n<p>ובהנוגע להנ\"ל, הנה בענינים גשמיים וחומריים יש הרבה מתעסקים ופועלים, ובעניני הדת לדאבוננו מעט מזעיר, ואפילו העוסקים בזה, הרי הוא בזהירות גדולה ביותר שלא לפגוע בכבודו של מי שהוא, באופן של \"בתי-יד של משי\", ודוקא כשהצד שכנגד הוא במצב רוח טוב וכו' וכו', במילא מובן עד כמה נוגע הדבר אשר זה שחננו ה' בכחות ובהשפעה לפעול בעניני דת, לא ידחה פעולה זו אפילו לרגע בשביל ענינים אחרים.</p>\n<p>בתקוה לשמוע בשורות טובות ובכבוד וברכה.</p>"],[1200870061,"ד'שלא\n\n<p>ב\"ה, י\"ד אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה רפאל נחמן שי' הכהן</p>\n<p> שלום וברכה!</p>\n<p>לאחרי שתיקתו הכי ארוכה נתקבל מכתבו מעש\"ק, ובודאי למותר לעוררו שגם הוא ינצל כחותיו בעדוד רוח אנ\"ש וצעירי אנ\"ש, וביחוד אלו שבכפר חב\"ד, ובהדגשה אשר דוקא במקום אשר נתגלתה מדת כו' הנה שם תתגלה מדת הרחמים שהיא גדולה ממדת החסד שלפני' נחלה בלי מצרים מבריח מן הקצה אל הקצה, וכמ\"ש לכמה מאנ\"ש.</p>\n<p>והביאור ע\"פ חסידות ועוד יותר אין דעם ארום פון חסידות, אשר גם התעוררות זו וקליטת הוראת רבותינו הק' צריכה להיות באופן שתמשך במעשה, היינו עשי' ככל הדרוש וככל היכולת בהתפתחות הכפר והמוסדות אשר בו, הן בכמות והן באיכות, שבודאי יתוסף עי\"ז בהפצת המעינות עד שיגיעו גם חוצה.</p>\n<p>נעם לי לקרות במכתבו שמשתדל לנצל כשרונותיו בענין הנ\"ל ע\"י התועדות וכדומה, ומה טוב שיחפש הזדמנות כאלו בכפר חב\"ד והתלמידים הנמצאים שם, כי דרישת השעה היא וענין שהזמן גרמא...</p>\n<p>במ\"ש במכתבו אודות מאמר רבנו הזקן (הובא בתו\"א בתחלתו) שע\"י הצדקה נעשים מוחו ולבו זכים אלף פעמים ככה, הנה כתבתי לאחד שלשונו הזהב של רבנו הזקן מדוייק בכל התיבות ואותיות. ובהנ\"ל אומר שנעשו <b>זכים,</b> היינו כלים מוכשרים לקבלה ביותר וביותר, אבל אינו אומר שנעשים מלאים ידיעות והרגשים. שמזה מובן אשר אף שהצלחה מופלגה להעושה צדקה, בכ\"ז גם הוא זקוק לעבודה ללימוד ויגיעה, אלא שהפירות הם אלף פעמים ככה, אלף ממש וכמוכח מהגהות צ\"צ שנדפסו בלקו\"ת לג' פרשיות שם.</p>\n<p>בברכה לבשו\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ד'שלא</b></i></h4>\n<p><b> מו\"ה רפאל נחמן שי' הכהן:</b> תל אביב. אגרות נוספות אליו - לעיל חי\"ב ג'תתקט, ובהנסמן בהערות שם.</p>\n<p><b> במקום אשר נתגלתה מדת כו':</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>\n<p><b> כתבתי לאחד</b><b>:</b> לעיל חי\"ב אגרת ד'קכו.</p>"],[1200870062,"ד'שלב\n\n<p>ב\"ה, ט\"ו אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה אברהם<br>\nחנוך שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מה' אייר, ובודאי כבר קבל בינתים ההערות לחומר דבטאון ל\"ג בעומר.</p>\n<p>ובמה ששואל אודות החילוקי דיעות בנוגע לאופן מושבו של כ\"ק אדמו\"ר מוהרש\"ב נ\"ע בעת אמירת דא\"ח, הדרך הפשוט הוא להעיר עליהם בהערה בשולי הגליון.</p>\n<p>בהנוגע אם להכניס קלישעס בהבטאון מתכנית הבנין וכו'.</p>\n<p>אינו נראה לי, עד שיפתחו מדור דקלישע ותמונות שם, כי בא\"ל, הרי משמעות הנ\"ל ענין של מגבית בבטאון, ואין זה מענינו - עכ\"פ במצב העכשוי, משא\"כ בנוגע להמכתב אודות ישיבת לוד שגם בו דברי התעוררות אין שלילה האמורה, אבל יש להתייעץ ולהתדבר ביניהם, אם כדאי הדבר עתה או לפרסם המכתב לראשונה בזמן קרוב יותר למגבית בפועל...</p>\n<p>לפלא שאינו מזכיר ע\"ד השתדלותו בנוגע לספרים של מחברים היו\"ל מזמן לזמן (מלבד אלו הנשלחים ע\"י ש\"ב הרה\"ח כו' סלונים שי' והם היו\"ל ע\"י מוסד הרב קוק), וביחוד הספרים דמר פרידבערג שהזכירו במכתבו מאז...</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<p>נ.ב.</p>\n<p>מסיבה נתעכב שילוח המכ' ובנתיים נתקבלו מכתביו מי\"ב וכ\"א אייר. חבילת שיחות מתורגמות (ואין הזמ\"ג לבקרם עתה).</p>\n<p>כמה מנהגים בבקשות אם בצירוף שם האם או האב (והאריך בזה בשו\"ת שם משמעון או\"ח סכ\"ב) ולכן (דלא ככתוב בסיום מכ' דכ\"א אייר) יש להזכיר שניהם כיון דאפשר, או רק בשם האם וכנוסח בסידור. וראה ג\"כ זח\"א פד, א. פנ\"י ס\"פ בהעלותך.</p>\n<p>לפרסם בבטאון הבא המברקים לכחב\"ד - נכון.</p>\n<h4><i><b>ד'שלב</b></i></h4>\n<p><b> מו\"ה אברהם חנוך שי':</b> גליצנשטיין, לוד. אגרות נוספות אליו - לעיל חי\"ב ג'תתעט, ובהנסמן בהערות שם.</p>\n<p><b> אופן מושבו:</b> פניו לצד צפון או לצד דרום.</p>\n<p><b> מלבד אלו הנשלחים</b><b>:</b> ראה לעיל חי\"ב אגרת ג'תתקכ, ובהנסמן בהערות שם.</p>\n<p><b> הספרים דמר פרידבערג</b><b>:</b> ראה לעיל חי\"ב אגרת ד'קפח.</p>\n<p><b> בצירוף שם האם</b><b>:</b> ראה לעיל חי\"א אגרת ג'תכ, ובהנסמן בהערות שם.</p>\n<p><b> המברקים לכחב</b><b>\"</b><b>ד</b><b>:</b> דלעיל ג'שג.</p>"],[1200870063,"ד'שלג\n\n<p>ב\"ה, ט\"ו אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"ב לחדש, מה שכותב אודות שכחה. הנה צריך לבדוק את התפילין שלו ושיהי' בקי עכ\"פ באיזה פרקים משניות בעל פה, וכן עכ\"פ פרק אחד מספר תניא קדישא, ויחזור עליהם מזמן לזמן ועל ידי זה יתחזק כח הזכרון.</p>\n<p>ובמה שכותב אודות חלומות וכו', הנה יבדוק המזוזות בדירה בה דר וביחוד בהחדר בו ישן, ויישן - אם אפשר - בטלית קטן שציציותיו בדוקות, ובכיסוי הראש.</p>\n<p>ועל שני הענינים האמורים, הנה בכל יום חול קודם תפלת הבקר, יפריש איזה פרנק (א' ב') לצדקה, והשי\"ת יזכהו לבשר טוב בכל האמור לעיל.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>"],[1200870064,"ד'שלד\n\n<p>ב\"ה, ט\"ו אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ כו' מו\"ה יצחק שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו - בלי הוראת זמן הכתיבה -</p>\n<p>א) במה שמקשה, למה השי\"ת רצה את זה וכו'.</p>\n<p>כבר אמרו רז\"ל כלל גדול, בהדי כבשי דרחמנא למה לך, והפירוש גם כפשוטו, ובפרט אשר לכל אחד ואחד מחלקי הבריאה יש לו תפקיד שעליו למלאותו, וכיון שאין דבר בעולם לבטלה, הרי נותנים לכל חלק וחלק הכחות והזמן הדרושים למילוי תפקידו זה, וכשמבלה זמנו וכחותיו (שבזה נכנס גם כח התבוננות שלו ושכלו) על ענינים שאינם מתפקידו, יחסרו לו בעת שיגש למלאות תפקידו המיוחד.</p>\n<p>ב) בשאלתו איך צריך להבין את הנ\"ל וכן בנוגע לשריפת החדר בקבוץ שדה אליהו ובו גם ספרים וכו'.</p>\n<p>כללות הנקודה בענינים כגון אלו היא, שאין שליטה על עניני איש היהודי, ובפרט על עניני הקדושה למי שהוא ושיהי', אם אין חלישות מצד איש היהודי בענינים <b>אלו</b><b>,</b> (שזוהי נתינת מקום לפגיעה מבחוץ), ולכן על כל אלו שנוגע להם ענינים כגון אלו, לפשפש בהנהגתם, שאז ודאי ימצאו שלא נזהרו בקדושת הספרים או יותר קרוב לומר בהלימוד שבהם שזה מטרת הדפסתם וכו' כפי הדרוש, ועד\"ז גם בנוגע לפב\"פ שבטח הי' איזה גרעון בהסיוע לו ולעבודתו בקדש מצד בעלי בחירה, ועי\"ז נפתח סדק לשליטת בלתי בעלי בחירה, מובן שהנ\"ל היא נקודה כוללת משותפת לכל המאורעות מסוג זה, אבל בכל מאורע צריך לפשפש על אתר במקום זה ובזמן שלפני המאורע, ואז ודאי ימצאו ענינים קרובים ומפורטים יותר.</p>\n<p>ג) במ\"ש אודות ההנהגה לאחרי שריפת החדר וכו'.</p>\n<p>הרי זה תלוי במנהג המקום ולכן עליו לפנות בזה לרבנים מורי הוראה הנמצאים שם או בסמיכות, וכדאי להתענין אם לא הי' בחדר זה ריקודים של תערובות.</p>\n<p>ד) במה שכותב אודות אמירת תפלה (בתפלת מנחה של ערב שבת קדש) בהנוגע לשמירת שבת הבא.</p>\n<p>אין זה במנהגי אנ\"ש, ולא בסידורו של רבנו הזקן.</p>\n<p>ה) במה שכותב שבעת המאורע בהקבוץ שלהם, למד אז הפרשה ונתץ את הבית וכו'.</p>\n<p>יעיין במדרש רבה סוף פרשה הנ\"ל, פי\"ז, שהענין ברוחניות הוא ענין הגלות וענין הגלות בפנימיות הוא, כנוסח שקבעו אנשי כנסת הגדולה, ומפני חטאינו גלינו מארצנו, שחטא ועון הוא גלות לנפש האלקית שבכל אחד ואחת מבני ישראל חלק אלקה ממעל ממש, ועי\"ז לניצוץ שכינה אשר בתוכו, וזהו הענין שממנו משתלשל גם גלות הגוף כפשוטו, וזוהי השייכות בין שני הענינים הפרשה והמאורע, שבאים לעורר על הכרח הוספה בעניני תורה ומצות ובפרט בשבת קדש, אשר עליו נאמר שבת <b>לה</b><b>'.</b> וח\"ו בגרעון בזה זהו ענין גלות וענין פרשה הנ\"ל, ונקודת הגלות המרכזית היא ענין שריפת בית המקדש שלכן הגדילו את צום החמישי, ועד\"ז מקדש מעט, מקום תפלה ר\"ל.</p>\n<p>ויהי רצון שיוסיף בלימוד התורה וקיום המצות ובעיקר בקביעות עתים בלימוד פנימיות התורה המביאה להתלהבות בעבודת השם (אש דקדושה האוכלת אש דלעומת זה ברוחניות ובמילא אין מקום לאש דלעומת זה גם בגשמיות), ולהשפעה בסביבתו בכיוון האמור.</p>\n<p>בברכה לבשר טוב,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ד'שלד</b></i></h4>\n<p><b> מו\"ה יצחק</b><b>:</b> ווייל, שדה אליהו.</p>\n<p><b> רצה את זה</b><b>:</b> המאורעות בכפר חב\"ד. ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>"],[1200870065,"ד'שלה\n\n<p>ב\"ה, ט\"ז אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה נחום שמרי' שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"א אייר, בו כותב ע\"ד המאורע בכפר חב\"ד ל\"ע ול\"ע.</p>\n<p>ובודאי למותר לעוררו במ\"ש לכמה מאנ\"ש שמוכרח לא רק לחזק המוסדות אשר שם, אלא עוד להרחיבם בכמות וגם באיכות כי שם ציוה ה' את הברכה עד העולם, וכהוראת רבותינו הק' אשר תתגלה במקום זה מדת הרחמים שהיא גדולה ממדת החסד שלפני' נחלה בלי מצרים מבריח מן הקצה אל הקצה.</p>\n<p>בברכה לבשו\"ט בהנ\"ל ומפעולותיו בזה.</p>\n<h4><i><b>ד'שלה</b></i></h4>\n<p><b> מו\"ה נחום שמרי':</b> ששונקין, ירושלים. אגרות נוספות אליו - לעיל חי\"א ג'תעד, ובהנסמן בהערות שם.</p>\n<p><b> המאורע בכפר חב\"ד:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>"],[1200870066,"ד'שלו\n\n<p>ב\"ה, ט\"ז אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ כו' מו\"ה ארי' שי' הלוי</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו, בו מזכיר ע\"ד המאורע בכפר חב\"ד, ובודאי כבר ידוע לו מה שכתבתי לכמה מאנ\"ש, אשר אף שבענינים כגון אלו אמרו רז\"ל בהדי כבשי דרחמנא כו', אבל בהנוגע להלימוד בהנהגה ולהוראות במילוי תפקיד האדם בעבודת השי\"ת, צריך כל אחד להתבונן אליבא דנפשי' ולהסיק המסקנא, ולדעתי בענין זה היא, אשר מוכרח לחזק הכפר בכללות והמוסדות שם ביחוד, וההתחזקות בכגון דא היא גם בהתפשטות והתרחבות כי שם ציוה ה' את הברכה עד העולם, וכהוראת נשיאנו הק' (דרך מצותיך דף קי\"ד ע\"ב) אשר שם - במקום זה תתגלה מדת הרחמים שהיא גדולה ממדת החסד שלפני' נחלה בלי מצרים מבריח מן הקצה אל הקצה.</p>\n<p>בברכה להטבת מצב בריאותו ולבשו\"ט מתוך הרחבת הדעת בהנ\"ל.</p>\n<h4><i><b>ד'שלו</b></i></h4>\n<p><b> מו\"ה ארי':</b> הורביץ, תל אביב.</p>\n<p><b> המאורע בכפר חב</b><b>\"</b><b>ד</b><b>:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>"],[1200870067,"ד'שלז\n\n<p>ב\"ה, ט\"ז אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ כו' מו\"ה נחמן שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו ממוצש\"ק. הנה ת\"ח על הבשו\"ט מאשר הביא שתילים וגרעינים וכו' לאה\"ק ת\"ו, ובמ\"ש שסידרו הדברים בפתח תקוה נא להתענין עוד בזה, אפשר עכ\"פ חלק יש לסדר בכפר חב\"ד כי שם צוה ה' את הברכה עד העולם, והרי ישנם כמה פרדסים שם, וע\"פ השמועה מצליחים, שזהו מוכיח שהאדמה מתאימה לענין זה.</p>\n<p>כיון שאינו מזכיר דבר בהנוגע לבריאות חותנו ש\"ב שליט\"א, בטח זהו סימן שהכל בסדר ובשלום, ומטובו לפרוש שלומו.</p>\n<p>בברכה המחכה לבשו\"ט.</p>\n<p>נ.ב.</p>\n<p>בטח יודע משלשת השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר</p>\n<p>זצוקללה\"ה נבג\"מ זי\"ע, בחומש תהלים ותניא הידועים, ועכ\"פ ישמור אותם מכאן ולהבא.</p>\n<h4><i><b>ד'שלז</b></i></h4>\n<p><b> מו\"ה נחמן:</b> אלבוים, ירושלים.</p>\n<p><b> הביא שתילים וגרעינים</b><b>:</b> מאתרוגי קלבריה. ראה לעיל ח\"י אגרת ג'נו. לקמן ד'שפא.</p>\n<p>ד'שצ.</p>\n<p><b> חותנו:</b> ה\"ר זאב דוב לודמיר.</p>"],[1200870068,"ד'שלח\n\n<p>ב\"ה, ט\"ז אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מיום ל' לעומר, בו כותב שמסתפק בכוונת כתבי, שצריך להשתדל בענין שידוך מתאים במרץ הכי גדול וגם בדרך הטבע.</p>\n<p>וכוונתי פשוטה, לעשות כמנהג הרוב הכי גדול במדינה זו ובזמן זה, והיינו להתקשר עם ממוצע שדכן טוב וכזה יש לו היכירות בחוגים דשומרי תורה ומצוה, ומבארים לו התנאים שמחפשים וכו'.</p>\n<p>ובמה שכותב אם צריכה להיות דתית במאה אחוז מקודם וכו' - או שמספיק הבטחה בנוגע להנהגה מכאן ולהבא.</p>\n<p>זה תלוי בתכונת נפש המבטיחה ואם נאמנת בקיום הבטחתה, והעיקר אם יודעת מה מקבלת על עצמה היינו שיש לה מושג באורח חיים יהודי אמיתי וכו', והשי\"ת יצליחו שיבשר טוב בהנ\"ל, וכן במה שכותב בסיום מכתבו אודות הוספה בעניני תורה ומצות.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>"],[1200870069,"ד'שלט\n\n<p>ב\"ה, ט\"ז אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו - בלי הוראת זמן הכתיבה - בו כותב אודות מה שאירע לו בענין העלי' על האני' בעת היותו באיטליא ביום ו' עש\"ק ושואל תיקון בזה.</p>\n<p>הנה עליו להשתדל להיות בקי בהלכות שבת עכ\"פ באלו הצריכות, ובפרט ע\"פ המבואר בקונטרס אחרון בסופו, לזאת עצה היעוצה וכו'.</p>\n<p>ולהודעתו מיום ההולדת שלו, הנה בטח ינהג במנהגי יום הולדת כפי שנהגו אנ\"ש בזמן האחרון, והשי\"ת יתן שתהי' אצלו שנת הצלחה בלימוד התורה ובקיום המצות בהידור.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ד'שלט</b></i></h4>\n<p><b> העלי' על האני':</b> ראה לקמן אגרת ד'תקנה, ובהנסמן בהערות שם.</p>\n<p><b> במנהגי יום הולדת</b><b>:</b> ראה לעיל חי\"ב אגרת ד'פב, ובהנסמן בהערות שם. לקמן ד'שנח.</p>\n<p>ד'תקסג. ד'תקצג. ד'תשא.</p>\n<p><b> מכתבי:</b> דלעיל ד'שיט.</p>\n<p><b> ההוצאות הקשורות</b><b>:</b> ראה גם לקמן אגרת ד'תרטו.</p>"],[1200870070,"ד'שמ\n\n<p>ב\"ה, ט\"ז אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מי\"ב אייר, בו כותב אודות הקב\"ע שלו בת\"ת, ויותר נכון אשר אין לו קביעות עתים, ומובן ופשוט שזהו היפך הנדרש, ובפרט בעניניו ובמכש\"כ וק\"ו ומה שבהנוגע לבו\"ד, הרי במצב כזה משתדלים להפיק רצונו ולגרום לו נח\"ר כו', אף שמסופקים אם היכולת בידו ואם ע\"י הנח\"ר ימלא הבקשה, עאכו\"כ בנוגע לקוב\"ה שבודאי היכולת בידו ובודאי הנחת רוח תצליח שצריך לעשות בזה ביותר וביותר, ולפלא שגם בענינים פשוטים כאלו צריכים לכתוב מעבר לים.</p>\n<p>מובן ופשוט גם כן שכל הדברים האלו הוא גם בנוגע לחבריו, ויה\"ר שימצא האותיות המתאימות בכדי להסביר להם את זה, ובמילא יתקבל בטוב גם אצלו, והעיקר שיביא בפועל בקביעות בזמן ובקביעות בנפש בלימוד תורת הנגלה ותורת החסידות, וכל העוסק בתורה נכסיו מצליחים שבכלל מלת נכסיו הם הרוחנים והגשמים גם יחד ומתוך מנוחת הנפש והרחבת הדעת...</p>\n<p>בברכה.</p>"],[1200870071,"ד'שמא\n\n<p>ב\"ה, ח\"י אייר, תשט\"ז</p><p>ברוקלין.</p><p>הנהלת ישיבת תומכי תמימים אשר בלוד<br>\nד' עליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבם מי\"ג אייר - ובטח נתקבל מכתבי מענה על מכ' הקודמים...</p>\n<p>במ\"ש אודות מספר התלמידים וכו' כבר פירשתי שיחתי בארוכה במכתבי הנ\"ל. ואחזור רק על הנקודה - שדעתי ברורה שהיכולת (מאיזה טעמים שיהי') למעט מספר התלמידים - ניתנה עי\"ז שזה כמה שנים שההנהלה \"מצמצמת\" בקבלת תלמידים. אלא שכיון שברחמיו הרבים ניתן מהשי\"ת ענין התשובה, גם בהנ\"ל מועלת תשובה, אלא שצריכה להיות תשובה כפי הוראת תורתנו, שהנקודה בזה: הי' רגיל לקרות דף אחד יקרא ב' דפים כו', ובענינם הוא בהנוגע להגדלת כמות התלמידים ומובן שגם איכות התלמידים.</p>\n<p>בברכה לבש\"ט בכל האמור,</p>\n<p><b>מ. שניאורסאהן</b></p><p>מכתביהם מה' וז' אייר נתקבלו.</p>\n<p>מה הן התוצאות בהמשך להביקורים שהזכירו במכתבם דד' אדר (נציגי ארצה\"ב) וח' ניסן (מר רגב שי')?</p>\n<p>ההסתדר ענין הטליפון בבי\"ס אשר בכחב\"ד?</p>\n<p>במש\"כ בס\"א דמכ' כ\"ז ניסן - הרי כ\"פ עוררתי שצ\"ל משרתים בקודש מחב\"ד.</p>\n<p>ומובן שצריך להכינם גם בהיותם בכותלי תו\"ת, אבל פשוט שעל פי מש\"כ ע\"ד הדו\"ד שהי' בזה - צריך להעשות באופן שלא יוכל להתפרש שהם יוצאים נגד כל הישיבות וכו'.</p>\n<p>במש\"כ בהפר\"כ שקו\"ט ע\"ד נחיצות שיפור לימוד הנגלה ואם זהו סותר ללימוד דא\"ח וכו' - נפלאתי ונצטערתי גם על הספק בזה, כי פשוט שצריך ומוכרח להעלות ולשכלל לימוד הנגלה (ובמילא מוכרח גם ר\"י וכו'), ואין זה סותר ח\"ו ללימוד דא\"ח, לעבודת התפלה וכו'. - ולפשיטות כ\"ז מסתפק הנני בשורות אלו.</p>\n<p>בשאלתם על מי לשלם ההוצאות הקשורות עם ההלואה שקבלו - פשיטא שאינו נוגע מי הוא הערב. ועל הלוה לשלם גם הנ\"ל, כמו שמשלם ההלואה עצמה.</p>"],[1200870072,"ד'שמב\n\n<p>ב\"ה, ח\"י אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ כו' מו\"ה דוד מאיר שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מפסח שני, בו כותב אשר קבעו מגורם בדירה חדשה, ומעצם הדירה הנם שבעי רצון, אבל שכני המקום בלי מים זו תורה וכו'.</p>\n<p>לדעתי צריך להיות שבע רצון גם מענין השני ואפשר יותר מענין הראשון, וכמובן ממרז\"ל שלאחרי שהפליגו בגודל הענין דהמלמד את בנו תורה את בן בנו ואת בן חבירו תורה, מסיימים בגודל ההפלאה דלהוציא יקר מזולל המלמד את בן עם הארץ תורה (עיין קדושין ל, ע\"א, ב\"מ פה, א), והרי זה כל האדם שנברא לשמש את קונו ע\"י שיעשה לו ית' דירה בתחתונים, ודירת האדם אינה אלא דרך והכשר לעבודה זו, מכיון שכל מי שאין לו בית דירה אינו אדם (עיין לקו\"ת ברכה צט, ב. יבמות סג, א ובתוס' וחדא\"ג שם), ודירה טובה וגם יפה מרחיבה דעתו של אדם ובמילא מצליח יותר בפעולותיו לעשות הדירה להקב\"ה.</p>\n<p>בברכה צו א געזונטען זומער.</p>\n<h4><i><b>ד'שמב</b></i></h4>\n<p><b> מו\"ה דוד מאיר</b><b>:</b> שולמן, ברוקלין. אגרות נוספות אליו - לעיל חי\"ב ד'כב, ובהנסמן בהערות שם. לקמן ד'תפה.</p>"],[1200870073,"ד'שמג\n\n<p>ב\"ה, ח\"י אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ מלאכתו מלאכת שמים<br>\nמו\"ה יעקב שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"א אייר... נעם לי לקרות במכתבו ע\"ד פעולתו והשפעתו בחוג נערות ע\"י דברי התעוררות, הרצאות בתורת החסידות וכו', ובמענה לשאלתו בזה, נוהגים שבתור יסוד להרצאה, לוקחים ענין מספרים ומאמרים של רבותנו נשיאנו הק', אלא שמבארים אותו בהסברה לפי ערך השומעות והמקבלות, ומובן שבאופן כזה מוכרחת ההודעה שאין זה מאמר חסידות אלא הסברת המרציא וכו'.</p>\n<p>למרות הערתו שבאסיפות שבסניף נשי חב\"ד בירושת\"ו מדברים באידיש, כדאי שידבר עם המנהלות שבסניף זה, שבודאי יש כמה ביניהן שמדברות עברית, ועכ\"פ לשון הקדש, ויוכל לנצל אותן בהנוגע להשפעה על הבנות הנ\"ל, וע\"י התייעצות שביניהם בטח יחליטו ע\"ד חלק הארגוני שבזה והגישה...</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<p>נ.ב.</p>\n<p>בטח ניצלו יום הל\"ג בעומר, וכן מתכוננים לזמן מתן תורתנו הבע\"ל, ויה\"ר שיהי' בהצלחה.</p>\n<p>בודאי גם הוא השתתף בעבודת הרישום, ובמכתבו הבא יודיע ע\"ד התוצאות בשטח שלו.</p>\n<h4><i><b>ד'שמג</b></i></h4>\n<p><b> מו\"ה יעקב</b><b>:</b> אהרונוף, ירושלים.</p>\n<p><b> הרישום</b><b>:</b> לרשת אהלי יוסף יצחק.</p>"],[1200870074,"ד'שדמ\n\n<p>ב\"ה, ח\"י אייר, תשט\"ז</p><p>ברוקלין.</p><p>מרת מערי תחי'</p>\n<p> ברכה ושלום!</p>\n<p>... וואס אנבעלאנגט דאס דרוקען ווידער, דעם ספר הרקמה, רעכין איך אז עס איז וויכטיג צו פארעפענטליכען די צוגעגעבענע ראנד צושריפטען, וואס לויט ווי איך געדיינק אייער מאן ע\"ה זיינע פרעציעזע שטריינגקייט צו זיך אליין, און ספעציעל צו זאכען וואס ער האט געטראכט צו פארעפענטליכען - פובליצירען - מוז דאס זיין די צושריפטן פון אלגעמיינעם ווערט, און פון דעם שטאנדפונקט, איז פילייכט וויכטיג איבערהויפט צו פערעפענטליכען די ראנד צושריפטען צוערשט, און ניט צוזאמען מיטן איבערדרוקען אויך דעם גאנצען ספר הרקמה (וועלכע זיינען דאך פראנען, אויב אפילו אין א קליינע צאל עקסעמפליארן), און ווען אפילו די ראנד צושריפטען, דארפען נאך בעארבעט ווערען, איז ווי עס פירט זיך אין אזעלכע פעלע, ווערט צוגעגעבען א באמערקונג, אז דאס איז א באשריפט פון ראנד צושריפטען, און דעריבער איז מעגליך אז א טייל איז ניט בעארבעט, און איך גלויב אז עס [איז] דאך בעסער צו פארעפענטליכען אין דעם פארם איידער צו אונטערדריקען גענצליך די בעמערקונגען - אויב עס זיינען ניטא די מיטלען, און קענענדיג אייער מאנס האנדשריפט, רעכין איך, אז דאס קאפירען וועט זיין גרינג און מיט ווייניג פעלערן צו קארעגירען, אזוי ארום אז דאס דרוקען די ראנד צושריפטען, וועט ניט פאדערען צופיל קאסטען - עס וואלט מיר אינטערעסירען, וויפיל זייטען, אומגעפער, קען דאס ענהאלטען.</p>\n<p>מיט א וואונש צו א געזונטען גוטען זומער און צו גוטע נאכריכטע אין דאס אויבען געזאגטע.</p>\n<h4><i><b>ד'שדמ</b></i></h4>\n<p><b> מרת מערי</b><b>:</b> ווילנסקי, סיססינטי. אגרות נוספות אליו - לעיל חי\"ב אגרות ד'פא. ד'קצג.</p>\n<p>לקמן ד'תרצז.</p>\n<p><b> דרוקען... הרקמה:</b> ראה לעיל חי\"ב אגרת ד'פא.</p>"],[1200870075,"ד'שמה\n\n<p>ב\"ה, י\"ח אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... ובמה שכותב אודות בנו שליט\"א שלא תמיד שומע לדבריו, הנה בכגון דא לפעמים רבות מועילים דברי ידידים יותר מאשר דברי ידידים וקרובים גם יחד, ובטח יכול למצוא אנשים בעלי השפעה על בנו שידברו עם בנו אודות הענין שכותב פעם ופעמים ופעמים רבות, ויה\"ר שיצליחו, ועוד והוא העיקר שעליו להשתדל להשפיע בסביבתו שיהיו אידן אן פשרות, ואצ\"ל שלא יסתפקו בהנהגה של פיפטי פיפטי, וה' יראה ללבב שמשתדל בכל כחו בזולתו שיתנהג מתאים לרצון העליון, ואז במדתו של הקב\"ה שהיא מדה כנגד מדה אלא שכמה פעמים ככה ישולם לו בהנוגע לבניו ובני בניו שליט\"א.</p>\n<p>כהוראתו נמסרה נדבתו למוסדות חינוך על טהרת הקדש אשר בכפר חב\"ד</p>\n<p>שבארצנו הק' תבנה ותכונן על ידי משיח צדקנו, ואשרי שלוקח חלק להעמיד שומר האמיתי על ארצנו הק' ותושבי', ובלישנא דקרא, ה' יבנה בית וה' ישמר עיר (שאז דוקא יש תועלת בבנינים של בו\"ד ובשומר בו\"ד - תהלים קכ\"ז), וכמבואר בארוכה ע\"י ר' אבא בר כהנא ור' אמי ור' אסי, בפתיחתא במד\"ר לאיכה רבתי, ויה\"ר שבמהרה נזכה לביאת גואל צדק בחסד וברחמים.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'שמה</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ב ע' 435.</p>\n<p><b> בכפר חב\"ד... שומר:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>"],[1200870076,"ד'שמו\n\n<p>ב\"ה, י\"ח אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"ב אייר. - ת\"ל על הבשורה טובה מהטבת מצב לימודו, ובודאי לא יסתפק בזה ויוסיף ככל יכולתו, וכמבואר בחסידות ומהם גם בספר תניא קדישא, אשר לאחרי שהורגל בהטבה אפילו גדולה הרי ההרגל נעשה טבע ואין זה נקרא כלל וכלל עבודה וצריך להוסיף על זה, יעויין שם פרק ט\"ו בארוכה לפ\"ע.</p>\n<p>ובמ\"ש אם בתורת הדא\"ח שייך ענין החזרה בפנים כ\"פ, כן הוא, וכמו בשאר חלקי התורה, ומזה מובן ג\"כ שכמו שבכל חלקי התורה צריך להוסיף בלימוד התורה ואין להסתפק בחזרה לבד, כן הוא גם בלימוד תורת החסידות וכמובא בהלכות ת\"ת לרבנו הזקן פ\"ב ס\"ה ואילך בהאמור והוא נוגע הן ללימוד הנגלה והן ללימוד החסידות.</p>\n<p>ובמ\"ש סדר לימוד בדא\"ח, יתייעץ בזה עם זקני אנ\"ש אשר בסביבתו והם יורוהו, וה\"ה בהנוגע ללימוד הנגלה.</p>\n<p>ובשאלתו אם לשמוע סיפורים מפב\"פ שאומר שהי' תלמידו של פב\"ב, אבל רואה הוא שאין לו עכשיו שום שייכות עם חב\"ד, - הנה לפלא גם השאלה בזה, כי אם האמת שאין לו שום שייכות עם חב\"ד, פשוט שלא על ידו יתקרב לחב\"ד, ואדרבה.</p>\n<p>כבקשתו יזכירוהו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע להענינים שכותב, ויה\"ר שיבשר טוב.</p>\n<p>לפלא שאינו מזכיר דבר בהנוגע לפעולותיו במסגרת צעירי אגו\"ח, שבודאי עושה בזה ומוסיף מזמן לזמן, ובטח ימלא בהזדמנות הבאה.</p>\n<p>בברכה</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<p>במש\"כ ע\"ד החוברת סדר החזרה והזכרון - אין כאו\"א שוה בענינים כגון אלו.</p>\n<p>והתועלת תלוי' בתכונת כח הזכרון של כל אחד.</p>"],[1200870077,"ד'שמז\n\n<p>ב\"ה, י\"ט אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nצנמ\"ס וכו' הרש\"י שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתביו מז' וח' אייר:</p>\n<p>תמהתי ביותר במה שכותב בהנוגע למכתבי, שכיון שלא הי' כתוב בו למי נכתב, מצאו מקום לפירושים - פירושים שאינם הולמים את המכתב כלל וכלל, ב) אשר נשללו והופרכו מתוכן המכתב, ג) לא סמכתי על זה והדגשתי הדבר בסיום המכתב, בשלילת שתי הנקודות שמזכיר.</p>\n<p>א) אי אפשר הדבר שרציתי לפגוע בכבודו של זה שכתבתי אליו, כיון שתוכן מכתבי מוכיח ההיפך הגמור - בהכתוב שם בפירוש מרז\"ל ותיבת עשירים. ולא עוד - בסיום המכתב ציינתי להוריות י\"א סע\"א, ששם המדובר ברבנו הקדוש, שאין עליו התואר נשיא המדובר. והאומנם חושדים אותי ביחס בלתי הגון ח\"ו כלפי רבנו הקדוש?</p>\n<p>ב) במה שכותב אודות המדינה - הנה בכל המכתב אינו מדובר עד\"ז כלל וכלל.</p>\n<p>ובסיום בפירוש הדגשתי: בקשר עם עם בנ\"י בעת אשר... בנ\"י \"דווים דחופים... עליהם\" הבאה לקוחה מדברי רז\"ל (יבמות מז, א) אשר בודאי לא נעלם מכת\"ר, ונוגע <b>לדינא</b> בפסקי השו\"ע ולא נשמע שמי שהוא יאמר אשר עתה בטל דין זה. וקבלת גרים - תוכיח.</p>\n<p>ג) במ\"ש שפב\"פ נקרא בשם נשיא של מפלגה פלונית או סוג אנשים פלוני - לפלא הערתו בזה, כיון שלשלול קושיא זו, העתקתי בסיום מכתבי: לא נשיא שבט כו'.</p>\n<p>דרך אגב, מזה ג\"כ ראי' שאין כאן זלזול בכבודו של מי שהוא כי המדובר שם בנחשון בן עמינדב ראשון לנשיאים וכו'.</p>\n<p>וחלוק תוכן תואר נשיא בנדון דידן, שמשתמשים בו מכבר ובתוכן מסוים, בתוכן הקשור ברעיון המשיחי -</p>\n<p>בקורת רוח קראתי בעתונים כאן, אשר בהקונגרס שהתאסף עתה בירושת\"ו, הכריזו מעל הבימה, אשר פשיטא שעדיין לא נתגשם החזיון המשיחי, ואין זה ביאת המשיח וכו' ואיש לא מיחה נגד זה ואילו זכינו היו החרדים לדבר ה' מוצאים בנפשם די אומץ לאמר את זה, כשמונה שנים מלפנים, וכמה מהצרות שאירעו את בנ\"י מאז ועד עתה, לא היו באים כלל או היו באים במיעוט עכ\"פ. והצרה היותר גדולה - בלבול המוח של כמה מאחב\"י ובעיקר מבין הנוער.</p>\n<p>כל האמור הוא, לדעתי כל כך פשוט עד שמתחילה ספק הי' אצלי אם לענות בשלילת הפירושים, כי לכאורה רק ביאור אחד ישנו לחשד מוזר האמור כו', וא\"כ מה יועיל המענה. ומה שהכריעני לכתוב, הוא - נוסף על מאמר רז\"ל שצריך לדון כ\"א לכף זכות, ואפשר שמאלו הבאים בטענה, נדמה להם שיש איזה מקום לחשדים האמורים -</p>\n<p>העיקר מפני תמהוני וגם צערי שרציתי להביעו,</p>\n<p>ואם ימצא לנכון בקשתי שגם ימסור עד\"ז,</p>\n<p>והוא שבמכתבי בן שני עמודים גדולים לפי ערך, שתוכנו ועקרו -</p>\n<p>צעקת הלב בקלא פנימאה דלא אשתמע בחוץ על אלפים ורבבות מבני ישראל אשר בשנים ספורות האחרונות עזבו תורת אלקים חיים ומצותי', ודוקא מעת דרכם על אדמת קודש ארץ אשר עיני ה' אלקיך בה מראשית השנה ועד אחרית שנה, וברובם המכריע הם מהנוער - עתידו של עם בנ\"י.</p>\n<p>ואפילו את\"ל שאין כל כפי' בדבר כלל ואפילו לא בעקיפין</p>\n<p>הרי המאבד עצמו לדעת - גם כן נוקטים בכל האמצעים למנעו מזה ולהפריע בעדו.</p>\n<p>והנקודה היחידה אשר מזכיר כת\"ר במכתבו אלי ואשר כנראה אודותה לבד נדבר אתו - הוא ענין השמטת שם התואר!</p>\n<p>דא\"ג מכתבי נשלח במעטפה, ועל המעטפה כתוב גם שם התואר President ולו הי' יסוד לחששות האמורים, לא היתה המעטפה כתובה ככה. ובפרט שברירה פשוטה היתה בידי להניח המכתב במעטפה ע\"ש ידידנו שי' ולבקשם למסור המכתב פא\"פ.</p>\n<p>והחילוק מובן, שבתואר פרעזידענט אין בו החשש לתוכן הנ\"ל שלי. ואליבא דאמת - יותר מחשש, ע\"פ מה שראיתי תגובת הנוער על התואר נשיא בנידון זה.</p>\n<p>כדי לשלול גם קושיות מוזרות, הנני לתרץ עוד נקודה: מפני מה לא נשתמשתי בשם פרעזידענט בפנים המכתב.</p>\n<p>והוא פשוט: העדר כתיבת תואר הוא \"ענין\" שלי, ובפרט שכמה ישנם מהכותבים בלשון הקודש שמשמיטים התוארים לגמרי, בכדי שלא לבייש את מי שאין לו, משא\"כ שינוי תואר - הרי זה התערבות גם בענינים של הזולת. וגם זה פשוט לדידי, וחבל על הזמן להסיר קושיות שאין להם יסוד, אלא שכל זה כדאי לי באם יגרום לאיזה פעולה בהנוגע לתוכנו האמיתי של מכתבי.</p>\n<p>בכבוד וברכה לבשו\"ט.</p>\n<h4><i><b>ד'שמז</b></i></h4>\n<p><b> הרש</b><b>\"</b><b>י</b><b>:</b> זוין, ירושלים. אגרות נוספות אליו - לעיל ד'שי, ובהנסמן בהערות שם.</p>\n<p><b> מכתבי</b><b>:</b> דלעיל חי\"ב ד'רכו.</p>"],[1200870078,"ד'שמח\n\n<p>ב\"ה, י\"ט אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג וו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה אלכסנדר סענדער שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"ד אייר... ובמ\"ש שי\"א שצריך להכות בתעמולה ופעולות עד שישרה השלום בין... כי השלום ביניהם גדול מהכל, מובן שאף שצודק האומר בפתגמו שגדול השלום וכידוע בכמה דרשות רז\"ל ומובן גם מסיום המדרש אסתר רבה בסופו, שברוב השלום תלוים כל הענינים אבל פשוט ג\"כ שאין לעכב שאר הפעולות אפילו לרגע וע\"פ מכתב הידוע של כ\"ק אדמו\"ר (מוהרש\"ב) נ\"ע הועתק במבוא לקונטרס ומעין (עמוד כב) שבזמננו זה אין זה סדר לבירורים וצריך להתעסק בכל הבא לידו יעו\"ש...</p>\n<p>במ\"ש אודות ענין מקוה בקבוץ מפלסים, צריך הי' להתדבר עם מרכז טהרת המשפחה בירושלים עיה\"ק ת\"ו ומובן שהרשות בידו לאמר ליו\"ר המרכז הרה\"ג כו' הלפרין שי' שעושה זה ע\"פ הצעתי ובטח יכתוב מהמשך הדבר, בקשר בנין המקוה ובכל הנ\"ל.</p>\n<p>המחכה לבשו\"ט ומפורטות.</p>\n<h4><i><b>ד'שמח</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 451 והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> מו\"ה אלכסנדר סענדר:</b> יודאסין, תל אביב. אגרות נוספות אליו - לעיל חי\"ב ג'תתס, ובהנסמן בהערות שם. לקמן ד'תרסז.</p>"],[1200870079,"ד'שמט\n\n<p>ב\"ה, י\"ט אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... במ\"ש בנוגע לכאב שינים, והרופאים מייעצים לעקור כו' - הנה אף שידוע מרז\"ל (פסחים קיג, א) בהנוגע לעקירת שינים (ויש חסידים מספרים שלכן הרה\"ג הרה\"ח והרה\"צ ר' הלל נ\"ע מפאריטש נזהר שלא לעקור שן), אבל לא ראיתי נזהרים בזה, ואפילו לא בבית הרב. ומובן ע\"פ הידוע בהנוגע להרפואות שבש\"ס, ושנשתנו הטבעים. ולא עוד אלא שאסור לנסות בזה וכמובא ממהרי\"ל (רע\"ק ליו\"ד סי' שלו).</p>\n<p>דא\"ג פעם שמעתי מכ\"ק מו\"ח אדמו\"ר שזהו לבד* הלחש למי שנתחב לו עצם וכו' (שבת סז, א) שהיו למדים אותו אפילו לתינוקות של בית הרב, ובעת הצורך, ל\"ע ול\"ע, היו אומרים אותו בהקדמת העמדת קערה על הראש - ולכן אף שצ\"ע אם יש לעשות בקצה האחרון, מה שמיעצו רופא אחד לעקור כל השינים ח\"ו אלא להתייעץ עם עוד מומחים בזה, ואפשר מספיק אחד או שנים וכו'.</p>\n<h4><i><b>ד'שמט</b></i></h4>\n<p>*) שוב מצאתי כן גם במהרי\"ל - בסופו בליקוטים.</p>"],[1200870080,"ד'שנ\n\n<p>ב\"ה, כ' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה משה שי'<br>\nהכהן</p>\n<p> שלום וברכה!</p>\n<p>בשעתו קבלתי מכתבו שכותב ע\"ד השם המתאים להתאחדות שני הבתי כנסיות, ולפי בקשתו לזרז במענה, מסרתי חוות דעתי בטעלעפאן בזה, וכבקשתו באתי בזה גם במכתב, והוא:</p>\n<p>אשר אף שענין השם תופס מקום חשוב בתורה ובמנהגי ישראל, שמזה מובן שגם בהנוגע לשמות בתכ\"נ - צריך לדייק בזה, בכל זה מובן שעוד יותר נוגע נוסח התפלה שמתפללים בו בבית הכנסת,</p>\n<p>והנה האריכו בכמה שו\"ת האחרונים בהנוגע לשינוי הנוסח, ומסקנא האחרונה היא, שאפשר לשנות מנוסח אשכנז לנוסח ספרד, אבל לא מנוסח ספרד לאשכנז. ומזה מובן ג\"כ, עד כמה נוגע שיהי' דוקא נוסח אר\"י שהוא עוד בדיוק נוסף בנוסח ספרד עצמו.</p>\n<p>ובפרט נוסח רבנו הזקן שהוא הנקרא עתה נוסח האריז\"ל, שרבנו הזקן בירר מכמה נוסחאות - ועל פי המסופר בן זקני החסידים בדורות שעברו, שבעת שקבע וכתב הסידור שלו, ביררו מששים סידורים נוסחאות שונות. ולכן לדעתי גם בשם שני בתי כנסיות המאוחדות צ\"ל התיבה נוסח האריז\"ל - בכדי לקבוע העיקר, שהוא נוסח התפלה כנ\"ל.</p>\n<p>ויה\"ר שיצליחו לקבוע בכל המתפללים - שהתפלה תפעול פעולתה בכל שעות היום.</p>\n<p>וכוונתי כפשוטה, שהברכה הראשונה בבקשת צרכיו שהיא בקשת הבנה ודעת, יעמדו בהשתוקקות זו גם באמצע היום, והברכה שלאחרי' - בקשה להתעוררות תשובה ולסליחה על עוונות, תעמוד בקשה זו להתעוררות תשובה גם בעת העסקים כו' וכו'.</p>\n<p>ואין לך דבר העומד בפני הרצון.</p>\n<p>בברכה לבשו\"ט</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ד'שנ</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ט ע' 277 והושלמה ע\"פ צילום האגרת.</p>\n<p><b> מו\"ה משה</b><b>:</b> שאייעוויטש, שיקגו. אגרות נוספות אליו - לעיל חי\"ב ד'ריד, ובהנסמן בהערות שם.</p>\n<p><b> והנה האריכו:</b> ראה גם לעיל חי\"א אגרת ג'ת, ובהנסמן בהערות שם. חי\"ב ד'יב. לקמן ד'תקסג.</p>\n<p><b> ועל פי המסופר:</b> בית רבי פד, א.</p>"],[1200870081,"ד'שנא\n\n<p>ב\"ה, כ' אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>לפלא שמעת מכתבו מכבר בו כתב אודות התעוררות לבבם של כמה מחבריו להוסיף אומץ בהתמדה ושקידה בלימוד תורת הנגלה ותורת החסידות וכן להדר בקיום מצותי', אין ממנו ידיעות נוספות, והרי ידוע הציווי שבכל יום ויום יהיו בעיניך כו' להוסיף על היום שעבר הן בתורה והן במצות, ובטח ימלא בהזדמנות הכי קרובה ובפרטיות הדרושה.</p>\n<p>וכבר ידועה הוראת נשיאנו הק' שתלמיד ישיבת תומכי תמימים צריך להתייעץ בעניניו ובפרט בנוגע לתעמולה בין התלמידים, עם המשפיעים והר\"י שלו, שהוא משומעי לקחם, ובטח גם בפו\"מ נוהג כן אף שלא הזכיר עד\"ז במכתבו הנ\"ל, ומובן ג\"כ שהתלמידים שעזרו ועוררו צריכים להיות הם עצמם דוגמא חי' ולמופת באופן הנהגתם ולימודם.</p>\n<p>בברכה להצלחה המחכה לבשו\"ט</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>"],[1200870082,"ד'שנב\n\n<p>ב\"ה, כ' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה יהודא זרחי' מרדכי ליב חיים שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מער\"ח אייר והקודמים לו. - נעם לי לקרות בו שזיכו אותו בפרס על חידושי תורתו, ויה\"ר שיזכה ללמוד תורה לא עמלק\"פ כדבר משנה, ופירושו שמקבלים פרס אבל יודעים שאין זה אלא פרס מלשון פרוסה*, ובמילא דרכו של עני - אין עני אלא בדעת בפרוסה, אבל הזוכה לטעום מדעת תורה מעריך את הענין שבלימוד התורה ששכר מצוה מצוה, שיכול לקיים רצונו של הקב\"ה, ומזה תוצאות על אתר שממלא עניניו שאי אפשר לעשותם על ידי אחרים, היינו ענינו בתור רב ומורה הוראה במילואם, אף שלפעמים הרי העסק בצ\"צ מפריע לפי שעה בלימוד התורה שלכן הרי פטרוהו רז\"ל, והרי מובן גודל הערך של ענין דאי אפשר לעשותו על ידי אחרים, משני הקצוות, דחפצי שמים, היינו מצות אינם שוים לדבר אחד מדברי תורה, אבל אם אי אפשר לעשותם על ידי אחרים הלא לא רק ששוים המה אלא שגם דוחים דברי תורה (מו\"ק ט' ע\"ב) ויעוין ג\"כ ספר תניא קדישא סוף פרק ל\"ז.</p>\n<p>ובאותו ענין בהנוגע ללימוד הכתה אשר בסביבתו הט', לפלא גדול שעד עתה לא נעשו כלשונו במכתבו, בבחי' חי נושא את עצמו, ולא לסיוע מאנשי הסביבה והוא בראשם עד שכנראה גם ממכתבו האמצעים וחיפוש התל' כל הענין הזה הוטל על אנשים הבאים מבחוץ, והשאר הם באופן של מסייע שאין כו'.</p>\n<p>כבקשתו אזכירו ואת זוגתו שי' ואת כל אלה שכותב אודותם על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע להמצטרך להם כפי כתבו, וכשם שכתב מההטבה בהענינים לגבי העבר, יה\"ר שיהי' טוב עוד יותר.</p>\n<p>בברכה לבשו\"ט ולהצלחה במושפעיו ובסביבתו שעי\"ז יתוסף בהצלחה גם בעניניו הפרטים במדתו של הקב\"ה שהיא מדה כנגד מדה אלא שכ\"פ ככה.</p>\n<p>נ.ב.</p>\n<p>במ\"ש במכתבו מאז בהענין דימי הפורים ע\"פ המבואר בס' תורה אור למגלת אסתר ד\"ה ומרדכי יצא, והחילוק להמצב בעת מתן תורה, יעויין בזה גם בס' שערי אורה קפ\"ה קצ\"ב, ועוד שמשם תוספת ביאור להנ\"ל.</p>\n<h4><i><b>ד'שנב</b></i></h4>\n<p>*) ראה לקו\"ת שה\"ש יז, א.</p>\n<p><b> מו\"ה יהודא זרחי' מרדכי ליב חיים</b><b>:</b> סגל, תל אביב. אגרות נוספות אליו - לעיל חי\"ב ד'מה, ובהנסמן בהערות שם. לקמן ד'תרמג.</p>"],[1200870083,"ד'שנג\n\n<p>ב\"ה, כ' אייר, תשט\"ז</p><p>ברוקלין.</p><p>מר אביגדור שי'</p>\n<p> שלום וברכה!</p>\n<p>בצער קבלתי הידיעה ע\"י הוו\"ח אי\"א נו\"נ עוסק בצ\"צ בעל מדות ורב פעלים מו\"ה מאיר שי' בליזינסקי אודות מצב בריאותו של כבודו ובעת רצון אזכירו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, אשר בחיים חיותו בעלמא דין עבד עבודתו בתור רועה ישראל חדורה אהבת ישראל לכל אחד ואחד ועל פי פתגם כ\"ק מו\"ח אדמו\"ר בשם הבעש\"ט שענין אהבת ישראל הוא אפילו לאיש הישראלי הנמצא בקצה תבל שמעולם לא ראהו, עאכו\"כ לאיש אשר השגחה העליונה חוננה אותו בכח השפעה בסביבתו הקרובה ואפילו הרחוקה שכל הטבה במצבו הן הגשמי והן הרוחני גורמת ומביאה הטבה בכלל בכל אלו המושפעים ממנו, היינו שנכפלת כ\"פ ככה, ומזה מובן ג\"כ גודל הזכות של אדם זה ואחריותו בהביא בחשבון אשר זיז שלו אפילו קל מתגדל כ\"פ ככה ע\"י התוצאות של זיז זה בסביבתו תלמידיו ומושפעיו, ולכן תקותי חזקה אשר לעת קבלת מכתבי זה כבר הוטב מצב בריאותו כפשוטו וד' הרואה ללבב מכיר ג\"כ ההחלטה לשינוי באותם הענינים אודותם שוחחנו בביקורו כאן וגם רמזתי עליהם במכתבי לכ', וזה עוד יוסיף בברכת רופא כל בשר ותהי' רפואתו רפו\"ק.</p>\n<p>המצפה לבשו\"ט וחותם באיחולים לבריאות הנכונה בגו\"ר.</p>\n<h4><i><b>ד'שנג</b></i></h4>\n<p><b> אביגדור</b><b>:</b> המאירי, רמת גן.</p>"],[1200870084,"ד'שנד\n\n<p>ב\"ה, כ' אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח וו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה זישא שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"ב אייר. נעם לי לקרות בו מהטבת מצב בריאותו, ובודאי שזה הביא תוספת בעבודתו בקדש, וע\"ד פתגם כ\"ק רבנו הזקן בעל התניא והשו\"ע, שהקב\"ה נותן ליהודים גשמיות והם עושים מגשמיות רוחניות.</p>\n<p>ובמה שעורר בדברי המהר\"ל בהקדמתו לס' תפארת ישראל, וז\"ל: הת\"ח לבו דבוק אל התורה וכו' אהבתו אל התורה דבר זה מסלק אהבת המקום בשעה זאת שבאים ללמוד כו' כי אין אהבה לשנים. ותמה למה לזה קורא שנים, ומה סתירה בין האחת לחברתה. - ואין הס' עתה תח\"י, ושקו\"ט ע\"פ העתקת כת\"ר.</p>\n<p>הנה מובן הוא ע\"פ הנראה במוחש בתכונת נפש האדם, כי בעת לימוד ענין שכלי ואפילו לימוד התורה, שצ\"ל באופן שיבינה וישיגה, נרגש במוח הלומד השכל שבדבר, וכיון שבעל שכל הוא ומשתוקק לשכל ובפרט לשכל מסוג זה, מצליח בהבנתו והשגתו, וכהוראת רז\"ל לעולם ילמוד אדם במקום שלבו חפץ. ומלבד יחידי סגולה - הרי החשק והאהבה לענין שכלי אפילו נעלה ביותר מפני שבטבע הוא בעל שכל, מסלק אהבת המקום שהוא מפני כי הוא חיינו וכיו\"ב, כי אלו הם שני ענינים. נוסף לדברי מהר\"ל הם סותרים זא\"ז, אבל רואים במוחש שאכן כן הוא, כי אהבת השכל היא אהבה המופנה כלפי עצמו שהוא האוהב שכל ויש לו טעם בזה והנאה, וממילא הרצון וחשק שלו בלימוד או בפלפול וכיו\"ב, משא\"כ אהבת המקום שבעיקרה צ\"ל מצד ההפלאה וריחוק הערך שבינו לבין בוראו, וק\"ל.</p>\n<p>ומזה מובן ג\"כ החילוק שבהיוצא משתי האהבות, האחת בידיעת התורה - בידיעתה הרי אפשר שכמרז\"ל לא זכה נעשית לו סם מות, היינו שמביאה לגיאות וכו', משא\"כ אם היא אהבת המקום שבאה מהתבוננות בגדלות הבורא, וכלשון הרמב\"ם הל' יסוה\"ת ריש פרק ב', שמביאה דוקא לביטול והעדר מציאות עצמו, וככל ששוקד יותר על אהבה זו - גדול הביטול בנפשו, עד שנעשה שפל במאד. - ועיין ב\"ח בטואו\"ח סמ\"ז, דברים חוצבים להבות אש.</p>\n<p>ונקודות מהאמור לעיל יש לדייק גם ברמב\"ם סוף הל' תשובה במ\"ש שם, איך צריך להיות קיום המצות ולימוד התורה וכו'. וראה ג\"כ אגרת הקדש לרבנו הזקן סי' ב'. וע\"פ כל הנ\"ל מובן ג\"כ דיוק רבנו הזקן בתניא סוף פרק מ\"א (נ\"ח ע\"ב) וז\"ל: קודם שיתחיל ללמוד צריכה הכנה זו לפחות כנודע שעיקר ההכנה לשמה לעכב הוא בתחלת הלימוד בבינונים. שמדייק <b>בתחלת</b> הלימוד, כי בבינונים אי אפשר שילמוד ע\"מ להבין ולהשיג ובשעת מעשה יעמוד בביטול ובלי הרגש מציאותו אפילו כח החכמה וההבנה שלו. וכבר נודע מרז\"ל - צדיקים הם מועטים.</p>\n<p>בברכת הצלחה בעבודתו בקדש ולהחדיר במושפעיו לימוד התורה חדורה אהבת ה'.</p>\n<h4><i><b>ד'שנד</b></i></h4>\n<p><b> מו\"ה זישא</b><b>:</b> וואלטנר, טנגיר. אגרת נוספת אליו - לקמן ד'תרל.</p>\n<p><b> פתגם</b><b>:</b> ראה גם לעיל חי\"ב אגרת ג'תתקמג, ובהנסמן בהערות שם.</p>"],[1200870085,"ד'שנה\n\n<p>ב\"ה, כ\"א אייר, ה'תשט\"ז</p><p>ברוקלין, נ.י.</p><p>צו די אנפירערשאפט און אנטיילנעמערינס<br>\nאין דער<br>\nקאנווענשאן פון אגודות נשי ובנות חב\"ד<br>\nניו-יארק, נ.י.<br>\nה' עליהן תחיינה</p>\n<p> ברכה ושלום!</p>\n<p>איך שיק דערמיט א באגריסונג און ברכה צו די דעלעגאטינס און חברות און צו אלע אנטיילנעמערינס אין דער קאנווענשאן, דינסטאג כ\"ז אייר, און האף צו השם יתברך, אז די פארזאמלונג וועט זיין מיט גרויס דערפאלג און ברענגען די געוואונשענע רעזולטאטן.</p>\n<p>די צייט צווישן פסח - דער יום-טוב פון אונזער אויסלייזונג פון מצרים, און שבועות - דער יום-טוב פון אונזער באקומען די תורה, איז ספעציעל צוגעפאסט פאר יעדער טעטיקייט וואס באצוועקט צו פארשטארקן דאס לערנען תורה און טאן און מקיים זיין מצוות, ווארום דאס איז דאך די צייט פון צוגרייטן זיך אויפצונעמען די תורה.</p>\n<p>באזונדערס איז די צייט מסוגל פאר פרויען ארבעט אין דער ריכטונג, נעמענדיק אין אכט וואס אונזערע חכמים, זכרונם לברכה, דערציילן וועגן די באזונדערע פארדינסטן פון די אידישע פרויען אין צוזאמענהאנג מיט די דערמאנטע צוויי געשעענישן: בא יציאת-מצרים - אז אין זכות פון די פרויען צדקניות זיינען אונזערע עלטערן אויסגעלייזט געווארן פון מצרים; בא מתן תורה - אז דער אויבערשטער האט געהייסן משה רבינן ריידן צוערשט מיט די פרויען און דערנאך מיט די מענער, וואס דורכדעם וועט דאס אננעמען פון דער תורה פארשטארקט און פאראייביקט ווערן.</p>\n<p>און יעדעס יאר אין דער צייט באנייט זיך די ג-טלעכע ברכה און השפעה ווי זי איז צוערשט אנפלעקט געווארן. מען דארף אבער צוגרייטן און שאפן די פאסנדע מיטלען און כלים כדי אויפצונעמען און אויסניצן די ברכה - אין דער צייט און אויף א לאנגע צייט נאכדעם.</p>\n<p>אין בין שטארק אין דער האפנונג, אז יעדע איינע פון אייך וועט זיך אריינטראכטן אין דער גרויסער פליכט וואס עס ליגט אויף די וועלכע האבן זוכה געווען צו זיין פארבונדן מיט אגודת נשי ובנות חב\"ד, און אויסניצן די גרויסע געלעגנהייטן און מעגלעכקייטן, וועלכע די קאנווענשאן שטעלט מיט זיך פאר, צו פארשטארקן און אויסברייטערן די טעטיקייט פון יעדן סניף בכלל און פון יעדער חברה בפרט.</p>\n<p>צוזאמען מיט א פארגרעסערונג אין דער אינערלעכער ארבעט פון די אגודות נשי ובנות חב\"ד, דארף און מוז אייך זיין אן אויסברייטערונג פון דער ארבעט מיטן צוועק אויסצושפרייטן איר ווירקונג אויך אויף פרויען וועלכע זיינען דערווייל נאך ניט פון חב\"ד, אין ענגען זין פון ווארט, און צוציען זיי צו אייער קרייז און סניף, וואס דורכדעם וועט מען זיי אויך צוברענגען צו די לעבעדיקע און לעבנסגעבנדע קוואלן פון אידישקייט ווי זיי זיינען דורכגעדרונגען מיט דער אינערלעכער ווארעמקייט און ליכטיקייט פון חב\"ד חסידות-לערע און לעבנס שטייגער.</p>\n<p>זיכער וועט אויסגעארבעט ווערן אן ארבעטס-פראגראם אויך אין דער ריכטונג.</p>\n<p>השם יתברך זאל מצליח זיין אייער ארבעט, איר זאלט זי אנפירן און דורכפירן מיט הצלחה און פרייד, אין גוטן געזונט און מיט פיל נחת, אידישן און חסידישן נחת, פון יעדן פון דער פאמיליע שיחיו און פון זיך אליין.</p>\n<p>בברכת הצלחה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ד'שנה</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ז ע' 250 והושלמה ע\"פ צילום האגרת.</p>\n<p><b> דער קאנווענשאן</b><b>:</b> סקירה נרחבת מהכינוס, וכן מהפעילות הכללית של אגונ\"ח, נדפסה בחוברת מיוחדת \"ערשטע נאציאנאלע קאנווענשאן אגודת נשי ובנות חב\"ד אייר תשט\"ז\" (קה\"ת ל\"ג בעומר תשי\"ז).</p>"],[1200870086,"ד'שנו\n\n<p>ב\"ה, כ\"א אייר, תשט\"ז</p><p>ברוקלין.</p><p>אגודת נשי ובנות חב\"ד באה\"ק ת\"ו<br>\nסניף ירושלים עיה\"ק ת\"ו<br>\nד' עליהן תחיינה</p>\n<p> ברכה ושלום!</p>\n<p>לאחרי ההפסק הארוך נתקבל מכתבן מל' ניסן, נוסף על הפ\"ש ע\"י הרבנית מרת חוה גורארי' שתליט\"א, ויהי רצון שכשם שבמכתבן זה מבשרות אודות החזקת הפעולות והרחבתן, הרי במכתביהן הבאים יודיעו ובפרטיות הדרושה אודות הרחבת הפעולות עוד יותר מתאים לדרישת השעה, שבטוחני שתהיינה גם כן בהצלחה, וביחוד נעם לי לקרות אודות הרעיון דיסוד מועדון בתוכן דתי בשביל הנוער, שלפי המצב זהו אחד הענינים היותר נחוצים, ובודאי גם נקודה זו ירחיבוה, וכוונתי כפשוטה, ביסוד עוד מועדונים ובהרחבת המועדון שיסדו כבר.</p>\n<p>כן ברצוני להדגיש כאן עוד הפעם, על דבר התועלת הכי גדולה הנשקפת מהשפעת החבירות דנשי ובנות חב\"ד על האמהות דתלמידים-ות הלומדים במוסדות חינוך חב\"ד, כי מלבד שעל ידי זה מחזקים את הקשרים בין התלמידים-ות והחינוך על טהרת הקדש שמקבלים, הנה גם בהנוגע לההורים עצמם, יש לקוות לשינוים גדולים וטובים, כיון שכבר מוכשרים במקצת על כל פנים על ידי העובדא שבנם או בתם מבקרים במוסד חינוך של חב\"ד, ועל ידי התאמצות הדרושה והתייעצות עם הנהלת המוסדות, בטח תוכלנה לתכנן פעולותיהן שיביאו לתוצאות הכי גדולות וטובות.</p>\n<p>מהנכון שיודיעו עכ\"פ השערה אודות הוצאות הכרוכות ביסוד מועדון על דרך האמור.</p>\n<p>מוסגר פה העתק מכתבי כללי, שגם אליהן הדברים שייכים.</p>\n<p>בברכה לחג מתן תורתנו הבע\"ל, ולהרחבת הפעולות בתוספת מרץ וחיות</p>\n<p>המתחדשים ונוספים אצל כל איש ואשה הישראלים ע\"י מתן תורה וקבלת התורה מחדש, ובפרט ע\"פ הוראת רז\"ל במאמרם הידוע בכל יום ויום יהיו בעיניך כחדשים.</p>"],[1200870087,"ד'שנז\n\n<p>ב\"ה, כ\"א אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> ברכה ושלום!</p>\n<p>במענה על מכתבה מי\"ב אייר, בו כותבת אודות הבעיא שעומד לפני' בקשר עם השידוך שלה בשעה טובה ומוצלחת עם האברך...</p>\n<p>הנה בטח במשך הזמן ימצאו פתרון גם לבעיות אלו שסוף סוף טפלות הן בערך לעיקר הענין, הוא בנין בית בישראל על יסודי התורה והמצוה, ובתקופתנו שישנם כמה וכמה השמים אור לחשך וחשך לאור, מוכרחים להיות אפילו יסודות אלו מוארים וחדורים מאור שבתורה זוהי פנימיות התורה שבתקופה זו נתגלתה בתורת החסידות ועניני', שעל ידי זה מתמעטת האפשרות לחליפין הנ\"ל, ולבלבול ענינים, וכיון שכותבת שהכירה בתקופה האחרונה עניני חב\"ד, תקותי שהכרה זו תבוא לפועל בחיי-ה מתאים להאמור, וגם זה יקל בפתרון הבעיות אודותם כותבת.</p>\n<p>וזכות התעסקותה בחינוך על טהרת הקדש במוסד אהלי יוסף יצחק ליובאוויטש, יעמד לה לתוספת ברכה מהשי\"ת הצלחה בעבודתה עבודת החינוך ובעניני' הפרטים.</p>\n<p>בברכה.</p>"],[1200870088,"ד'שנח\n\n<p>ב\"ה, כ\"א אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מעש\"ק והפ\"נ, בו כותב ע\"ד הספיקות שחלו אצלו בהנוגע לסדר לימודו בהחברותא וכו'.</p>\n<p>כבר מבואר בכ\"מ ענין הקבלת עול שמוכרח להיות מתלמיד בהנוגע להרב, ומיוסד על מרז\"ל על הכתוב שפתותיו שושנים נוטפות מור עובר, וה\"ה בנדון דילי' שצריך לפרט עניניו בצירוף הטעמים ונימוקים שלו לפני הר\"מ והר\"י ומשפיע דא\"ח שלו, אבל אחר כך צריך להתנהג דוקא כהוראתם ואז מצליחים להיות מקבל כדבעי, שזהו ג\"כ הכשר והכנה והקדמה להיות במשך הזמן גם משפיע כדבעי, ועיין ג\"כ השיחה הידועה בנדון זה, נדפסה בתורת שלום עמוד פ\"ד.</p>\n<p>בודאי שומר שלשת השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר</p>\n<p>זצוקללה\"ה נבג\"מ זי\"ע, בחומש תהלים ותניא הידועים.</p>\n<p>ולהודעתו מיום הולדת שלו (בודאי ינהג במנהגי יום הולדת כפי שנוהגים בזה אנ\"ש בזמן האחרון), הנה יה\"ר שתהי' שנת הצלחה אצלו בגשמיות וברוחניות בלימוד התורה וקיום המצות בהידור.</p>\n<h4><i><b>ד'שנח</b></i></h4>\n<p><b> בתורת שלום</b><b>:</b> בדפוסים החדשים ע' 75.</p>\n<p><b> במנהגי יום הולדת</b><b>:</b> ראה לעיל אגרת ד'שלט, ובהנסמן בהערות שם.</p>"],[1200870089,"ד'שנט\n\n<p>ב\"ה, כ\"א אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו משילהי ניסן, בו כותב הסיבות והטעמים למה שנמצא ועובד בעניני כו', ונפקד מקומו בשטח פעולות חב\"ד עכ\"פ פעולות במילואן.</p>\n<p>והנה אפילו את\"ל שצודקים טעמיו בכל המאה אחוז... עדיין אינו מובן, מה יתוסף עי\"ז בפעולות חב\"ד ואיך יעשה עי\"ז נוטר כרמו שלי, וכבר כתבתי לכמה מאנ\"ש שעיקר פעולות בתקופה זו הוא ע\"פ מאחז\"ל שפירשו כ\"ק אדמו\"ר הצמח צדק, אנן פעלא דיממא אנן, צו מאכען ליכטיג, וליכטיג כדבעי, נעשה ע\"י מאור שבתורה שמתגלה בתורת החסידות ועניני', און ניט פון זיצען אויף א אנדער וואגען, ולהאריך הסברה בהרחב הביאור מפני מה נמצא שם ולא פה, לא יתוסף עי\"ז בהאמור, ובפרט שברור בעיני שמופרך הדבר, שמי שהוא מאנ\"ש אין לו אפשריות בשטח חב\"ד כיון שנשיאנו הק' דורשים את זה מכל או\"א אין נקי.</p>\n<p>והנה אף כי פשיטא שלא היתה כוונתי במה ששואל אותי במכתבו זה, אם יעזוב ענין שפרנסתו בזה לע\"ע מבלי לדעת מקודם איפוא ימצא להוצאות שלו ושל ב\"ב שיחיו, כי זהו הנהגה דתהו, אבל כאמור, וגם זה לכמה מאנ\"ש, שזכינו בדורנו זה שהענינים הרוחנים מתן שכרם בצדם שכר בענינים גשמים, אף שמובן שלא כל השכר ורק פירות ופרי פירותיהן, ואין כאן המקום להאריך, ובפרט שרואים את זה במוחש.</p>\n<p>במ\"ש אודות היסוד בכפר חב\"ד קורס מזורז למורים, נכון הדבר, וכן נכון יסוד כל ענין שאפשר בכפר חב\"ד, אם יש רק היכולת שיהי' על טהרת הקדש, אבל מובן ג\"כ שצריך מי שהוא שיתעסק בזה.</p>\n<p>ובסיום מה דפתח, איני בא בכאן בהוראות פרטיות באיזה ענין בשטח חב\"ד יתעסק, ומשני טעמים, כבר נוכחתי לדעת שאנ\"ש מדקדקים במאמר רז\"ל ילמוד במקום שלבו חפץ, ונלמד בבנין אב לכל עניניהם שיהי' דוקא במקום שלבם חפץ, ובמילא אין תועלת בהוראת הפרטים, וכן הפרטים תלוים בהענינים המשתנים מזמן לזמן באה\"ק ת\"ו לעתים קרובות, אבל ודאי הדבר שיכול לפעול בשטח חב\"ד, ובאם ירצה באמת יכול לפעול גדולות, ויה\"ר מהשי\"ת שיכיר כל הנ\"ל בקרוב ממש ויבוא בפועל בקרוב...</p>\n<p>בברכה לבשו\"ט.</p>\n<p>מסיבה נתאחר השילוח, ובנתיים נתקבלו מכתביו מכ\"ח אייר וג' סיון. והתעסקותו בעולי מרוקו המתאימים לרוח כחב\"ד שיתיישבו בכחב\"ד נכונה וטובה מאד מאד. וכן להכניס ילדיהם לתו\"ת ולאח\"ת. ונחוץ מאד <b>שיתועדו</b> עמהם בלה\"ק לעתים תכופות, כי מתאוננים שאין מקבלים מההתועדויות כ\"א בדרך מקיף, כיון שאין מבינים אידית.</p>\n<p>הגדולים (ובפרט הנשואים) אין כדאי להכריחם להתפלל דוקא בנוסח חב\"ד ומנהגיו. ואלו שיכנסו לתו\"ת אח\"ת וביסל\"מ - במילא יתרגלו בנוסח זה.</p>\n<h4><i><b>ד'שנט</b></i></h4>\n<p><b> כרמו שלי</b><b>:</b> ראה לעיל חי\"ב אגרות ג'תתקצט. ד'פו. ד'קצ. לקמן ד'תקכה.</p>\n<p><b> כתבתי לכמה מאנ</b><b>\"</b><b>ש</b><b>:</b> ראה לעיל ח\"י אגרת ג'קב, ובהנסמן בהערות שם.</p>\n<p><b> מאחז</b><b>\"</b><b>ל</b><b>:</b> עירובין סה, א.</p>\n<p><b> שפירשו</b><b>:</b> ראה גם לעיל ח\"י אגרת ג'מא, ובהנסמן בהערות שם.</p>"],[1200870090,"ד'שס\n\n<p>ב\"ה, כ\"א אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מלפני הפסח - שהתארך בדרך הילוכו -</p>\n<p>א) בשאלתו אם גם להבא ימשיך בסדר הלימוד שלו דעת עתה שלומד בישיבה עד צהרים, ואח\"כ נוסע לביתו ל...</p>\n<p>הנה מובן שלא זו הדרך ובפרט בגיל שלו, ואף שהי' מוכרח כפי כתבו בסדר האמור, לדעתי תיכף כשיסור ההכרח יש להסתדר באהלה של תורה כל היום, והוא נוגע לא רק בכמות אלא גם באיכות, כוונתי כשיודע שבכל יום ויום נמצא ג\"כ בעניני מסחר וכיו\"ב, הרי גם בשעת הלימוד גורם זה חסרון בהתרכזות ובהתמדה ושקידה, וכנראה במוחש, ופשוט שאם מי שהוא מבני הבית לע\"ע אינו מסכים על סדר הלימוד דכל היום, יש לדבר אתו פעם ושתים וכמה פעמים, וכאשר מדברים בדרכי נועם ודרכי שלום סו\"ס מצליחים, לשכנע גם אותו.</p>\n<p>ב) במה שכותב אודות תיקון בענין הידוע.</p>\n<p>הנה לכל לראש צריך להסיח דעת מזה, וכיון שמחשבת האדם משוטטת תמיד, אופן הגירוש דמחשבה בלתי רצוי' היא, ע\"י הלבשת כח המחשבה במחשבה רצוי', ומה טוב במחשבת אור דתורה אור, שאפילו מעט אור דוחה הרבה חשך, וצריך להיות זהיר בטבילת עזרא, ואמירת תהלים לאחר התפלה בכל בקר, קביעות עתים לימוד במאור שבתורה זוהי פנימיות התורה, שבתקופתנו נתגלתה בתורת החסידות \"דלית תמן לא קושיא מסטרא דרע ולא מחלוקת מרוח הטומאה וכו'\" (עיין אגרת הקדש לרבנו הזקן סי' כ\"ו), ונתינה לצדקה איזה פרוטות בכל יום חול קודם תפלת הבקר, והשתדלות בהשפעה על הזולת, ובפרט על הנוער לקרבו לתורה ומצותי' ולמאור שבתורה, שעל ידי כל זה זוכים לסייעתא דשמיא ולהצלחה בעניני תורה ומצות של עצמו.</p>\n<p>בברכה לבשו\"ט בכל האמור לעיל.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>"],[1200870091,"ד'שסא\n\n<p>ב\"ה, כ\"א אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ כו' מו\"ה שלום דובער שי'<br>\nשו\"ב</p>\n<p> שלום וברכה!</p>\n<p>לאחרי שתיקתו הארוכה נתקבל מכתבו מיום הבהיר הילולא דרשב\"י, ונהניתי לקרות בו שלומד עם כתה כפי מסורת אבותינו הק' קמ\"ץ אל\"ף א, וכידוע קדושת האותיות והנקודות שהם למשה מסיני, וכמובן ופשוט בזהר ובתקו\"ז בכמה מקומות, ולא רק האותיות ונקודות עצמן אלא אפילו שמותיהם, וכמובא שם ששמות הנקודות הם ראשי תיבות שמות מלאכים וכו'...</p>\n<p>בברכה.</p>\n<h4><i><b>ד'שסא</b></i></h4>\n<p><b> מו\"ה שלום דובער שי':</b> רסקין, לונדון. אגרת נוספת אליו - לעיל ח\"ח ב'תכא.</p>\n<p><b> קדושת האותיות</b><b>:</b> ראה גם לעיל חי\"א אגרת ג'שפו, ובהנסמן בהערות שם.</p>"],[1200870092,"ד'שסב\n\n<p>ב\"ה, כ\"א אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה יוסף שי'</p>\n<p> שלום וברכה!</p>\n<p>... בהנוגע להתקדמות בנין הישיבה אחי תמימים אשר במחנם הט' שהתחילו כבר להתפלל בבנין נוסף על הלימוד בו, שיהי רצון שהתפלה תוסיף חכמה בינה ודעת בהלימוד, ולימוד תורת חיים ודא\"ח יוסיף חיות בתפלה, ובמילא תתוסף ברכת השי\"ת והצלחתו בענינים הפרטים של הלומדים ומתפללים, ועאכו\"כ המתעסקים [בכל] האמור, וכמ\"ש עץ חיים היא למחזיקים בה ותומכי' מאושר.</p>\n<p>ויוסיף כח ואומץ בהשתדלות בכל האמור שבודאי יתוסף עי\"ז בבריאותו הוא בבריאות זוגתו וכל בני המשפחה שי', ותתוסף ההצלחה גם בעניני הפרנסה.</p>\n<p>בפ\"ש כל אנ\"ש שיחיו, ובפרט המתעסקים בהענין דישיבת אחי תמימים ברשל\"צ ולקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ד'שסב</b></i></h4>\n<p><b> מו\"ה יוסף:</b> שמוטקין, ראשון לציון. אגרת נוספת אליו - לעיל חי\"א ג'תרנד.</p>\n<p><b> התקדמות בנין הישיבה</b><b>:</b> ראה גם לעיל אגרת ד'רעט, ובהנסמן בהערות שם.</p>"],[1200870093,"ד'שסג\n\n<p>ב\"ה, כ\"א אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... ובמ\"ש אודות פב\"פ שחש לעין הרע וכו', הרי בענינים כגון אלו, כשאין משימים לב לזה כלל והיסח הדעת בתכלית, מבטלים אותם, וכיון שהזכיר עד\"ז במכתבו, הנה יבדוק את התפילין שלו ואת המזוזות בדירתם, וזוגתו תי' תחזיק במנהג בנות ישראל הכשרות להפריש לצדקה קודם הדלקת הנרות בכל עש\"ק וערב יום טוב...</p>\n<p>בברכה.</p>\n<p>נ.ב.</p>\n<p>במ\"ש שעשו מצבה באותיות בולטות, תמוה הדבר, ובפרט שמה שאמרו לו שקשה לשכחה, יסודו בדברי רז\"ל (הוריות יג, ב ועפמשנ\"ת בטעמי המצות להרח\"ו פ' ויחי). ועוד נוסף בזה שאין צריכים לשנות מרוב המצבות, ולכן לדעתי יש לבקש את האומן שיעשה אותיות שקועות וכמנהג כשר בישראל.</p>\n<p>ומסיימים בטוב, שיבשר טוב בהנוגע להוספה בלימוד תורתנו, תורת חיים, וקיום מצותי' וחי הם.</p>"],[1200870094,"ד'שסד\n\n<p>ב\"ה, כ\"ב אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג וו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה דוד<br>\nשי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו, נעם לי להוודע ממנו, שבהשיעורים בבית הכנסת הי' ג\"כ לימוד הלכות שבת, אבל כנראה ממכתבו זהו בעבר ואין שיעור זה קיים עתה; ועוד זאת אף שידוע הכרח הלימוד דהלכות שבת, וכמו שהפליג בזה באגה\"ק לרבנו הזקן בעל התניא והשו\"ע (עיין שם קונטרס אחרון, קסג, ע\"א), אבל מובן ג\"כ שמוכרחת הידיעה בהלכות דימות החול וכמו הלכות ברכות, הנחת תפילין, תפלה, ברכת הנהנין וכו', אשר העדר הידיעה בהם מבהיל, ולא עוד אלא שמועטים המשימים לב ללימוד זה מפני שלבם חפץ דוקא בפלפולא דאורייתא וכו', וד\"ל. ולכן תקותי שישתדל לתקן הדבר, וזכות הרבים תלוי בו, ולהעיר ג\"כ מהלכות תלמוד תורה לרבנו הזקן פ\"ב סעיף טי\"ת, ובהקדמת בניו בהדפסתם השו\"ע שלו.</p>\n<p>ולקראת חג השבועות הבע\"ל, הנה יה\"ר, וכפתגם כ\"ק מו\"ח אדמו\"ר, שנזכה לקבלת התורה בשמחה ובפנימית.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'שסד</b></i></h4>\n<p><b> מו\"ה דוד:</b> ווינשסטר, שיקגו. אגרת נוספת אליו - לעיל ד'רצו. וראה שם לתוכן האגרת שלפנינו.</p>"],[1200870095,"ד'שסה\n\n<p>ב\"ה, כ\"ב אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... במענה על מכתבו מי\"ד אייר, בהנוגע למקום חינוך בני אנ\"ש שיחיו.</p>\n<p>ברור הדבר אשר נשיאינו הק' נשיאי חב\"ד - הם המנהלים בפועל מוסדות חינוך חב\"ד לכל סוגיהם: ישיבות, ת\"ת, ביסל\"מ, בי\"ס לנערות וכו'. - ואשריו של כאו\"א מאנ\"ש (וכל אחב\"י בגדר אנ\"ש הם) שיחנך בניו ובנותיו שיחיו במוסדות אלו לטוב להם בגשמיות וברוחניות, בטוב הנראה והנגלה.</p>\n<p>- ופשוט שברשותו וגם זכותו הוא להודיע השקפתי ודעתי ברורה זו לכל הרוצה לשמוע. ועליו ולשומע - יונעם.</p>\n<h4><i><b>ד'שסה</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ב ע' 417.</p>"],[1200870096,"ד'שסו\n\n<p>ב\"ה, כ\"ב אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה ישראל צבי שי' הלוי</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מיום הבהיר הילולא דרשב\"י, בו כותב שמקוה להמשיך ע\"י קישור מכתבים עם אותם שהתחיל להשפיע עליהם לקרבם לתורה ויהדות, ובודאי לא יסתפק בהמשך בלבד, כי תורתנו תורת חיים דורשת להוסיף, וכפסק הידוע דמעלין בקדש, ובפרט בזמננו שכל רגע יקר ביותר וביותר, מתאים לפתגם כ\"ק מו\"ח אדמו\"ר אשר הנה זה (מלכא משיחא) עומד אחר כתלנו, אלא שצריך לסיים בירורי הפכים קטנים, ומזה מובן ג\"כ עד כמה נחוצה התרחבות פעולת נשי ובנות חב\"ד, אשר ע\"י הוספה אפילו קטנה לפי ערך בהן, מתוסף כמה פעמים ככה בסביבתן, כי נשים דברניות הן ועסקניות הן...</p>\n<h4><i><b>ד'שסו</b></i></h4>\n<p><b> מו\"ה ישראל צבי שי':</b> הבר, תל אביב. אגרת נוספת אליו - לעיל חי\"ב ג'תתסח.</p>"],[1200870097,"ד'שסז\n\n<p>ב\"ה, כ\"ב אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה יוסף שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מי\"ג אייר עם המוסגר בו, ות\"ח ת\"ח על השתדלותו בענין הכי נעלה דכולל חב\"ד, וכידוע עד כמה השתדלו בזה כל נשיאנו הק' כאו\"א בדורו, החל מרבנו הזקן בעל התניא והשו\"ע ועד לדורנו זה, שמזה מובן ג\"כ גודל הנחת רוח הנגרם ע\"י כל המשתדלים בזה ומגדילים את הדבר.</p>\n<p>ומה שכותב שלע\"ע הסתפק במועט מפני הקישוים שבגביית הסכומים, רצוני לפרש התיבה <b>שמסתפק</b> שאין זה סיפוק אמיתי אלא רק הפסק בעבודה בשביל תוספת כח לאחרי ההפסק, שבכדי שתהי' תועלת ההפסק במילואה צריך להיות מתוך מנוחת הנפש, וזהו פירוש ענין ההסתפקות, ומובן שהפסק כגון דא גם זה לעבודה יחשב כיון שמנצלים אותו לתוספת בעבודה.</p>\n<p>ובהביא בחשבון מאמר רז\"ל אשר יותר ממה שהנותן עושה עם המקבל, המקבל עושה עם הנותן, הרי עאכו\"כ אשר <b>בגבית</b> צדקה, שאך לרגע הוא המקבל, הנה עוד יותרת פעולתו בהנוגע להנותן, והתבוננות זו וכעין זו מגדילה סיפוק הנפש של גבאי הצדקה עד שמוסיף גם בבריאות כפשוטה, וע\"ד מ\"ש שמועה טובה תדשן עצם, שהוא גם בפשטות וכנודע מסיפור רז\"ל.</p>\n<p>במ\"ש שלע\"ע סניף הת\"ת במקום החדש אינו מצליח, בודאי ישתדלו ככל הדרוש בעריכת דעי קעמפ שם, שזה ישמש בסיס והכנה טובה וקרובה לרכישת תלמידים לזמן לימודים הבע\"ל, ולדעתי ח\"ו לחשוב ע\"ד חיסול הסניף שם.</p>\n<p>אכפול ברכתי בקשר עם הידיעה מאז ובכתיבתו גם עתה במכתבו זה, אודות ארבעת החדרים אשר רכש בקדש, שלאריכות ימים ושנים טובות הרי הוא וזוגתו שיחיו ירבו בעניני תורה ומצות בשמחה ובטוב לבב הן בממונם והן בגופם.</p>\n<p>איני יודע הנהגת הת\"ת שבהנהלתו בהנוגע לל\"ג בעומר, אבל בשנה זו שחל ביום שהתלמידים פנוים מלימודי חול, בודאי הוסיפו בזה כהנה וכהנה. ויה\"ר שההוספה יהי' רישומה ניכר גם בימים ושבועות שלאחרי זה.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'שסז</b></i></h4>\n<p><b> מו\"ה יוסף</b><b>:</b> פלייער, שיקגו. אגרות נוספות אליו - לעיל חי\"ב ג'תתלט, ובהנסמן בהערות שם.</p>\n<p><b> סיפור רז\"ל:</b> גיטין נו, ב.</p>\n<p><b> סניף הת\"ת במקום החדש</b><b>:</b> ראה לעיל חי\"ב אגרת ג'תתקכז, ובהנסמן בהערות שם.</p>"],[1200870098,"ד'שסח\n\n<p>ב\"ה, כ\"ב אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ כו' מו\"ה נפתלי שי' הכהן</p>\n<p> שלום וברכה!</p>\n<p>נעם לי לקבל מכתבו מט\"ז אייר, בו כותב אודות פרטי הלימודים עם הכתות שהשפעתו עליהם, ובודאי משתדל וכן משתדלים חבריו להרבות מספרם, כוונתי מספר המשתתפים בכל כתה וכתה, שבענין זה הוא כל' מרז\"ל, נר לאחד נר למאה, ועיין הלכות תלמוד תורה לרבנו הזקן, פרק א' סעיף ג' בהנוגע למספר המשתתפים בכתה אחת, וכשישתדלו בזה בודאי יצליחו, וגודל הענין אינו נצרך לביאור, ואשרי המשתדלים בארגון כתות אלו הלומדים <b>לפניהם</b> וכדרז\"ל, ובפרט בארצנו הק' אשר עיני ה\"א בה מראשית השנה עד אחרית שנה.</p>\n<p>ואף שאין זה פוטר מלימוד בפ\"ע, הן בנגלה והן בחסידות, כמובן ופשוט, ובפרט לימוד תורת החסידות המביא חיות בעניני האדם בכלל ובהשפעה על הזולת ביחוד, כבר ידוע פתגם רבנו הזקן בעל התניא והשו\"ע, אשר על ידי הצדקה עם הזולת נעשים מוחו ולבו זכים אלף פעמים ככה, וכשלומד שיעורו מצליח ביותר וביותר.</p>\n<p>ומטובו למסור הנ\"ל לחבריו העוסקים בעבודה כגון דא, ויה\"ר שכאו\"א מהם יבשר טוב מהתפתחות המפעל ומהגדלת השתתפותו בו.</p>\n<p>בברכת הצלחה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ד'שסח</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ב ע' 368 והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> מו\"ה נפתלי שי</b><b>':</b> ראטה, ירושלים. אגרת נוספת אליו - לעיל חי\"ב ד'רסא. לקמן ד'תקמד. ד'תשו.</p>"],[1200870099,"ד'שסט\n\n<p>ב\"ה, כ\"ג אייר, תשט\"ז</p><p>ברוקלין.</p><p>מחות' הרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה גרשון<br>\nשי' וזוגתו הרבנית מרת גסיא תחי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבם מעש\"ק, ובמ\"ש אודות המאורע בכפר חב\"ד, הנה כבר כתבתי לכמה מאנ\"ש אשר דברי נשיאנו רבוה\"ק חיים וקיימים לעד, ואינם יוצאים מידי פשוטם, ועאכו\"כ שאין מקום לפירוש שהדברים אמורים בנוגע לאחרים אבל לא לזה שאין הדבר מתקבל בשכלו, ובכגון דא הוראת רבותנו ברורה היא, אשר במקום זה תתגלה מדת הרחמים שהיא גדולה ממדת החסד שלפני' נחלה בלי מצרים מבריח מן הקצה אל הקצה, ועל כל אחד ואחת אשר חוננו השי\"ת בכח השפעה לא רק לחזק רוח תושבי הכפר אלא להראות גם דוגמא בזה מתאים למעמדו ומצבו, וכשיתבונן בודאי ימצא הדברים והאותיות שיוכל לפעול בכיוון זה...</p>\n<p>בעת רצון אזכיר את כל אלו שכותבים אודותם על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, ויה\"ר שיבשרו טוב בכל האמור ובקרוב ממש.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'שסט</b></i></h4>\n<p><b> מו\"ה גרשון:</b> חן, חיפה. אגרות נוספות אליו - לעיל חי\"א ב'תתקעח, ובהנסמן בהערות שם.</p>\n<p><b> המאורע בכפר חב\"ד:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>"],[1200870100,"ד'שע\n\n<p>ב\"ה, כ\"ה אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה יוסף שי'<br>\nשו\"ב</p>\n<p> שלום וברכה!</p>\n<p>לאחרי שוב הפסק ארוך במכתביו, נתקבל מכתבו מכ\"ב לחודש זה, ומובן אשר סיבת העדר הכתיבה שכותב הוא, שאין מה לכתוב ולהודיע, אין זה מתרץ הקושיא, אלא אדרבה עוד מגדיל אותה, כי איך זה אפשר אשר אחד מאנ\"ש ובפרט מהתמימים ובפרט מהמשרתים בקדש, שבודאי זוכר המבואר בדא\"ח בתוכן הכתוב ימים יוצרו ולו אחד בהם, אשר כל יומא ויומא עביד עבידתי', ובאם לאו יומא ערטילאי הוא, יכתוב שלא כתב משך כמה שבועות וחדשים, מפני שלא הי' מה לכתוב, ובפרט שנמצא בעיר בה עשיריות אלפים מישראל, ונוכח לדעת שחלק מסוים מהם עדיין זקוק לבריאות ברוחניות, הבאה על ידי עניני תורה ומצות, כי רמ\"ח מ\"ע הם נגד רמ\"ח אברים ושס\"ה מצות ל\"ת כנגד שס\"ה גידים, ומובן ופשוט ג\"כ שלפום גמלא שיחנא, ומקודם ניתנו לו הכחות הנצרכים לעבודה זו.</p>\n<p>אקוה שניצלו את יום הבהיר ל\"ג בעומר הילולא דרשב\"י באופן המתאים, אף שאינו מזכיר עד\"ז, וכן ינצלו את ימי הסגולה הבע\"ל, ונעם לי לקרות במכתבו שגם מר...</p>\n<p>השתתף בהתועדות, וכדאי ונכון לחזקו ולעודדו לזמנים תכופים אותו ואת זוגתו שיחיו, וד\"ל.</p>\n<p>בברכה לבשו\"ט בכל האמור לעיל.</p>\n<h4><i><b>ד'שע</b></i></h4>\n<p><b> מו\"ה יוסף</b><b>:</b> גולדשטיין, סינסיטי. אגרות נוספות אליו - לעיל ח\"ט ב'תתקנג.</p>"],[1200870101,"ד'שעא\n\n<p>ב\"ה, כ\"ה אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>לאחרי שתיקתו הארוכה נתקבל מכתבו מכ\"א אייר, בו כותב איזה סיבות שמרפות ידיו בלימוד ספרים השייכים לקבלה.</p>\n<p>והנה לפלא, כי בטח בעת היותו פה נדבר ע\"ד לימוד תורת החסידות, ומובן ששונה הוא, ובמילא אין מקום להסיבות אותם מזכיר במכתבו, אף שבאמת גם בהנוגע ללימוד הקבלה אינם סיבות לעכב את הלימוד, ובפרט בהנוגע ללימוד תורת החסידות, הנלמד משך כמה דורות, ולא - כמו שכותב - ע\"י הקדמת לימוד הזהר דוקא, ופשיטא שלימוד זה לא החסיר בשלימות האדם, אלא אדרבה עוד הוסיף בזה, כוונתי לומר - שנוסף על הידיעה שבתורת החסידות, הרי לימוד זה מוסיף אור וחיות, ובמשך הזמן גם הבנה, בלימוד שאר חלקי התורה.</p>\n<p>אלא שככל התורה כולה, שבמה דברים אמורים שנברא בעל גבול יכול לקבלה, אף שארוכה מארץ מדה וגו' - דוקא על ידי הקדמת נעשה לנשמע, וכמובן גם כן מסוגית הש\"ס בזה (שבת פ\"ח ע\"א) אשר דוקא תומת ישרים תנחם, משא\"כ וכו', הרי כן הוא גם בכל חלק מתורתנו הק', ותורת החסידות בכלל זה כמובן, וכמדומה שגם על אודות נקודה זו נדבר כשהי' כאן. ויהי רצון שיבשר טוב בקרוב בהנוגע לבנין בית בישראל בנין עדי עד, ועוד קודם לזה ע\"ד קביעות בלימוד פנימיות התורה (וכפתגם רבנו הזקן בעל התניא והשו\"ע, קביעות בזמן וקביעות בנפש), אשר הא מסייע להא - ויעוין עירובין נ\"ג ע\"ב עלץ בנערה שני הפירושים אשר שייכים זה לזה. ובקידושין ל, ב.</p>\n<p>בברכה, וכמאמר המשנה חייב אדם לומר בלשון רבו, הוא כ\"ק מו\"ח אדמו\"ר, לקבלת התורה בשמחה ובפנימיות, ופ\"ש חבריו שי' בברכת החג האמורה.</p>\n<h4><i><b>ד'שעא</b></i></h4>\n<p><b> שככל התורה</b><b>:</b> ראה גם לעיל אגרת ד'רעז, ובהנסמן בהערות שם.</p>\n<p><b> וכפתגם</b><b>:</b> ראה גם לעיל חי\"ב אגרות ד'קכו. ד'רטז. לעיל ד'שכב. לקמן ד'תיז.</p>\n<p><b> שני הפירושים</b><b>:</b> אמרי לה אשה ואמרי לה מסכתא.</p>\n<p><b> קדושין</b><b>ל</b><b>, </b><b>ב</b><b>:</b> אם אשה ממש היא... אם תורה היא.</p>"],[1200870102,"ד'שעב\n\n<p>ב\"ה, כ\"ה אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"ג אייר, בו שואל איך אפשר להסביר ההכרח דכיסוי הראש.</p>\n<p>ולפלא על השאלה בזה, ובפרט כשנמצאים עתה בימי הכנה לקבלת התורה, שרק על ידי הקדמת נעשה לנשמע קבלנוה, וכסוגיא הידועה (שבת פ\"ח ע\"א) על שאלת הצדוקי, איך לא רצו להבין <b>מתחלה</b><b>,</b> והמענה על זה כמ\"ש תומת ישרים תנחם (משא\"כ) <b> וגו',</b> וכבר ידוע דיוק לשון המשנה (ברכות ריש פרק ב') יקבל עליו <b>עול</b> מלכות שמים כו' <b> עול</b> מצות כו', אלא שברצות ה' דרכי איש זוכים להבין אפס קצהו מטעמי המצות, אבל גם אז צריך לקיימן בדוקא בקבלת עול ולא מפני שמוצא טעם בשכלו <b>המוגבל</b> של הנברא לציוויו של הבורא שהם באין ערוך, ומובן ופשוט שאמונת האדם באלקים מכרחת בדיון <b>שכלי</b> קבלת ציוויו של האלקים מבלי לדרוש הסברה בשכל <b>האנושי</b> עליהם, שהרי גם שכל הפשוט, אם רק בריא הוא, מבין שאי אפשר לבעל גבול להבין את הבלתי בעל גבול, והרי זה מיסודי האמונה של כל בני ישראל מאמינים בני מאמינים, אשר השם יתברך שהוא ודעתו <b>ורצונו</b> אחד הוא בלתי בעל גבול אמיתי, והאדם הוא מוגבל בכל עניניו.</p>\n<p>נוסף על כל הנ\"ל, הנה בהביא בחשבון שכר המפורש בענינים דכיסוי הראש (עיין באריכות בזהר הק' חלק ג' קכ\"ו ע\"א), הרי אפילו אם הי' זה רק בדרך ספק וספק ספיקא ח\"ו, גם כן כדאית הטרחה לכיסוי השערות משום הס\"ס, ועאכו\"כ שדברי הזהר שהם חלק מתורתנו תורת אמת, אמיתים הם, וקיימים ונצחים <b>בכל</b> מקום <b>ובכל</b> זמן.</p>\n<p>כפי שמראה הנסיון, הנה כשלפעמים אין פב\"פ מצליח להשפיע על פב\"פ, טוב לעשות ולהשתדל להשפיע בעקיפין, על ידי ידידים ומכירים, וכשמשתדלים בזה בלי ליאות, הרי בדברי נועם ובדרכי שלום סו\"ס מצליחים. ועוד זאת להעיר אשר ברובא דרובא, כשרואים שאין מצליחים להשפיע על הזולת בעניני תורה ומצות, הנה מניעה פנימית בזה, שהמשפיע מקיל בעניני תורה ומצוה, אף כי במצות אחרות, ובמילא ישולם לו בהעדר הצלחה דברי התעוררות שלו, כי מדתו של הקב\"ה מדה כנגד מדה, והרי כל המצות שייכות אחת לחברתה, כי כולם ביחד הם קומה שלימה, וכמרומז במאמר רז\"ל, רמ\"ח מצות עשה כנגד רמ\"ח אברים של אדם שס\"ה מצות לא תעשה כנגד שס\"ה גידים, שכללות האברים והגידים הם גוף אחד ואחיד, וכשיוסיף בהצריך תיקון בעניניו הוא בודאי תתוסף ההצלחה בהשפעתו גם על בת גילו תחי' ויהי רצון שיבשר טוב בכל האמור.</p>\n<p>ומהנכון לבדוק את התפילין שלו וכן אשר בקשר עם השידוך והחתונה בשעה טובה ומוצלחת, יקבע לימוד בפנימיות התורה היא תורת החסידות, ובכל יום לאחר תפלת הבקר יאמר השיעור תהלים - כפי שנחלק התלים לימי החדש - מתאים לתקנת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>בברכה לבשו\"ט בכל האמור לעיל ובברכת מזל טוב מזל טוב לבנין בית ישראל בנין עדי עד על יסודי התורה והמצוה.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ד'שעב</b></i></h4>\n<p><b> כיסוי הראש</b><b>:</b> באשה.</p>"],[1200870103,"ד'שעג\n\n<p>ב\"ה, כ\"ה אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מיום הבהיר ל\"ג בעומר הילולא דרשב\"י, בו כותב אודות מצב בריאותו וכן בהתוצאות מזה בנוגע ללימודו. וכיון שנמצא בטפול רופאים מומחים המתייעצים כפי כתבו איש עם רעהו יש לשמוע להוראתם, ויה\"ר שיקוים בו מאמר רז\"ל התורה נתנה רשות לרופא לרפאות שאז היא רפואה מתאימה ופעילה. ובהנוגע ללימוד, הרי יכול הוא לקבוע לימוד לגירסא למשך זמן ולראות איך זה ישפיע עליו.</p>\n<p>ומובן ופשוט שמה שכותב שנמצא בדכאון נפשי וכו', הרי זה מעצת היצר ותחבולותיו למנוע את האדם ממילוי תפקידו בעולם, הוא כדבר משנה אני נבראתי לשמש את קוני שצ\"ל בשמחה דוקא, וכביאורו של המורה הגדול הוא הרמב\"ם (סוף הלכות לולב) בדברים נפלאים ומפליאים יעויין שם, אליבא דנפשי', ואז יגיל וישמח בשמחה אמיתית וע\"ד האמור בכל דרכיך דעהו, וכמבואר ענין שמחה זו ואיך לבוא אלי' בספר התניא עיי\"ש פרק ל\"א ואילך, ועבודה זו מביאה ג\"כ תוספת בבריאות הגוף וכנראה במוחש.</p>\n<p>בברכה לבשו\"ט בכל האמור ולקבלת התורה בשמחה ובפנימיות.</p>"],[1200870104,"ד'שעד\n\n<p>ב\"ה, כ\"ה אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>לאחרי ההפסק נעם לי לקבל מכתבו מיום הבהיר ל\"ג בעומר הילולא דרשב\"י.</p>\n<p>ובמ\"ש אודות הענין דמחשבות זרות, הנה צריך לבדוק את התפילין שלו וכן שיהיו חקוקים בזכרונו איזה פרקים משניות ואיזה פרקים תניא, ומזמן לזמן יעבור עליהם בכדי לא לשכחם וכן אשר בכל עת מצוא הנה יתפלל וילמוד מתוך הספר, אשר כל זה ביחד יועיל להאמור, אבל העצה העיקרית היא שבכל עת שמרגישים במחשבה זרה [וידוע הדיוק בזה, שלא דוקא מחשבה אסורה או אפילו בטלה, כי אם אפילו מחשבה זרה בערך למעמדו ומצבו], יסלקה וידחנה על ידי מחשבה טובה, שהרי המחשבה משוטטת תמיד, ודיחוי מחשבה בלתי רצוי' הוא על ידי מחשבה רצוי' ואין לך דבר העומד בפני הרצון.</p>\n<p>ובפרט אשר משתדל בקירוב לבן של בני ישראל לאבינו שבשמים בכל מקום שהשפעתו מגעת, ובפרט בין אלו הנמצאים במעמד ומצב של משמעת ורואים גם בעיני בשר עד כמה ההנהגה דקבלת עול יסוד היא לכל כ\"ד שעות היום, שמזה מובן במכל שכן וקל וחומר איך שהוא בנוגע לכל אחד מצבאות ה' הם בני ישראל במילוי פקודת מלכם ממה\"מ הקב\"ה.</p>\n<p>ויהי רצון שיוסיף בדברי התעוררות אלו ובכל האפשרות, ובמדתו של הקב\"ה שהיא מדה כנגד מדה אלא שכמה פעמים ככה, יתוסף גם בעניניו הפרטים הברכה וההצלחה, ובפרט שמתקרבים אנו לימי חג השבועות זמן מתן תורתנו שקבלנוה על ידי הקדמת נעשה לנשמע.</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות ובפ\"ש חבריו הנ\"ל ומטובו למסור גם להם ברכתי האמורה.</p>"],[1200870105,"ד'שעה\n\n<p>ב\"ה, כ\"ה אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ הרב מו\"ה נחום<br>\nשי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו. - כבקשתו יזכירוהו ואת ב\"ב שיחיו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע להמצטרך להם, ויהי רצון שיתעסק ככל יכולתו בהחזקת כל עניני היהדות בסביבתו ומושפעיו הקרובה ואפילו הרחוקה, וכבר נודע מאמר רז\"ל - בהנוגע לבני ישראל, אני ישנה (בגלותא) ולבי ער להקב\"ה לתורתו ומצותי', אלא שצריך המעורר לעורר בדברים היוצאים מן הלב ואז נכנסים ללב השומעים, וכשמעוררים וחוזרים ומעוררים הרי סו\"ס פועלים פעולתם בהנוגע לפועל ובחיי היום יומים, וכיון שהטוב הוא בלי גבולי, הרי תמיד ישנו מה להוסיף לשפר ולשכלל והשי\"ת יזכהו לעשות בזה מתוך בריאות והרחבת הדעת.</p>\n<p>בברכה כלשון המורגל בפי כ\"ק מו\"ח אדמו\"ר לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ד'שעה</b></i></h4>\n<p><b> מו\"ה נחום</b><b>:</b> בורשטין.</p>"],[1200870106,"ד'שעו\n\n<p>ב\"ה, כ\"ו אייר, תשט\"ז</p><p>ברוקלין.</p><p>ועד כפר חב\"ד<br>\nד' עליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת הפרטי-כל מימי כ\"ז ניסן ה' י\"ד וט\"ו אייר, ובודאי במשך הזמן נתקבל מכתבי מענה על הפ\"כ הקודם, ואחכה לבשו\"ט בהענינים אודותם נכתב שם.</p>\n<p>זה איזה זמן שהתכתבתי עם מר דוד שי' הלמן רוקח, בהנוגע לפתיחת מרקחת בכפר חב\"ד, וכנראה ממכתביו אשר לא נפלאת היא. וכיון שתלוי הענין בפרטים ופרטי פרטים, מהנכון הי' שיתדברו עמו ויבררו כל הפרטים אשר בזה, והרי גם זה נכנס במסגרת התפשטות והתרחבות כפר חב\"ד.</p>\n<p>בברכה.</p>\n<p>תמיהתי (מהולה בצער קצת) על אשר ברוב קטעי המכ\"ע שנתקבלו ומתקבלים גם עתה נזכר בדוקא השם שפריר! והרי זה כו\"כ עוררתי ע\"ד נחיצות קביעות שם כחב\"ד ובדוקא. ולפלא שכנראה ענין זה קל בעיניהם, בה בשעה שארז\"ל שמא מילתא הוא.</p>\n<p>ומוכח גם מיני' ובי', מזה שהמכ\"ע כותבים בדוקא ההיפך. וד\"ל. ובטח עתה שעת הכושר להביא בפועל גם את זה, ולכלול (בשם זה או: כחב\"ד א' וב') גם הכפר הישן...</p>"],[1200870107,"ד'שעז\n\n<p>ב\"ה, כ\"ו אייר, ה'תשט\"ז</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"נ מלאכתו מלאכת שמים וכו'<br>\nמו\"ה אבא שי'</p>\n<p> שלום וברכה!</p>\n<p>... בטח מוסיף אומץ בלימוד הכתה ובלימוד ת\"ת דרבים, ובפרט בעת זו הדורשת ריבוי הכלים בכפר חב\"ד לקבלת ברכות השי\"ת בהפלגה, הבאות ממדת הרחמים שהיא נעלה ממדת החסד שלפני' נחלה בלי מצרים מבריח מן הקצה אל הקצה וכהוראת נשיאינו הק'.</p>\n<h4><i><b>ד'שעז</b></i></h4>\n<p><b> מו\"ה אבא שי':</b> לוין, כפר חב\"ד.</p>\n<p><b> ובפרט בעת זו</b><b>:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>"],[1200870108,"ד'שעח\n\n<p>ב\"ה, כ\"ו אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה דוד משה שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתביו, הנה ת\"ח על הבשו\"ט שביה\"ס מתקדם ומתרבה מספר</p>\n<p>התלמידים, ובטח משתדל ג\"כ בהרמת האיכות. ויה\"ר שכולם יעבדו שכם אחד בהנהלת המוסד הק' אשר על שם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע בהתפתחותו והתרחבותו, ותתברך עבודתם בהצלחה מופלגה.</p>\n<p>בודאי יודיע בפרטיות אודות תוצאות הרישום, התכנית לימי החופש בקיץ הבע\"ל, ומה טוב כמו שכתבתי כ\"פ על אודות סידור קייטנא בכפר חב\"ד אשר שם צוה ה' את הברכה, וכידוע מאמר קדושי עליון ומהם אדמו\"ר הזקן אדמו\"ר האמצעי ואדמו\"ר הצמח צדק, אשר תתגלה שם מדת הרחמים שהיא גדולה ממדת החסד שלפני' נחלה בלי מצרים מבריח מן הקצה אל הקצה, עיין בדרך מצותיך להצ\"צ דף קי\"ד סוף ע\"ב.</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות ולבשו\"ט בכהנ\"ל.</p>\n<p>הפ\"נ שבמכתבו יקרא בעת רצון על הציון הק', ויבש\"ט בזה.</p>\n<h4><i><b>ד'שעח</b></i></h4>\n<p><b> מו\"ה דוד משה שי</b><b>':</b> גרין.</p>\n<p><b> וכידוע מאמר</b><b>:</b> ראה לעיל אגרות ד'רפא, ד'שז, ובהנסמן בהערות שם.</p>"],[1200870109,"ד'שעט\n\n<p>ב\"ה, כ\"ו אייר, תשט\"ז</p><p>ברוקלין.</p><p>אגודת נשי ובנות חב\"ד<br>\nסניף מאנטרעאל,<br>\nד' עליהן תחיינה.</p>\n<p> ברכה ושלום!</p>\n<p>באשטעטיג די ערהאלטונג פון אייער בריף פון כ\"ב אייר, אין וועלכען איר שרייבט - חאטש אין קורצען - וועגען אייער ארבעט אין די פארגאנגענע וואכען, און השם יתברך זאל העלפען אז די ארבעט זאל שטענדיג האלטען אין פארגרעסערען זיך און אויסברייטערען זיך, וואס דאס פאדערט זיך איצטער אין א פיל גרעסערער מאס איידער פאר אונדזער צייט, און וויבאלד אז מען פאדערט דאס פון אונז, גיט השם יתברך די מעגלעכקייט און כחות צו פארווירקליכען דאס.</p>\n<p>זיכער וועלען די פון אייך געקומענע דא צו דער אלגעמיינער אסיפה פון נשי ובנות חב\"ד, איבערגעבען א גרוס פון דאנען, און איך וויל דא צוגעבען אויך א וואונש צו [א] פרייליכען יום טוב שבועות און א געזונטען זומער פאר אייך און אייערע פאמיליעס שיחיו.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ד'שעט</b></i></h4>\n<p><b> אלגעמיינער אסיפה:</b> ראה לעיל אגרת ד'שנה.</p>"],[1200870110,"ד'שפ\n\n<p>ב\"ה, כ\"ו אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>לאחרי הפסק נעם לי לקבל מכתבו מיום החמישי... ונשען על מאמר הרמב\"ם (ראה הל' דעות פ\"ב. פ\"ג משמנה פרקים שלו) הידוע שבדוגמת רפואת הגוף הוא גם רפואת הנפש, הרי רואים אנו בבריאות הגוף שמייקרים את הזמן וכל שאפשר להקדים בהטבת הבריאות משתדלים בזה ואין מביטים על סדרים, סדרי זמנים או סדר המעלות, ובלבד שתקדים ההטבה והשיפור, וה\"ה במ\"ש אודות הפצת המעיינות \"שכיון שהידיעה שלו בזה עדיין נראית לקטנה, רוב הענינים אינם ברורים, ולכן יחכה בהפצת המעיינות עד שימלא גרעון הנ\"ל\", - וע\"פ האמור לעיל מופרכת שיטה זו, ובפרט ע\"פ הנודע במ\"ש יוסיף דעת יוסיף מכאוב, וגם מרגישים שכל שמתוסף בדעת האמיתית של תורה מבינים וגם מרגישים איך חסר בהבנה והשגה (וא\"כ מזמן לזמן יוגדל הגרעון בהרגשתו) והעיקר שהזמן הוא אבדה שאינה חוזרת, והנהגה בכ\"ז הוא ע\"פ מרז\"ל עמא פזיזא, ובמרז\"ל ברור עוד יותר חטוף ואכול חטוף ושתי דעלמא דאזלינן מני' כבי הילולא דמיא, ובודאי לדכוותי' למותר להאריך בזה, ויעיין ג\"כ אליבא דנפשי' במכתב כ\"ק אדמו\"ר (מוהרש\"ב) נ\"ע, נדפס במבוא לקונטרס ומעין דף כ\"ב איך שבזמננו אין סדר לבירורים, ויה\"ר שעוד הפעם יתבונן בכל הנ\"ל, ותקותי חזקה שבמילא יבוא למסקנא האמורה.</p>\n<p>בברכה לבשו\"ט ולקבלת התורה בשמחה ובפנימיות.</p>"],[1200870111,"ד'שפא\n\n<p>ב\"ה, כ\"ו אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה שניאור זלמן שי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מיום הבהיר ל\"ג בעומר הילולא דרשב\"י עם המוסגר בו וכן קבלתי הפ\"נ הכללי שאקראהו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, ועוד חזון למועד לאשר קבלתו לכללות אנ\"ש.</p>\n<p>ובמ\"ש אודות נטיעת שתילי אתרוגים קלברה באה\"ק ת\"ו הנה גם עתה, לדעתי אינו בדומה לאתרוגי קלברה עצמם, ורק שסר בזה הענין דהרכבה, כנראה משיחות נשיאינו רבוה\"ק, הי' בענין אתרוגי קלברה לא רק החשש דהרכבה. וכמובן גם מפתגם הידוע של רבנו הזקן אשר כשאמר הקב\"ה ולקחתם לכם וגו' שלחו שליח לקלברה והביאו משם אתרוגים. וכבר כתבתי במקום אחר (הועתק בהערות לקונטרסי תשרי) הטעם גם ע\"פ נגלה, כי קלברה היא איטליא של יון שהיא משמני הארץ, וכדאי' במד\"ר על פסוק זה, ולכן חל ע\"ז הציווי כל חלב לה' וכדרשת הרמב\"ם סוף הל' איסורי מזבח, וע\"ד אין מביאין בכורים אלא וכו'.</p>\n<p>ולהודעתו מיום ההולדת שלו הבע\"ל, הנה יה\"ר שתהי' שנת הצלחה אצלו בלימוד תורת הנגלה והנסתר וקיום המצות בהידור, ובזה - מצוה דזהיר בה טפי הנהגת הרבנות להיות מרא דאתרא כדבעי, וכמבואר בכ\"מ וענין המצוה מיוחדת דכאו\"א בפרט, שהיא השער לעליית כל התומ\"צ שלו ולהמשכת כל ההשפעות שלו וכמבואר בכ\"מ, ויהי' זה מתוך בריאות הרחבת הדעת ולאריכות ימים ושנים טובות, ובפרט אשר זכה להיות מרא דאתרא בכפר חב\"ד אשר שם צוה ה' את הברכה עד העולם ואשר תתגלה במקום זה מדת הרחמים שגדולה ממדת החסד שלפני' נחלה בלי מצרים מבריח מן הקצה אל הקצה.</p>\n<p>בברכה שדירתו חדשה תרחיב הדעת ותשנה המזל לטוב ובברכה לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ד'שפא</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ט ע' 390 והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> מו\"ה שניאור זלמן:</b> גרליק, כפר חב\"ד. אגרות נוספות אליו - לעיל ד'רפא, ובהנסמן בהערות שם.</p>\n<p><b> לאשר קבלתו:</b> לקמן אגרת ד'תד.</p>\n<p><b> נטיעת שתילי אתרוגי קלברה באה</b><b>\"</b><b>ק</b><b>:</b> ראה לעיל אגרת ד'שלז, ובהנסמן בהערות שם.</p>\n<p><b> וכבר כתבתי:</b> ראה גם לעיל ח\"י אגרת ג'נו.</p>\n<p><b> וכמבואר בכ</b><b>\"</b><b>מ</b><b>:</b> ראה גם לעיל חי\"א אגרת ג'תשיד, ובהנסמן בהערות שם. חי\"ב ד'ריא.</p>\n<p><b> תתגלה במקום זה מדת הרחמים</b><b>:</b> ראה לעיל אגרת ד'שז, ובהנסמן בהערות שם.</p>"],[1200870112,"ד'שפב\n\n<p>ב\"ה, כ\"ז אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ איש רב<br>\nפעלים כו'<br>\nמו\"ה ניסן שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"ה אייר והקודם לו.</p>\n<p>בעת רצון אזכירו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע לבריאות הנכונה, ובודאי ביאר לכ' ג\"כ הרופא ששאל בעצתו, אשר ענין לחץ הדם תלוי במדה חשובה במצב רוח האדם, שמזה מובן שהנהגה מתאימה לדברי הבעש\"ט, עזב תעזוב עמו - עם הגוף, בשמחה וטוב לבב, ה\"ז מהענינים שמתן שכרם בצדם הטבת בריאות הגוף כפשוטה, וכנראה גם במוחש.</p>\n<p>ומה נפלאו דברי רבינו הזקן בתניא פרק מ\"ט (ס\"ט סוף ע\"ב) ובנו בחרת כו' הוא הגוף כו', ומסוגלים ימים אלו בפרט להאמור כיון שהם ימי הכנה לקבלת התורה, אשר כדרז\"ל נעשו כל ישראל בריאים בגופם ושלמים (וע\"פ כל הנ\"ל מובן שאין להתנצל כלל על מה שכתב אלי בענין זה, כי נוסף על הפתגם החסידותי הידוע, יענעמס גשמיות איז בא מיר רוחניות, הרי גוף הישראלי קדוש הוא וכמובן גם מתניא הנ\"ל)</p>\n<p>כיון שאינו מזכיר בהנוגע לבריאות זוגתו הרבנית שתליט\"א בטח הכל בסדר.</p>\n<p>בת\"ח על הבשו\"ט מההידור בעניני המקוה ובטח ימשיך כת\"ר בכיוון זה למהדרין מן המהדרין, במקוה האמורה וגם בשאר המקואות שהשפעתו מגיעה, ובימיו ובימינו נזכה לקיום היעוד אשר מקוה ישראל ה' ויזרוק עלינו בתכ\"י מים טהורים וכמ\"ש וזרקתי עליכם מים טהורים הקדמה קרובה לגאולה האמיתית הבאה תיכף לאחרי זה.</p>\n<p>בברכה כלשון הרב הוא כ\"ק מו\"ח אדמו\"ר לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ד'שפב</b></i></h4>\n<p><b> מו\"ה ניסן:</b> טלושקין, ברוקלין. אגרות נוספות אליו - לעיל חי\"ב ג'תתקכח, ובהנסמן בהערות שם.</p>\n<p><b> דברי הבעש\"ט:</b> ראה גם לעיל חי\"א אגרת ג'שפא, ובהנסמן בהערות שם. חי\"ב ג'תתלו.</p>\n<p>לקמן ד'תריד.</p>\n<p><b> נעשו כל ישראל בריאים:</b> ראה גם לעיל ח\"ו אגרות א'תקסח. א'תקעט. א'תרכ.</p>\n<p><b> בתכ</b><b>\"</b><b>י</b><b>:</b> בתוככי כל ישראל.</p>"],[1200870113,"ד'שפג\n\n<p>ב\"ה, כ\"ז אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>לאחרי הפסק ארוך נעם לי לקבל מכתבו מי\"ד אייר שמסתדרים הענינים והולכים ובכיוון טוב, היינו בשני הפרטים שתהי' לו דיעה (ובטח בדרכי נועם תהי' לו דיעה זו בהנוגע להחלטה) ושישאר זה בסוד. ומזה עוד ראי' נוספת שאין לך דבר העומד בפני הרצון, ואשר מתקיים פסק דין של מעלה אשר בכל ענין של תורה יר\"ש ומדות טובות תהי' יד חסידי חב\"ד על העליונה, ורואים הפירות מהענין הראשון על אתר במה שבשיעור החדש ישנו למוד לקו\"ת וגם מתן שכרם בצדם בשידוך טוב ומתאים לילדיהם שי'.</p>\n<p>ויה\"ר שהצלחתו בכל הנ\"ל יעורר בו כחות נוספים לעבודה בשטח עניני חב\"ד ובהתרחבות והתפשטות אבל בדרכי נועם, ואז יהי' ע\"ד האמור כשאיש אחד מכם גולה לברבריא הרי מבררים את כל המדינה, ובירורים בימינו אלה הוא ע\"י הפצת המעינות (עד שיגיעו גם) חוצה שענינם לא רק לימוד החסידות אלא הליכה בהדרכותי' ומנהגי' וזהו עיקר וכמאמר המשנה לא המדרש [עיקר] אלא המעשה.</p>"],[1200870114,"ד'שפד\n\n<p>ב\"ה, כ\"ז אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה משה זלמן שליט\"א ובנו מו\"ה דוד<br>\nשליט\"א</p>\n<p> שלום וברכה!</p>\n<p>איך בין געווען צופרידען צו באקומען אייער בריף פון יום ב' אלס צוגאב צו די גרוסן און ידיעות וואס איך באקום פון אנ\"ש שיחיו שבאה\"ק ת\"ו על ידי משיח צדקנו.</p>\n<p>געוויס באזוכט איר ניט נאר דעם כפר חב\"ד, נאר אויך אלע מוסדות חב\"ד וועלכע געפינען זיך בארצנו הקדושה און נעמט אויך איינטייל אין די התועדות אנ\"ש וועלכע קומען פאר אין די ימי סגולה וואס אויף וויפיל דאס זאל ניט זיין חשוב אין אלע ערטער, איז דאס נאך מער חשוב'ר אין ארץ אשר עיני ה' אלקיך בה מראשית השנה ועד אחרית שנה, און לויט דעם באוואוסטען חסידישער ווארט, אז אידען טרעפען זיך צוזאמען קומט ארויס פון דעם א טובה צו די אלע וועלכע האבען זיך צוזאמענגעטראפען און וואס נאך מער, אז עס העלפט נאך א אידען, און בפרט ווי מען זעהט דאס בעשיינפערליך, אז די באגעגעניש איז מתוך אהבת ישראל און חסידישע ווארימקייט.</p>\n<p>ולקראת חג השבועות זמן מתן תורתנו הבא עלינו ועל כל ישראל לטובה, ווינש איך אייך און אלע אייערע לויטן נוסח הברכה וואס כ\"ק מו\"ח אדמו\"ר פלעגט באנוצען, לקבלת התורה בשמחה ובפנימיות.</p>\n<p>בברכת החג.</p>\n<h4><i><b>ד'שפד</b></i></h4>\n<p><b> מו\"ה משה זלמן</b><b>:</b> פייגלין, מלבורן (ובשעה זו באה\"ק). אגרות נוספות אליו - לעיל חי\"ב ד'ק, ובהנסמן בהערות שם. לקמן ד'תשח.</p>\n<p><b> חסידישער ווארט:</b> ראה גם לעיל ח\"י אגרת ג'קנט, ובהנסמן בהערות שם.</p>"],[1200870115,"ד'שפה\n\n<p>ב\"ה, כ\"ח אייר, תשט\"ז</p><p>ברוקלין.</p><p>הנהלת ישיבת תומכי תמימים אשר בלוד,<br>\nד' עליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתביהם מכ' כ\"ב כ\"ג אייר, ובמה שכותבים אודות המקום המתאים לבנין הישיבה. כבר כתבתי במכתבי מאז, הנקודה הכללית בזה, שצ\"ל בריחוק מקום האפשרי מבתי הספר למלאכה, כיון שסדרי הלימודים בשניהם אינם בשוה, ומהחלקות שמתאימות לתנאי זה באיזה מהן לבחור, עליהם לדון על אתר והשי\"ת יצליחם.</p>\n<p>לפלא שאין מזכירים במכתבם מפעולות הנוסעים [ב]יום הבהיר ל\"ג בעומר הילולא דרשב\"י, ובטח ינצלו גם ימי חג השבועות זמן מתן תורתנו הבע\"ל באופן המתאים ויה\"ר שיהי' בהצלחה.</p>\n<p>ולקראת חג השבועות הבע\"ל, הנה כלשון הרב הוא כ\"ק מו\"ח אדמו\"ר יה\"ר שנזכה כולנו בתכ\"י לקבלת התורה בשמחה ובפנימיות.</p>\n<p>קטעי מכ\"ע נתקבלו, ות\"ח.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'שפה</b></i></h4>\n<p><b> לבנין הישיבה:</b> שתועבר מלוד לכפר חב\"ד. ראה לעיל אגרת ד'דש, ובהנסמן בהערות שם.</p>\n<p><b> כבר כתבתי:</b> לעיל חי\"ב אגרות ד'קכג. ד'קלח.</p>"],[1200870116,"ד'שפו\n\n<p>ב\"ה, כ\"ח אייר, תשט\"ז</p><p>ברוקלין.</p><p>הנהלת צעירי אגו\"ח באה\"ק ת\"ו<br>\nסניף תל אביב,<br>\nד' עליהם יחיו</p>\n<p> שלום וברכה!</p>\n<p>לאחרי ההפסק הכי ארוך נתקבל מכתבם מכ\"ב אייר עם המוסגר בו, ויה\"ר שמכאן ולהבא תתרבה ההצלחה בעבודתם בקדש ויעבדו בה בשמחה ובטוב לבב, שגם עי\"ז תתוסף ההצלחה עוד יותר, וכמובן ע\"פ המבואר בדא\"ח בכ\"מ פעולת שמחה של מצוה ומרומז ג\"כ בהפתגם המובא בדא\"ח שמחה פורץ גדר, והרי מסוגלים ימים אלו דהכנה למתן תורה להאמור, שהרי במ\"ת הקדימו נעשה לנשמע והי' זה מאהבה רבה וכתוכן מרז\"ל כפה עליהם הר כגיגית, אברהם שקראו הר (תו\"א למגילת אסתר, צ\"ו ד') אלא שאז מודעא רבה לאורייתא כי כפה עליהם, משא\"כ בזמננו הרי זה נעשה בדרך אתעדל\"ת.</p>\n<p>מוסג\"פ העתק מכתבי כללי, שאף ששייך לנשי ובנות חב\"ד, בטח יש בתוכנו גם ענינים שיוכלו לנצלם בעבודתם בקדש, הם.</p>\n<p>ולקראת חג השבועות הבע\"ל, הנה כלשון הרב הוא כ\"ק מו\"ח אדמו\"ר יה\"ר שנזכה כולנו בתוכ\"י לקבלת התורה בשמחה ובפנימיות.</p>\n<p>לפלא שבעת הביקור דהת' בירות\"ו - לא ביקרו גם בבי\"ס הרשת.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'שפו</b></i></h4>\n<p><b> מכתבי כללי:</b> דלעיל ד'שנה.</p>"],[1200870117,"ד'שפז\n\n<p>ב\"ה, כ\"ח אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה דוד נתן<br>\nשי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"ה אייר עם המסוגר בו, הנה בעת רצון אזכיר את כל אלו שכותב אודותם על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, ויה\"ר שמתוך בריאות הנכונה והרחבת הדעת יוסיף אומץ בעבודתו בקדש בסביבתו בכלל ובבית הכנסת ובבית המדרש ביחוד, ואם מעט אור דוחה הרבה חשך עאכו\"כ הרבה אור, ואין לך דבר העומד בפני הרצון.</p>\n<p>ולקראת חג השבועות הבע\"ל, הנה כלשון הרב הוא כ\"ק מו\"ח אדמו\"ר יה\"ר שנזכה כולנו בתכ\"י לקבלת התורה בשמחה ובפנימיות.</p>\n<p>בברכה.</p>\n<p>במש\"כ ע\"ד שהבערה - דוקא - לחלק וללאו יצאת - יש להעיר מזה\"ק ח\"ב רג, ב ונתבאר בס' המצות להצ\"צ מצות לא תבערו. - כן יעוין שו\"ע לרבנו הזקן או\"ח סתצ\"ה בקו\"א (ושקו\"ט בזה בשו\"ת אבני נזר חאו\"ח סרל\"ח).</p>\n<p>במש\"כ לפרסם דברי מהר\"ל מפראג בהנוגע לניפוץ בציצית - בטח יבאר שזהו דברי המהר\"ל (ולא בשו\"ע וכיו\"ב).</p>\n<p>- במה שהעתיק מס' בנין אריאל שרק הארון עשה בצלאל והשאר רק ע\"פ דבריו ועצתו, כי האור <b>לא נברא במאמר</b> וכו' - הל' צריך ביאור, כמובן, ואין הס' תח\"י. וראה זח\"ב קכז, ב. רמב\"ן עה\"ת בראשית א, ג. - ולהעיר מפדר\"א פ\"ג: י' דברים עלו במח' כו' והארון והאור לעוה\"ב. ועיי\"ש בביאור הרד\"ל.</p>\n<h4><i><b>ד'שפז</b></i></h4>\n<p><b> מו\"ה נתן דוד:</b> לעסער, ברוקלין. אגרות נוספות אליו - לעיל חי\"א ג'תקעח, ובהנסמן בהערות שם. לקמן ד'תקמב.</p>\n<p><b> במש\"כ ע\"ד שהבערה - דוקא - לחלק וללאו יצאת:</b> במכתבו:</p>\n<p>כשבאתי לבקר את כ\"ק אדמו\"ר שליט\"א... בחיים חיותו של כ\"ק אדמו\"ר כבוד חותנו הקדוש נ\"ע... אמרתי לפני כ\"ק אדמו\"ר שליט\"א הסבר על טעם למה הבערה דוקא לחלק יצאת... וכ\"ק אדמו\"ר שליט\"א אמר לי ג\"כ טעם נכון, אבל אינני זוכר בדיוק. כמדומה לי שהבכן הי' לפי שהוא רק ניצוץ [...] הדקה כמו חודו של מחט ואח\"כ נחשב ככוחו וכוח כוחו וכשנולד הניצוץ כל שהיא אינו ראוי לכלום רק אח\"כ ניצץ האש יותר ויותר והוא חידוש. ע\"כ הנני זוכר ואולי שכחתי, אבקש במחכ\"ת הקדושה להודיע תוכן כוונתו בזה.</p>\n<p><b> דברי מהר\"ל מפראג:</b> שהובאו בדרישה (ס\"י סק\"א), הטעם שגם ניפוץ הצמר צ\"ל לשמה, שלפי\"ז יש להחמיר בציצית ע\"י מכונה. וראה לעיל ח\"ו אגרת א'תשכב.</p>\n<p><b> כי האור לא נברא במאמר:</b> אלא נתעטף הקב\"ה כו', ולפי שהארון נגד האור לכן הוצרך גם הוא להעשות (לא רק במאמר אלא) במעשה ידיו.</p>"],[1200870118,"ד'שפח\n\n<p>ב\"ה, כ\"ח אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> ברכה ושלום!</p>\n<p>במענה על מכתבה ממוצש\"ק, בו כותבת שלא השתתפה בפעולות נשי ובנות חב\"ד מפני שלא נעשו פעולות בזמן האחרון. - ומובן שאין תירוץ זה מספיק, שהרי על <b>כל</b> אחת ואחת מהחבירות להתענין בהרחבת הפעולות ולהרבות יזמה (אינציאטיב) בזה, ועאכו\"כ שזהו מחובתן של כל אחת מהחבירות במצב כדברי' שלא נעשו כל פעולות, וכיון שאין צועקין על העבר, הנה יה\"ר שתתנהג באופן כזה בהנוגע על להבא ובודאי כשיסתכלו בהמצב בסביבתן ימצאו כמה ענינים ואופנים איך לפעול בהצלחה.</p>\n<p>נכון במאד מה שעובדת בשטח חינוך בנ\"י על טהרת הקדש, ובודאי גם על ידי זה יתחזק בריאותה עוד יותר, ובפרט שמתקרבים אנו לזמן מתן תורתנו אשר התורה מביאה רפואה לעולם ומחזקת את האדם הישראלי ולא רק ברוח אלא גם בגוף.</p>\n<p>בברכה לבשר טוב בכל האמור לעיל,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<p>נ.ב.</p>\n<p>מוסג\"פ העתק מכתבי כללי לאסיפה הכללית של נשי ובנות חב\"ד כאן שבטח תנצל תוכנו בהתאם להאמור לעיל.</p>\n<h4><i><b>ד'שפח</b></i></h4>\n<p><b> מכתבי כללי</b><b>:</b> דלעיל ד'שנה.</p>"],[1200870119,"ד'שפט\n\n<p>ב\"ה, כ\"ח אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... וואס איר שרייבט בנוגע דעם כח הזכרון, דארפמען זעהען ניט צו פארמאטערן עם, דאס הייסט, ווען מען קוקט איין אין א ספר אדער מען לערנט און מען פילט אז דער כח הזכרון ווערט פארמאטערט, דארף מען אומבייטען דעם לערנען אויף א אנדער ענין פון לערנען, פון משניות צו עין יעקב, פון גמרא צו משניות, און ענליכעס, אדער טאן א אנדער מצוה ענין אויף א ויילע, און דערנאך צוריק קומען צום לערנען, און דער לערנען זאל זיין אין דעם וואס לבו חפץ, אויך דארפמען וויסען אויף אויסווייניג לפחות עטליכע פרקים משניות, און זעהן צו אויס'חזר'ן דאס באופן ניט צו פארמאטערן דעם כח הזכרון אויב אפילו דאס וועט נעמען עטוואס ליינגער.</p>\n<p>ולקראת חג השבועות הבע\"ל, הנה כלשון הרב הוא כ\"ק מו\"ח אדמו\"ר יהי רצון שנזכה כולנו בתכ\"י לקבלת התורה בשמחה ובפנימיות.</p>\n<p>בברכה.</p>"],[1200870120,"ד'שצ\n\n<p>ב\"ה, כ\"ט אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה מרדכי שי' הכהן</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מיום הבהיר הילולא דרשב\"י. - הנה ת\"ל אשר סו\"ס בא לפועל הענין דלקיחת שתילים וכפי המכתב שקבלתי עתה מאה\"ק ת\"ו כבר נטעו אותם, אף שעדיין איני יודע עד\"ז בפרטיות הדרושה, ואתענין לדעת מצדו באיזה אופן סגרו וחתמו על השתילים או שלחום ע\"י הבי דואר וכיו\"ב וכו'.</p>\n<p>לפלא שע\"ד עניני העיר אינו כותב כלום מלבד שתי המלות <b>הכל שלום</b> אשר הורגלו כזה לכתוב גם ע\"ד מצב דהעדר פעולות או באופן נעלה יותר כשהוא כדבעי בהקו דסור מרע אף שאין נעשה בהקו דועשה טוב, ועיין תניא פרק ל' ומה לי בחי' סור מרע ומה לי בחי' ועשה טוב הכל היא מצות המלך הקדוש יחיד ומיוחד ב\"ה.</p>\n<p>וכיון דאתאן להכא, באתי על עוד ענין שכנראה גם לא הותחל עד\"ז והוא הפעולה בין הנשים, ומוסג\"פ העתק מאחד ממכתבי בזה, והרי עתה הם ימי סגולה וכמבואר גם במכתבי זה, והאריכות בזה אך למותר.</p>\n<p>בפ\"ש כל אנ\"ש ובברכה לבשו\"ט בכל האמור ולקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ד'שצ</b></i></h4>\n<p><b> מו\"ה מרדכי</b><b>:</b> פרלוב, מילנו. אגרות נוספות אליו - לעיל חי\"ב ג'תתקסט, ובהנסמן בהערות שם.</p>\n<p><b> דלקיחת שתילים:</b> מאתרוגי קלבריה. ראה לעיל אגרת ד'שלז, ובהנסמן בהערות שם.</p>"],[1200870121,"ד'שצא\n\n<p>ב\"ה, כ\"ט אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"א אייר והקודמים.</p>\n<p>הנה פשיטא שהעדר המענה אין בזה ענין של קפידא ח\"ו והוא בסיבת הטרדות, וכיון שכותב בכל מכתב כו\"כ ענינים ביחד ונוסף על זה ריבוי שיטים בכל עמוד וכותב גם בין השיטים וממעל לשיטים, שכל זה מקשה העיון ולפעמים גם הקריאה, לכן גם המענה נדחה, ובאתי בזה רק להסיר החשש שלו הנ\"ל וכן להביע תמהוני על מיעוט הידיעות מפעולות צעירי אגו\"ח בכלל ומפעולותיו הוא בפרט.</p>\n<p>ולקראת חג השבועות הבע\"ל הנה כלשון הרב הוא כ\"ק מו\"ח אדמו\"ר יה\"ר שנזכה כולנו בתכ\"י לקבלת התורה בשמחה ובפנימיות.</p>\n<p>בברכה.</p>\n<p>נתעכב השילוח - בכדי לענות על שאלותיו, עכ\"פ בקיצור.</p>\n<p>א) בענין ניטל - הטעם ומנהגנו - כפי שהועתק בהיום יום י\"ז טבת.</p>\n<p>ב) נ' לפענ\"ד שזמנו ע\"פ הלוח היוליאני, שהוא ע\"פ חשבון תקופת שמואל [ולא ע\"פ הלוח הגריגוריאני, שהוא ע\"פ תקופת ר' אדא (אף שהוא מדויק יותר)], כיון שעפ\"ז הוא חשבון התקופה בברכת החמה ועוד. - אבל י\"ל שכיון שיוצא מהכלל ענין ניטל שקביעותו לא ע\"פ מנין בנ\"י אלא ע\"פ מנין או\"ה, א\"כ יש להתחשב עם מנין או\"ה הנוהג במקום דוקא, וכן אומרים בשם כ\"ק מו\"ח אדמו\"ר שבארצה\"ב אמר לנהוג הנ\"ל ע\"פ מנין המדינה כאן.</p>\n<p>ג) לשמועתו שבארה\"ק ת\"ו אין נוהגין בזה כלל (ובטח שמע זה מבר סמכא ביותר) - אם נכונה השמועה אולי אפ\"ל הטעם, שכיון שפשטה שם (מלבד תקופות קצרות, כידוע) ממשלת הישמעאלים, ותלוי בשר של מעלה, לא הי' מלכתחילה ענין לניטל שם, ובמילא אין החשש דלהוסיף חיות. ועפ\"ז יומתק ג\"כ הענין שבכל מדינה צ\"ל ע\"פ נוהג או\"ה שבמדינה, כנ\"ל. - ולהעיר מס' דרכי חיים ושלום סתתכ\"ה.</p>\n<p>ד) הנזהרים מלקדש כו' עפמש\"כ בשו\"ע אדה\"ז סרע\"א ס\"ג ושואל לחשבון השעות בזה, שנסתפק בהמענה שלי. - וא\"י המקום לספק: שליטת כל מזל הוא שעה של ששים מינוט, והסדר בזה ע\"פ המבואר בפרש\"י שבת (קכט, ב, ובכ\"מ), ולכן הנ\"ל הוא בשעה שביעית - משעות הנ\"ל - אחר חצות היום, כלשון רבנו הזקן שם, וחצות הוא באמצע בין נה\"ח ושקה\"ח כמובן.</p>\n<p>ה) מש\"כ שבאה\"ק ת\"ו אין נזהרים בזה, הנה אם הוא מנהג מקובל שם, י\"ל הטעם שמלכתחילה לא קבלוהו (והרי גם בשו\"ע שם דייק בלשונו: <b>יש</b> נזהרים כו' וכבר נת' שלכתחילה יש לו לקדש מיד כו' - אף שלפעמים יהי' זה בשעה הנ\"ל). והטעם להעדר קבלת מנהג זה (אפילו כשאין זה מיד בבואו כו') - י\"ל משום דשומר מצוה לא ידע דבר רע (ראה שו\"ע רבנו סתנ\"ה סעיפים טו-טז).</p>\n<p>וא\"ו) הטעם שהביא שבאה\"ק ת\"ו אין שליטה למזלות, אין נ\"ל דשייך <b>לענין זה</b> כיון דלא אישתמיט בשו\"מ לפרש כן. וסמוכות לזה מהא דרע\"ק (ובודאי גם ברתי') הרי היו בא\"י ובכ\"ז הוה דאיגא (שבת קנו, ב). וכן גם ריב\"ל הי' בא\"י ובכ\"ז כתב אפנקסי' האי מאן כו' (שם קנו, א). ודוחק גדול לומר <b>שכתב על פנקס שלו</b> בשביל תלמידיו שמבבל (עדמש\"כ בתוס' סוכה מד, א) כמובן.</p>\n<p>ז) במש\"כ בתיבת באולתו - כבר העירותי ע\"ז בתניא (דפוס ברוקלין תשט\"ו ע' תלב) שלפ\"ד צ\"ל כאולתו.</p>\n<p>ח) בענין אחש\"פ וד' כוסות - נתבארה דעתי בהתועדות דש\"ז אחש\"פ שעתה שייך זה לרבים. ונימוקי בארוכה אז.</p>\n<p>- בטח יבש\"ט משלום כל אלו שכתב אודותם במכתביו.</p>\n<h4><i><b>ד'שצא</b></i></h4>\n<p>חלקה נדפס בלקו\"ש ח\"י ע' 319 וחלקה בחי\"א ע' 290 והושלמה ע\"פ העתק המזכירות.</p>\n<p><b> בהמענה שלי</b><b>:</b> דלעיל חי\"ב ד'מב. וראה גם בהנסמן בהערות שם.</p>\n<p><b> שבאה\"ק אין שליטה למזלות</b><b>:</b> ראה גם לעיל חי\"ב אגרת ג'תתקעה.</p>\n<p><b> בהתועדות דש\"ז אחש</b><b>\"</b><b>פ</b><b>:</b> נדפסה בלקו\"ש ח\"ד ע' 1299.</p>"],[1200870122,"ד'שצב\n\n<p>ב\"ה, כ\"ט אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ' אייר, בו שואל:</p>\n<p>א) אם מחויב הוא ללמוד חסידות, כי אפשר שאיננו ראוי לכך.</p>\n<p>הנה <b>פשוט</b> הדבר* אשר מחויב הוא בלימוד חלק תורה זה, ובפרט שנמצאים אנו בזמן שנוגע לימוד זה לקיום המצות וללימוד שאר חלקי התורה, וכנראה במוחש שע\"י האור והחיות הבא ע\"י לימוד החסידות נתוסף חיות בקיום כל המצות ובפרט בעבודת התפלה שהוא הסולם שעל ידו עולה האדם מארצה השמימה, וכמבואר בזהר הק', והקדמה להתפלה צריכה שתהי' התבוננות בגדולת הבורא ב\"ה (כמובא באורח חיים סי' צ\"ח סעיף א') שיודעים מהותה ואופנה ע\"י לימוד החסידות.</p>\n<p>ב) מהו המקור שמשנים אנ\"ש נוסח התפלה והמנהגים לנוסח ומנהגי חב\"ד.</p>\n<p>הנה אינה מובנת השאלה בזה, כי פשיטא שהתלמיד צריך לנהוג כהוראת רבו דוקא, וכל אלו המקבלים עליהם את רבנו הזקן בעל התניא והשו\"ע לרב, פשוט שצריכים לנהוג על פי הוראתו.</p>\n<p>ג) מה הן דרכי ההתקשרות האמיתית.</p>\n<p>הוא הלימוד בתורת החסידות והליכה בהדרכותי' ומנהגי' שעי\"ז מתקשרים יחד כל החסידים.</p>\n<p>ד) מה הן הנהגות המיוחדות ללימוד תורת דא\"ח.</p>\n<p>הוא קיום המצות ולימוד התורה ובהידור האפשרי.</p>\n<p>ה) מי שעוסק הרבה בלימוד הנגלה אם זקוק הוא ללימוד החסידות.</p>\n<p>פשוט הדבר שכן הוא, ואדרבה עוד יותר, כמובא בזהר חלק ג' קנב, א. אשר לימוד פנימיות התורה שבימינו נתגלתה בתורת החסידות, היא נשמתא דאורייתא ללימוד נגלה דתורה שנקראת גופא דאורייתא וכמבואר שם, עיי\"ש.</p>\n<p>ויה\"ר שיתחיל בלימוד בפועל ובהקדם האפשרי ויוסיף בזה מזמן לזמן ובהקדמת נעשה לנשמע שזהו תנאי לקבלת התורה בכל חלקי', ויה\"ר שישפיע גם על חבריו בזה.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ד'שצב</b></i></h4>\n<p>*) יעוין בקונטרס עה\"ח בארוכה. וראה ג\"כ הל' ת\"ת לרבנו הזקן פ\"א ס\"ד: וא\"א לה להתתקן ולהשתלם כו'.</p>"],[1200870123,"ד'שצג\n\n<p>ב\"ה, כ\"ט אייר, ה'תשט\"ז</p><p>ברוקלין, נ.י.</p>\n<p> שלום וברכה!</p>\n<p>במש\"כ ע\"ד הנהגה בנישואין לבת כהן - הוא עפמש\"כ בשו\"ת צ\"צ חאה\"ע סי\"א, להיות בקי באיזה מסכת (עכ\"פ ממס' הקטנות ובקיאות בענינים ולא הל' ממש) וכל המוסיף מוסיפין לו בכט\"ס.</p>\n<h4><i><b>ד'שצג</b></i></h4>\n<p><b> נישואין לבת כהן</b><b>:</b> ראה גם לעיל ח\"ה אגרת א'תפב. ח\"ו א'תרא. ח\"ז ב'יד. חי\"א ג'תצט.</p>"],[1200870124,"ד'שצד\n\n<p>ב\"ה, כ\"ט אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מי\"ב אייר, מבשר טוב מהטבת בריאותו, הנה יה\"ר שכשם שמבשר טוב מהטבת הבריאות בגשמיות כן יבשר טוב במה שמסיים במכתבו אודות לימוד החסידות, אשר לא לבד שהתחזק בזה אלא שעוד מוסיף וכציווי תוה\"ק דמעלין בקדש ומובטח השי\"ת שיקיים ההבטחה כל המוסיף מוסיפין לו והמקבל עליו <b>עול</b> תורה היינו שזהו בדרך קבלת עול מתמעטים אצלו הדאגות והטרדות שכולם נכללים בהענין דעול מלכות ודרך ארץ וכפסק המשנה ולפום גמלא שיחנא.</p>\n<p>כבקשתו יזכירוהו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע למילוי משאלות לבבו לטובה לבן זכר, ובודאי שומר שלשת השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע בחומש תהלים ותניא הידועים, ועכ\"פ ישמור אותם מכאן ולהבא והשי\"ת יצליחו.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>"],[1200870125,"ד'שצה\n\n<p>ב\"ה, כ\"ט אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... וואס איר פרעגט פאר וואס קומט דאס וואס מען האט אויף אייך ארויסגעלאזט א נאמען וכו' - בכלל איז, בהדי כבשי רחמנא למה לך און א איד דארף זעהען מוסיף זיין אין תורה ומצות און אין השפעה אויף א צווייטען אין דעם זין, און אז מעט אור איז דוחה הרבה חשך על אחת כמה וכמה אז הרבה אור פארטרייבט סוף כל סוף דעם חשך און עניני חשך סיי ברוחניות און סיי בגשמיות, און השי\"ת זאל אייך מצליח זיין צו אנזאגען בשורות טובות אין דאס אויבען געזאגטע,</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות.</p>"],[1200870126,"ד'שצו\n\n<p>ב\"ה, כ\"ט אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו בו כותב אשר ראה השגחה פרטית, אבל מה יעשה וצריך הוא לסייעתא דשמיא לעבודת התפלה וכו'</p>\n<p>כבר ידוע פסק רז\"ל הבא לטהר מסייעין לו, ולאידך גיסא לא יגעת ומצאת אל תאמין, ולכן בידו הדבר תלוי, ואם יתייגע בזה כפי כחו, הבטיחתנו תורתנו הק' תורת חיים, יגעת ומצאת, אלא שבכדי להמשיך ההצלחה בפועל ולמטה, צריך לתת צדקה להזולת לא רק צדקה בממון אלא צדקה בהשפעה טובה לקרבו לתורה ומצות שעל ידי זה מתרבה ההצלחה שמלמעלה בענינים אלו של המשתדל כיון שמדתו של הקב\"ה מדה כנגד מדה (אלא שכמה פעמים ככה).</p>\n<p>כבקשתו הזכרתי את כל אלה שכותב אודותם על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע להמצטרך להם, ויה\"ר שיבשר טוב בזה ושהוסיף בלימוד התורה ובקיום המצות בהידור ומשפיע גם בסביבתו בכיוון זה.</p>\n<p>בברכת החג,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>"],[1200870127,"ד'שצז\n\n<p>ב\"ה, כ\"ט אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ וכו'<br>\nמו\"ה ישכר דוב שי</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מיום הששי, עם הפ\"נ המוסג\"ב עבור אמו שתחי' שקראתי היום ער\"ח על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע ואחכה לבשו\"ט.</p>\n<p>ת\"ח על הקורת רוח שגרם לי בכתבו אודות אופן חגיגת יום הבהיר ל\"ג בעומר הילולא דרשב\"י, ובודאי ינצלו גם זמן מתן תורתנו והימים שלפניהם ושלאחריהם בכיוון המתאים, בעוד מועד יכינו ג\"כ תכנית לימי החופש בקיץ הבע\"ל.</p>\n<p>ובמ\"ש אודות הסברא שילמדו לימודי חול בחצי יום הראשון, הנה מובן שבכלל אין רצוי הדבר, אבל מה ששואל אם יתנהג בזה בתקיפות, הרי אף שעיקר הוא שהתחלת היום ולימודיהם צ\"ל דוקא בלימודי קדש, אבל במקום דאי אפשר כלל יש להסכים בדוחק שלאחרי לימוד אחד של לימודי קדש, הרי שאר הלימודי קדש יהיו בשעות מאוחרות, כיון שגם באופן זה מתקיים הצווי שראשית עריסותיכם תתנו לה', (אף שעדיין במקומו עומד הגרעון שדוקא בשעות הבקר שהתלמידות קולטות את הלימוד יותר לומדים אז לא את הלימודי קדש), וי\"ל - שימצא אנשים מן הצד שישפיעו על פב\"פ שתסכים להמשיך בסדר הלימודים כמו עד עתה.</p>\n<p>ולהודעתו מעשיית התספורת של בנם יוסף יצחק שליט\"א, הנה יה\"ר שהוא וזוגתו שיחיו יגדלוהו לתורה ולחופה ולמעשים טובים.</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ד'שצז</b></i></h4>\n<p><b> מו\"ה ישכר דוב שי':</b> גורביץ, מנהל ביה\"ס בית רבקה בצרפת. אגרות נוספות אליו - לעיל חי\"ב ג'תתקי, ובהנסמן בהערות שם. לקמן ד'תפט.</p>\n<p><b> לימודי חול בחצי יום הראשון:</b> ראה גם לעיל חי\"ב אגרת ג'תתר, ובהנסמן בהערות שם.</p>"],[1200870128,"ד'שצח\n\n<p>ב\"ה, כ\"ט אייר, תשט\"ז</p><p>ברוקלין.</p><p>משתתפי שיעור הנלמד ברבים, ע\"י הרה\"ח<br>\nנו\"נ עוסק<br>\nבצ\"צ מו\"ה חיים אליעזר שי' הלוי</p>\n<p> שלום וברכה!</p>\n<p>בנועם קבלתי מכתבם בו כותבים אשר הוסיפו בקדש ללמוד גם ספר התהלים לנעים זמירות ישראל, נוסך על השיעורים דעד עתה, ומילתא היא שהזמן גרמא שמתקרבים אנו ליום ההילולא של דוד מלך ישראל החי וקים, אשר כמאמר רז\"ל התפלל שיהיו קורין בהם - במזמורי תהלים - <b>והוגים</b> בהם, ונוטלים עליהם שכר כנגעים ואהלות, ויהי רצון אשר ילכו מחיל אל חיל ומתאים להוראת תורת החסידות תורת אלקים חיים בשמחה ובטוב לבב עדי יקוים היעוד, ודוד עבדי נשיא עליהם לעולם בביאת משיח צדקנו במהרה בימינו.</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ד'שצח</b></i></h4>\n<p><b> מו\"ה חיים אליעזר:</b> הבר, פתח תקוה. ראה גם לעיל חי\"ב אגרת ד'קעד. לקמן ד'תרמא.</p>"],[1200870129,"ד'שצט\n\n<p>ב\"ה, כ\"ט אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ כו'<br>\nמו\"ה אברהם דוד שי'</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מיום החמישי,</p>\n<p>ובקשר למה שכותב שהוא מיו\"ח של החסיד הנודע מו\"ה כו' וכו' משה יצחק ז\"ל מיאסס, אתענין לדעת אם יש תחת ידו איזה מכתבי יד שלו בתורת החסידות או מסיפורי החסידים השייכים להנ\"ל ואם הן, תוכנם לפי ערך עכ\"פ, ות\"ח מראש על הטרחא.</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות ולבשורות טובות.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ד'שצט</b></i></h4>\n<p><b> מו\"ה אברהם דוד:</b> שלינקא, ראשון לציון.</p>"],[1200870130,"ד'ת\n\n<p>ב\"ה, כ\"ט אייר, תשט\"ז</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה יונה שי'</p>\n<p> שלום וברכה!</p>\n<p>אין ענטפער אויף אייער בריף פון ה' אייר.</p>\n<p>עס וואונדערט מיר וואס איר דערמאנט גארניט וועגען אייער עסקנות צבורית, וועגען וועלכעס איך פרעג אדער דערמאן אין מיינע בריף צו אייך, און האפענטליך וועט איר דאס ערגענצען אין אייער נעקסטע בריף.</p>\n<p>די פ\"נ בייגעלייגט צו אייער בריף, וועלען געלייענט ווערן - בלי נדר אויף דעם ציון הק' פון כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע...</p>\n<p>בברכה לקה\"ת בשמחה ובפני'.</p>\n<p>נ.ב.</p>\n<p>זיכער האט איר געהערט פון דער געשעהעניש אין כפר חב\"ד באה\"ק ת\"ו און אין צוזאמענהאנג מיט דעם ווערט איצטער אנגעפירט א קאמפיין לטובת די בתי הספר למלאכה וחקלאות, אויף וועלכע עס איז געווען דער איבערפאל, ל\"ע ול\"ע. וואס לויטן ווארט פון רבנו הזקן, איז אין אזא ווארט ווערט נתגלה די מדת הרחמים וועלכע איז פיל גרעסער ווי מדת החסד שלפני' נחלה בלי מצרים ומבריח מן הקצה אל הקצה, האב איך איבערגעגעבען אייער טשעק אלס ערשטע איינצאלונג פאר דעם צוועק, און השי\"ת זאל העלפען אז בקרוב ממש זאלט איר מוסיף זיין אויף דעם כמה פעמים ככה און אויך אייערע קינדער זאלן טאן אזוי און כמה פעמים ככה און דאס וועט פארגרעסערען די ברכות פון השם יתברך והצלחתו אין געזונט פרנסה און אז דאס זאל זיין מתוך מנוחת הנפש והרחבת הדעת. און ערווארטע פון אייך גוטע בשורות אין דאס אלץ אויבען געזאגטע.</p>\n<h4><i><b>ד'ת</b></i></h4>\n<p><b> מו\"ה יונה:</b> דרעשער, באגאטא. אגרות נוספות אליו - לעיל חי\"א ג'תרעו. ג'תשמב.</p>\n<p><b> געשעהעניש אין כפר חב</b><b>\"</b><b>ד</b><b>:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>\n<p><b> ווארט פון רבנו הזקן</b><b>:</b> ראה לעיל אגרת ג'שז, ובהנסמן בהערות שם.</p>"],[1200870131,"ד'תא\n\n<p>ב\"ה, כ\"ט אייר, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>נאכן לאנגען שוייגען בין איך געווען צופרידען צו באקומען אייער בריף פון ל' בעומר, אין וועלכען איר שרייבט ראשי פרקים פון דעם וואס עס טוט זיך בא אייך, ותודה לא-ל פאר דער גוטע בשורה פון דעם געזונט פון פלונית שתחי', ויהי רצון עס זאל גיין פון גוט צו נאך בעסער.</p>\n<p>בנוגע אייער שרייבען, צו העלפען אחינו בני ישראל אשר בארצנו הק' תבנה ותכונן על ידי משיח צדקנו, איז באוואוסט די רייד פון דוד מלך - שהוא - חי וקים (תהלים קכ\"ז), אז ווען ה' יבנה בית, און ה' ישמר עיר, דענסטמאל העלפט דאס בויען און היטען פון א בשר ודם, און דעריבער מוז מען דורכאויס זעהען, אז השם יתברך זאל טאן דאס אויבען געזאגטע, וואס דאס פירט מען אויס על דרך דעם מאמר פון ר' אבא בר כהנא ור' אמי ור' אסי (אין פתיחתא דאיכה רבתא במדרש רבה) דורך לימוד תורתנו הק' און דעם לערנען איר ביראת שמים ועל טהרת הקדש, דארטען אין ארצנו הק', און ליידער זיינען ווייניג די העלפער אין דעם און אויך די וואס העלפען יע, איז דאס אין א ניט גענוגענדער מאס, און דעריבער דארף יעדער איד חובבי תורה ומצות וואס זיינען דורכגענומען מיט אהבת ישראל, וואס אמת'ע אהבת ישראל איז דורך אהבת התורה ואהבת השם, דארפען זיי שטיצען מיט א גאר אנדער מאס די מוסדות הנ\"ל בארצנו הק' ת\"ו.</p>\n<p>און אויב מען וועט אייך אויפווארפען, פארוואס איז ניט קענטיג אייער נדבה אין די פערשידענע קאמפיינס - קענט איר זיי ענטפערן אז ניט איר זשאלעוועט די געלט אדרבה איר גיט נאך מער לפי ערך (און בפרט, אז <b>די</b> געלט ותורתה פארקלענערט אויך הסכנה ובמילא ההוצאות אין ענינים גשמים וד\"ל).</p>\n<p>און אויך צוגעבען אז לויטן פסק רז\"ל איז ענייך קודמין ועניי עירך קודמין, אנ\"ש ומקושרים ושייכים, וואס פארלאנגען, און פרעגען בא מיר, ווייז איך זיי אן צו מנדב זיין אויף די מוסדות חב\"ד בארצנו הק' ת\"ו וואס די ארבעט דארט לויט דער פאדערונג פון דער צייט, ווערט אלץ מער און גרעסער, און איך האף אז אין כפר חב\"ד, וואו עס איז געווען השריפה אשר שרף ה' וועט דארט איצט נתגלה מדת הרחמים שהיא גדולה ממדת החסד שלפני' נחלה בלי מצרים מבריח מן הקצה אל הקצה, וכהוראת רבנו הזקן רבנו האמצעי וכ\"ק אדמו\"ר הצמח צדק, כי שם ציוה ה' את הברכה עד העולם.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'תא</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ט ע' 485 והושלמה ע\"פ העתקה.</p>\n<p><b> געווען השריפה:</b> ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>\n<p><b> נתגלה מדת הרחמים</b><b>:</b> ראה לעיל אגרת ג'שז, ובהנסמן בהערות שם.</p>"],[1200870132,"ד'תב\n\n<p>ב\"ה, כ\"ט אייר, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nצנמ\"ס הרש\"י שי'</p>\n<p> שלום וברכה!</p>\n<p>... בביקורו של מר שז\"ר כאן שוחחנו ע\"ד בקור אחדים מתלמידי תומכי תמימים דכאן - באה\"ק ת\"ו למשך איזה שבועות ואולי יותר, וע\"ד שמארגנת כאן בשנים האחרונות מחלקה התורנית של הסוכנות. והצעתי להנ\"ל שמכמה טעמים מתענין הנני בזה, למרות שבודאי גם פעולה זו תעורר תלונות וטענות עלי מכמה צדדים, וד\"ל, אבל מהתנאים העיקרים בזה - שע\"ד התייסדות הכפר וסיוע בעניניו שאין זה בא ע\"י מפלגה אלא ישר ממשרדים המתאימים, הרי גם ארגון הנסיעה צ\"ל רק באופן בלתי מפלגתי, ומחלקה התורנית בארצוה\"ב מפורסמת כענין של מפלגה, אף שבאופן רשמי אולי אינו כך, ולכן התנאי הוא:</p>\n<p>א) כיון שאין בקופת תו\"ת בכלל אמצעים ובמילא הוצאות נסיעה הנ\"ל, צריך אהי' לחפש ממקורות אחרים וע\"ח ענינים אחרים, ולכן אפשר לי לדון ע\"ד הגשמה בפועל אם הוצאות הכרטיסים יעמידו לרשותי, אבל כנ\"ל <b>ישר מהסוכנות</b>, ולא ע\"י מחלקה תורנית וכיו\"ב.</p>\n<p>ב) אף שברוב הפעמים מחלקת התרבות דהסוכנות נותנת הוצאות האש\"ל באה\"ק ת\"ו, והכרטיסים הם ע\"ח הנוסעים או המוסדות השולחים אותם. - מטעם הנ\"ל, היינו חוסר אמצעים והקישוים בהשגת אמצעים חדשים, בנדון נסיעת תלמידי תו\"ת, צ\"ל באופן אחר, היינו שיתנו הוצאות הנסיעה הלוך ושוב, והאש\"ל על אתר יסודר על ידי.</p>\n<p>מובן שאין נוגע לי איך שירשמו בפנקסי מחלקת התרבות לאיזה תכלית נתנו הכסף, אבל מצדי מודיע אני אופן הסידור בפועל.</p>\n<p>ג) ועוד נקודה עיקרית, אף שפשוטה היא, והיא: שתכנית וסדרי ביקורי תלמידי תו\"ת באה\"ק ת\"ו לא יתערבו בזה מבחוץ (היינו - באיזה מקומות יבקרו, בלוית מי כו' וכו') אף שגם אני מעונין שיבקרו במקומות שונים באה\"ק ת\"ו, אף שמקומם העיקרי יהי' במוסדות חב\"ד אשר באה\"ק ובכפר חב\"ד.</p>\n<p>... כדאי להעלות שאלה זו על סדר היום, כי לדעתי נסיעה זו תביא עדוד היותר גדול לתושבי הכפר בהוה, ולאלו אשר משדלם הנני שיתיישבו בו, וכן למוסדות חב\"ד - בכפר חב\"ד ובלוד...</p>\n<p>בברכה לבשו\"ט.</p>\n<h4><i><b>ד'תב</b></i></h4>\n<p><b> הרש</b><b>\"</b><b>י</b><b>:</b> ה\"ר שלמה יוסף זוין. אגרות נוספות אליו - לעיל ד'שי, ובהנסמן בהערות שם.</p>\n<p><b> בקור אחדים... באה</b><b>\"</b><b>ק</b><b>:</b> תוכנית שליחות אברכים לבקר במוסדות חב\"ד באה\"ק התחילה כבר בקיץ תשי\"ד, בשיחה עם מר שזר, כנזכר לעיל ח\"ט אגרת ב'תתכו: \"דברתי אתו ע\"ד שימצאו אמצעים לנסיעות קבוצת תלמידי תו\"ת דכאן למשך איזה חדשים לאה\"ק ת\"ו\".</p>\n<p>אמנם תוקף משנה קיבלה תוכנית זאת לאחר המאורע דלעיל אגרת ד'תרפא, ובהנסמן בהערות שם, ועיקר תפקיד השליחות היתה לעודד את יושבי כפר חב\"ד, ואת כללות אנ\"ש באה\"ק.</p>\n<p>בהמשך לזה - לקמן אגרות ד'תע. ד'תרצו.</p>\n<p>על נסיעת השלוחים ראה לקמן אגרת ד'תקמו, ובהנסמן בהערות שם.</p>"],[1200870133,"ד'תג\n\n<p><i> [אייר תשט</i><i>\"</i><i>ז</i><i>?]</i></p>\n<p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ</p>\n<p>מו\"ה ישראל זוסמאן שי'</p>\n<p>שלום וברכה!</p>\n<p>סו\"ס נתקבל מכתבו מכ\"ד ניסן, וביאורו העדר מכתביו מפני שלא נתקבל מענה מכאן, - הנה לפלא, כי פעמים בקשתי את אנ\"ש שלא יפרשו פירושים על העדר המענה מכאן כי ברובא דרובא הוא מפני הטרדות, שלכן באים לכל לראש המענה על הענינים הדחופים ונחוצים ביותר, וגם המענה לכאלו שלע\"ע אינם עדיין מאנ\"ש במאה אחוז וע\"ד האמור בתפלת שלמה המלך שישנם כאלו שצריכים להעביר (פארלויפן) הדרך.</p>\n<p>וד\"ל.</p>\n<p>במה שכותב אם לעשות מנין גם בקירוב להדירות החדשות ויש אומרים שעי\"ז יוחלש מצב בית הכנסת דעתה, - הנה בכגון דא צריך להחליט בהתאם לתנאי המקום והזמן, ובטח יש מקום לפשרה, היינו שבימות החול שאז טרודים במלאכה ובפרט בהנוגע לזמן תפלת שחרית, יהי' מקום תפלה בצבור בעוד מקומות, משא\"כ בהזמנים שפנוים יותר, הרי כבר ידוע דברוב עם הדרת מלך, ומובן שהנ\"ל הוא רק נקודה כללית, ויש להתייעץ על אתר עם המרא דאתרא וזקני אנ\"ש בהנוגע לפועל.</p>\n<p>וברכה בכל עת זמנה היא, - להודעתו אודות האפשערעניש של נכדו שליט\"א, הנה יה\"ר שהוריו יגדלוהו לתורה ולחופה ולמעשים טובים מתוך הרחבת הדעת, ומועתק לקמן קטע ממכתב כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, בנוגע למנהג ישראל זה של גזיזות השערות וכו'.</p>\n<p>ולהודעתו מנשואי בתו שתליט\"א, הנה יה\"ר שתהי' בשעה טובה ומוצלחת ולבנין בית בישראל בנין עדי עד על יסודי התורה והמצוה.</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<p>וז\"ל כ\"ק מו\"ח אדמו\"ר:</p>\n<p>... ובדבר גזיזת השערות - אפשערעניש - הוא דבר גדול במנהג ישראל ועיקרו הוא בהחינוך דהשארת פיאות על הראש, ומיום הגזיזה והנחת הפיאות של הראש, נהגו להדר להרגיל את התינוק בענין נשיאת ט\"ק וברכת המזון וק\"ש שעל המטה, והשי\"ת יהי' בעזרם שיגדלום לתורה ולחופה ולמעשים טובים מתוך פרנסה בהרחבה ובמנוחת הדעת בגשמיות וברוחניות.</p>\n<h4><i><b>ד'תג</b></i></h4>\n<p><b> מו\"ה ישראל זוסמאן:</b> דבורץ, כפר חב\"ד. אגרות נוספות אליו - לעיל חי\"ב ד'א, ובהנסמן בהערות שם. לקמן ד'תכה. ד'תריא.</p>\n<p><b> בתפלת שלמה המלך:</b> מלכים א ח, מג.</p>"],[1200870134,"ד'תד\n\n<p>ב\"ה, ר\"ח תליתאי, ה'תשט\"ז</p><p>ברוקלין, נ.י.</p><p>אנשי כפר חב\"ד הם ובני ביתם</p>\n<p>ד' עליהם יחיו</p>\n<p>שלום רב וברכה עד בלי די!</p>\n<p>הפ\"נ כללי שלהם נתקבל. וקראתיו ערב ראש חדש מתן התורה על ציון מיסד הכפר חב\"ד ומנהלו כ\"ק מו\"ח אדמו\"ר העומד ומשמש ומעורר רחמים רבים למילוי משאלות לבבם לטובה ולהתחזקות הכפר והתפשטותו, ולמילוי תפקידו כמרכז הפצת המעינות באה\"ק תובב\"א מתוך מנוחת הנפש והגוף הרחבת הדעת ובשמחה וטוב לבב.</p>\n<p>הצעתי שמשך המעת לעת דזמן מתן תורתנו שהוא גם הילולא דדוד מלכא משיחא והבעל שם טוב, יתחלקו למשמורות אומרי תהלים ולמשמורות לומדי חסידות - אנשי הכפר ואנ\"ש ומתלמידי לוד שיחוגו בכפר חב\"ד ויסיימו ויחתמו היו\"ט בהתועדות חסידותיית כאחים ממש כי אב אחד לכולנה ובהתעוררות והחלטות לחיזוק כל עניני הכפר וביחוד מוסדות החינוך הקימים וביסוד חדשים ביסל\"מ דפוס וסמינר לבנות ועוד.</p>\n<p>בברכה שיקוימו בהם, בתוך כלל ישראל דברי נותן התורה בחקותי (חקיקה שבתורה וחקיקה שבנפש) תלכו (מהלכים בלי גבול) ואת מצותי תשמרו ועשיתם (ביד ימין. עיין ד\"ה אם בחוקותי בס' המאמרים תרכ\"ו) אותם גו' ונתנה הארץ יבולה ועץ השדה יתן פריו גו' וישבתם לבטח גו' ונתתי שלום גו' והשבתי חי' רעה גו' והתהלכתי בתוככם גו' ואולך אתכם קוממיות וכדרז\"ל (ב\"ב עה, א) שתי קומות בתורה הנגלה ובתורת החסידות בנפש ובגוף בגשמיות וברוחניות.</p>\n<p>ובברכת קבלת התורה בשמחה ובפנימיות, לבשורות טובות בטוב הנראה והנגלה (כי כ\"ע מודי בעצרת דבעינן לכם) ולאלתר לגאולה האמתית והשלימה.</p>\n<p>מטעם המובן יושלח הנ\"ל - באיזה קיצורים גם במברק.</p>\n<h4><i><b>ד'תד</b></i></h4>\n<p>חלקה נדפס בלקו\"ש ח\"ז ע' 361 ובשלימות בחי\"ג ע' 161.</p>\n<p><b> הפ</b><b>\"</b><b>נ</b><b>:</b> בהמשך להמאורעות בכפ\"ח. ראה לעיל אגרת ד'רפא, ובהנסמן בהערות שם.</p>"],[1200870135,"ד'תה\n\n<p>ב\"ה, א' סיון, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה דוד שי'</p>\n<p> שלום וברכה!</p>\n<p>ת\"ח על מכתבו מכ\"ה אייר, בו כותב ע\"ד המשך הפעולות בעניני חסידות תורה ויהדות וידיעות ממצב הכללי בכפר חב\"ד אשר שם צוה ה' את הברכה, ובודאי יוסיף בזה וכל המוסיף מוסיפין לו בעניניו הפרטים, וכן יעורר את כל תושבי הכפר האנשים ונשים לעשות כהנ\"ל כל אחד ואחת מתאים למעמדו ומצבו ויכולתו וכשרונותיו, ובמדתו של הקב\"ה שהיא מדה כנגד מדה ישולם להם אלא שעוד כמה פעמים ככה בטוב הנראה והנגלה ובפרט שכפר חב\"ד הוא המקום אשר תתגלה בו מדת הרחמים שהיא גדולה ממדת החסד שלפני' נחלה בלי מצרים מבריח מן הקצה אל הקצה.</p>\n<p>ולקראת חג השבועות הבע\"ל הנה בלשון הרב הוא כ\"ק מו\"ח אדמו\"ר יה\"ר שנזכה בתכ\"י לקבלת התורה בשמחה ובפנימיות.</p>\n<p>בברכת החג ולבשו\"ט.</p>\n<h4><i><b>ד'תה</b></i></h4>\n<p><b> מו\"ה דוד</b><b>:</b> בראוומן, כפר חב\"ד. אגרות נוספות אליו - לעיל חי\"ב ד'ב, ובהנסמן בהערות שם. לקמן ד'תסז. ד'תרמז.</p>\n<p><b> תתגלה בו מדת הרחמים:</b> ראה לעיל אגרת ד'שז, ובהנסמן בהערות שם.</p>"],[1200870136,"ד'תו\n\n<p>ב\"ה, א' סיון, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו - בלי הוראת זמן הכתיבה - בו כותב אודות נוסח התנאים אשר אצלנו.</p>\n<p>הנה נכון הדבר שזהו הנוסח מכ\"ק אדמו\"ר הצמח צדק, ויש תחת ידי פוטוגרפיא מהתנאים והצ\"צ הוסיף גם בגוף כתי\"ק, וגם בו אין סופי השורות שוות וכו' נוסף על שאין נמצא שם ע\"ד קנס וכו'.</p>\n<p>בודאי בעת קשוה\"ת שלו חזר מאמר דא\"ח, ולפלא שאינו מזכיר עד\"ז במכתבו.</p>\n<p>ואכפול ברכותי שיהיו הקשו\"ת בשעה טובה ומוצלחת ולבנין בית בישראל בנין עדי עד על יסודי התורה והמצוה כפי שהם מוארים במאור שבתורה זוהי תורת החסידות.</p>\n<p>בברכת מזל טוב ולקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ד'תו</b></i></h4>\n<p><b> יש תחת ידי פוטוגרפיא</b><b>:</b> נדפסה בבטאון חב\"ד גליון 36 - 37 ע' 18.</p>"],[1200870137,"ד'תז\n\n<p>ב\"ה, א' סיון, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמלאכתו מלאכת שמים מו\"ה חיים שאול שי'</p>\n<p> שלום וברכה!</p>\n<p>... ובמ\"ש בסיום מכתבו, מה יהי' הסוף. - הנה לפלא הספק ח\"ו בזה, כי ידוע פסק בי\"ד שלמעלה, אשר בכל ענין של תורה יראת שמים ומדות טובות תהי' יד מקושריו והולכי בעקבותיו (של רבנו הזקן) על העליונה (עיין קיצורים והערות לס' תניא סוף עמוד קכ\"ב) וגם זה בכלל שכבר הצליחו להעמיד מוסד חינוכי חב\"ד, ובודאי תומשך ההצלחה גם בעתיד להמשיך בבנין המוסד ולשפרו באיכות ובכמות, ויה\"ר שיעשה זה בשמחה ובטוב לבב.</p>\n<p>ולקראת חג השבועות הבע\"ל הנה בלשון הרב הוא כ\"ק מו\"ח אדמו\"ר יהי רצון שנזכה כולנו בתכ\"י לקבלת התורה בשמחה ובפנימיות.</p>\n<p>בברכת החג.</p>\n<h4><i><b>ד'תז</b></i></h4>\n<p><b> מו\"ה חיים שאול</b><b>:</b> ברוק, ראשון לציון. אגרות נוספות אליו - לעיל חי\"ב ד'לט, ובהנסמן בהערות שם. לקמן ד'תקעא. ד'תשה.</p>\n<p><b> מה יהי' הסוף:</b> מקשיי בניית בנין לישיבת אחי תמימים בראשון לציון. ראה לעיל אגרת ד'רעט, ובהנסמן בהערות שם.</p>"],[1200870138,"ד'תח\n\n<p>ב\"ה, א' סיון, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"ו אייר, כבקשתו יזכירו את בנו הבכור... שליט\"א על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבגמ זי\"ע נשיא ישראל להטבת מצב בריאותו, וכבר ידוע הוראת רז\"ל אשר יין של קידוש והבדלה מוסיף במאור עיניו של אדם.</p>\n<p>ובמ\"ש אודות ענין המחשבות*, מובא בספרים הק' אמר עם הספר ישוב מחשבתו כו' שע\"י הלימוד בפנים, הנה האותיות מאירות ומועילות לבטל מחשבות בלתי רצויות, וגם בשעה שאין ספר מצוי הרי ע\"י שחקוקים במוח הזכרון דברי תורה בכלל וביחוד מפנימיות התורה הנקראת אילנא דחיי דלית תמן לא קשיא וכו' דכתיב ואת רוח הטומאה אעביר מן הארץ (רעי\"מ פ' נשא המובא ונתבאר באגרת הקדש לרבנו הזקן סי' כ\"ו) - כ\"ז דוחה חשך הם מחשבות הבאים מצד החשוך, וכבר ידוע שהמחשבה משוטטת תמיד (ולא כדבור, עת לחשות מלדבר) ודוחים מחשבה בלתי רצוי' דוקא ע\"י מחשבת קדש.</p>\n<p>ולקראת חג השבועות הבע\"ל וע\"פ מרז\"ל חייב אדם לומר בלשון רבו, הוא כ\"ק מו\"ח אדמו\"ר, הנה יה\"ר שנזכה בתכ\"י לקבלת התורה בשמחה ובפנימיות.</p>\n<p>נ.ב.</p>\n<p>במ\"ש אודות הספרים דהוצאת קה\"ת, כמדומה כבר נכתב שבזה יש לפנות</p>\n<p>להמתעסקים בזה באה\"ק ת\"ו ובראשם הרב אברהם פריז רח' בר כוכבא 16, פתח תקוה.</p>\n<h4><i><b>ד'תח</b></i></h4>\n<p>*) בטח מניחים גם תפילין דר\"ת - מוחין דאבא. וכנראה אשר עת לבודקן - התפלין דרש\"י והתפלין דר\"ת.</p>\n<p>נדפסה בלקו\"ש חי\"ט ע' 466 והושלמה ע\"פ העתק המזכירות.</p>"],[1200870139,"ד'תט\n\n<p>ב\"ה, א' סיון, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"ה אייר, נעם לי לקרות בו אשר כמה ספיקות שהיו לו, חוסלו, וכמבואר בספרים הק' אשר ספ\"ק בגימט' עמל\"ק הכוונה לקליפת עמלק, שבדוגמת עמלק כפשוטו ענינו שאף שהאמבטי' רותחת קופץ לתוכה, ובלבד לקרר את בני ישראל וכמ\"ש אשר קרך [עיין במדרש תנחומא שם], ומזה בנין אב לכל הספיקות שמזכיר אשר מקורם כפי האמור וד\"ל.</p>\n<p>במ\"ש אשר קרא בספרי התוכנים ע\"ד כוכבים שקרן האור משם צריך ללכת הרבה יותר משית אלפי שנין עד שיגיע לארץ, ומקשה איך יתאים עם המובא בתוה\"ק שנמצאים אנו בשנת ה'תשט\"ז לבריאה.</p>\n<p>הנה אפילו את\"ל שחשבון הנ\"ל ע\"ד מרחק הכוכב - אמיתי הוא (כי גם בזה יש חילוקי דיעות בין התוכנים) אין מזה קושיא לתאריך הבריאה, שהרי כמו שנבראו הכוכבים נבראו ג\"כ קרני האור, וכמו שיכול השי\"ת לברוא כוכב שרק אז ואח\"כ יתחיל להאיר, כן אפשרי שיברא הכוכב ביחד עם קרני האור היוצאים ממנו. ובפרט ע\"פ הנאמר בפרשה ראשונה שבתורתנו ויהי בקר יום אחד, ו\"יהי מאורות\" אך ביום הרביעי, היינו שהיתה מציאות אור בקר קודם תליית המאורות ברקיע השמים.</p>\n<p>במ\"ש שראה בס' פלוני, אשר יש לומר שששת ימי בראשית אינם ימים של כ\"ד שעות כו' וכו' - ולצערנו נמצאים פירושים כאלו גם בעוד ספרים, אבל <b>מעקמים</b> הם את הכתובים מפני, שבמחילת כת\"ר, לא ידעו כדי צרכם \"היסודות\" עליהם נבנו השערות החוקרים השונים במדעים בהנוגע לתאריך הארץ. כי הידיעה והחקירה ביסודות אלו מוכיחה לשכל הבריא שאינם אלא <b>השערות ורחוקים</b> מודאיות, וכן הוא <b>דעת בעלי</b> <b> המדע</b> וכמובא בספריהם הם, אף שמעלימים הספיקות שיש להם בהיסודות, בספרים הנלמדים בבתי ספר להמתחילים בזה. ולמותר להאריך ולהעיר על הראי' הכי פשוטה, שששת ימי בראשית ענינם - של כ\"ד שעות, כיון ששמירת יום השבת לאחרי ששת ימי השבוע קשור בזה.</p>\n<p>בודאי יודע משלשת השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע בחומש תהלים ותניא הידועים ועכ\"פ ישמור אותם מכאן ולהבא, נוסף על לימוד שיעור קבוע בתורת החסידות.</p>\n<p>בברכה.</p>\n<h4><i><b>ד'תט</b></i></h4>\n<p>נדפסה בלקו\"ש חט\"ו ע' 478. בהמשך אליה לקמן אגרת ד'תרס.</p>\n<p><b> ספ\"ק בגימט' עמלק:</b> ראה גם לעיל חי\"א אגרת ד'תשכב.</p>\n<p><b> שנמצאים אנו בשנת ה'תשט</b><b>\"</b><b>ז</b><b>:</b> ראה גם לעיל חי\"ב אגרת ג'תתסח.</p>\n<p><b> השערות</b><b>:</b> ראה גם לעיל חי\"ב אגרת ד'רט. לקמן ד'תיד.</p>"],[1200870140,"ד'תי\n\n<p>ב\"ה, ג' סיון, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"ו אייר, הנה כיון שאין לו לדיין אלא מה שעיניו רואות, אפשר שמה שכותב בהנוגע להנהגה חריפה עם התלמידים זקוקים לזה ב..., אבל בכל זה הרי יש לדון בזה עצמו אם במדת החסד או במדת הגבורה, ולכן אפילו במקום שמוכרחים להנ\"ל הרי מכמה טעמים יש להקל ולרחם בדין ובפרט ע\"פ מאמר רז\"ל שלשה תהא ימין מקרבת ושמאל דוחה, וביחוד שיש חשש גם להענין דהמכה בנו גדול וכו' נוסף על השמועות (שכנראה מקורם מתלמידים הקשישים הנ\"ל) שאינם מוסיפים בשם הטוב וכו' וד\"ל...</p>\n<h4><i><b>ד'תי</b></i></h4>\n<p>לתוכנה ראה לעיל אגרת ד'רעו.</p>"],[1200870141,"ד'תיא\n\n<p>ב\"ה, ג' סיון, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>... וכידוע הפתגם, שהמחנכים של הישיבות וכו' הם בשביל התלמידים ולא להיפך, שמזה הוראה שבמקום ספק יש לפסוק הדין באופן שהוא תועלת יותר בשביל התלמידים מבלי להתחשב כ\"כ עם השם טוב של המחנכים והמחוקקים.</p>\n<p>ואת\"ל הרי זהו מעין מס\"נ, אבל בתקופתנו זו גם זה דורשים מאתנו, וכמבואר בחסידות הדיוק מסירת הנפש ולא מסירת הגוף, והוא שמוותר על טובתו ואפילו על טוב האמיתי דקדושה בשביל תועלת הזולת ובפרט תועלת הרבים, וכידוע פתגם רבנו הזקן בעל התניא והשו\"ע מענה על השאלה, מה חידשה החסידות, ומענתו לעשות טובה להזולת ע\"ח טובת עצמו, ושאלוהו שזקוקים לראי' ע\"פ נגלה דתורה שכן הוא, וענה שזה מפורש בש\"ס שורפן חסיד (נדה יז, א עיי\"ז בתוס')...</p>\n<p>ואדם רואה מהרהורי לבו שמתקרבים אנו לזמן קבלת התורה ולא קבל נותן התורה הערבות דהתישים כי אם דוקא ערבות הגדיים, וק\"ל. וידוע פירוש האריז\"ל עה\"כ והימים האלה נזכרים ונעשים, שכשהם נזכרים הרי נעשים ובאים בפועל כל הענינים שבפעם הראשונה, ויה\"ר שנזכה לבשו\"ט בכל האמור.</p>\n<p>בכבוד ובברכה בלשון הרב הוא כ\"ק מו\"ח אדמו\"ר לקבלת התורה בשמחה ובפנימיות.</p>"],[1200870142,"ד'תיב\n\n<p>ב\"ה, ג' סיון, תשט\"ז</p><p>ברוקלין.</p><p>האברך הוו\"ח אי\"א נו\"נ עוסק בצ\"צ אהרן<br>\nשי'</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מכ\"ה אייר, ובודאי ימשיך בבשו\"ט מפעולותיו הוא וכן מפעולות שאר אנ\"ש שי' אשר במחנם הט'.</p>\n<p>מוסג\"פ העתק מכתבי כללי, אף שבודאי יושלח ימים אלו באופן רשמי לסניף נשי ובנות חב\"ד אשר במעלבורן.</p>\n<p>בודאי כמנהגם הטוב ישלחו לכאן קטעי המכ\"ע הנוגעים לעניני חב\"ד, ובודאי למותר לעוררם שמוכרח שידפיסו לעתים קרובות יותר מענינים אלו, ומה טוב כמו שעושים אנ\"ש בכמה מדינות שהנהיגו במכ\"ע המופיעים שם, ונקראים ע\"י אחינו בני ישראל, להדפיס בכל עש\"ק וערב יום טוב איזה ענין בתורה ומצותי' ואם באפשרי מבואר ומואר ברעיונות חסידותיים, ומהנכון שיעורר את אנ\"ש שיחיו על זה.</p>\n<p>בברכה לקבלת התורה בשמחה בפנימיות.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ד'תיב</b></i></h4>\n<p><b> אהרן שי':</b> סרברנסקי, מלבורן. אגרות נוספות אליו - לעיל חי\"ב ג'תתקנו, ובהנסמן בהערות שם. לקמן ד'תקיג.</p>\n<p><b> מכתבי כללי:</b> דלעיל ד'שנה.</p>\n<p><b> קטעי המכ</b><b>\"</b><b>ע</b><b>:</b> בהמשך לזה - לקמן שם.</p>"],[1200870143,"ד'תיג\n\n<p>ב\"ה, ד' סיון, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ מלאכתו מלאכת שמים<br>\nמו\"ה עזריאל שי'</p>\n<p> שלום וברכה!</p>\n<p>לאחרי שתיקתו הכי ארוכה נתקבל מכתבו מיום השלישי (וגם בו לא נמצאת כל סיבה להפסק הכתיבה משך כל הזמן).</p>\n<p>בו כותב ע\"ד עבודתו בקדש במחנם הט' והתפשטותה, ובטח לא יסתפקו בזה וירחיבוה הן בכמות והן באיכות מתאים לדרישת השעה, ובודאי יש כר נרחב שגם זוגתו תחי' תנצל כשרונותי' במחנם הט' במילואה, ואין הדבר תלוי אלא ברצון.</p>\n<p>במ\"ש אודות בנין המקוה, הנה חבל שכנראה עדיין באמצע העבודה בזה ואף שבכגון דא כל יום ויום עולם מלא הוא, וד\"ל, ובודאי אשר גם בזה הדבר תלוי ברצון המתעסקים בזה, כי היכולת ניתנה להם ככל הדרוש, ואחכה לבשו\"ט בכל האמור.</p>\n<p>ולקראת חג השבועות הבע\"ל, הנה בלשון כ\"ק מו\"ח אדמו\"ר יה\"ר שנזכה בתכ\"י לקבלת התורה בשמחה ובפנימיות.</p>\n<p>בברכת החג.</p>\n<p>נתעכב השילוח ובנתיים נתקבל מכתבו מי\"ד סיון... במש\"כ ע\"ד ביקור כאן צריך לברר אם מפאת שינוי המצב יתנו רשיון לחזרה ומובן שהבירור צ\"ל באופן בלתי רשמי וד\"ל.</p>\n<p>ובקשר עם יום ההולדת - ובטח ינהג במנהגי אנ\"ש ביום ההולדת - יה\"ר שתהי' שנת הצלחה במילוי תפקידו (נבראתי לשמש את קוני) ע\"י הקמת תלמידים חסידים יר\"ש ולומדים, ומתוך הרחבת הדעת.</p>\n<h4><i><b>ד'תיג</b></i></h4>\n<p><b> מו\"ה עזריאל שי</b><b>':</b> חייקין, אגאדיר. אגרת נוספת אליו - לקמן ד'תרלט.</p>\n<p><b> שינוי המצב</b><b>:</b> היחס ליהודים במדינות הערביות, בתקופה זו.</p>"],[1200870144,"ד'תיד\n\n<p>ב\"ה, ד' סיון, ה'תשט\"ז</p><p>ברוקלין, נ.י.</p><p>כבוד הרב הגאון המפורסם חו\"ב סועו\"ה<br>\nסדרן ופלפלן<br>\nוו\"ח אי\"א בעל מדות תרומיות איש<br>\nאשכולות דורש טוב<br>\nלעמו וכו' וכו' מוהררי\"א הלוי שליט\"א<br>\nרב ראשי</p>\n<p> שלום וברכה!</p>\n<p>ת\"ח לכהדר\"ג שליט\"א עבור המברק במענה על מברקי בהנוגע לענין הכאוב של הסינאגאג קאונסיל והניו-יורק בארד אוו ראבבייס, ונוסף על זה קבלתי פ\"ש אישית על ידי הרב האללאנדער שי' בשובו מביקורו באה\"ק ת\"ו ופרטים בזה. ואין די באר גודל ההיזק שנמנע על ידי צעד כהדר\"ג בבטלו את מכתבו. וכמו שכתבתי במברקי אשר לדעתי זהו נוגע באופן ישר גם לפלישת תנועת השמרנים והריפורם לאה\"ק ת\"ו, אף שמטעמים מובנים לא רציתי לפרש במברקי וכתבתי סתם \"ונוגע לדורות ולארצות\". ואם נזכה וינצלו שעת הכושר זו של היהדות בארצות הברית, יש מקום לומר שיהי' זה מפנה עקרי ביחס בני ישראל מכל החוגים לתנועת הקונסרבטיבים והריפורמים, מתאים לתורתנו הק'.</p>\n<p>ונזקקים לזה בדורנו, דור יתום, עוד ביותר, וכהוראת חז\"ל הידועה, שאם בקעה מצא - באיזה ענין או מצוה, הרי לא לבד שאי אפשר לתקנה על ידי פשרה, אלא אדרבה צריך להוסיף ולעשות משמרת - וגדר בה גדר.</p>\n<p>ואחתום מכתבי מתאים לדבר משנה, חייב אדם לומר בלשון רבו, הוא כ\"ק מו\"ח אדמו\"ר, לברך ולהתברך בקבלת התורה בשמחה ובפנימיות.</p>\n<p>בהוקרה בכבוד וברכה,</p>\n<p>בהזדמנות זו מצורף בזה מה שעלה ברעיוני בהנוגע לבעיות במכתב כהדר\"ג שליט\"א האחרון.</p>\n<p>בענין הסתירה - לכאורה - שבין דעת החוקרים אודות זמן הדרוש \"בשביל תקומת והופעת הכתב והתפתחות הלשונות והתרבויות בכלל\" ובין הפירוש הפשוט וישר בתורה ובמאמרי רז\"ל ומקובל מדורי דורות על כל עמנו בענין מנין לבריאת העולם, שזוהי שנת ה'תשט\"ז לבריאת העולם וכנוסח שטרות וכו', אשר \"זוהי השאלה השרשית בשלב של החקירות בזמן ההוה\" -</p>\n<p>לדעתי, אי אפשר שתהי' בזה סתירה, כי אי אפשר לסתור מהשערה בעלמא. וכונתי בזה:</p>\n<p>(א) בכלל, בנוגע לכל מסקנות המדע - ידוע היסוד והפרינציפיון (הנקרא, כמדומה, על שם הייזנברג), אשר כל ה\"חוקים\" שבכל ענפי המדע אינם אלא הנחות השערות היותר אפשריות, הקרובות יותר להתגשם. ז.א.: בנוגע לעתיד אי אפשר לו לאדם לדעת דבר בהחלט גמור, אלא רק בהשערה. ואחת ההשערות היא, אשר ככל שיגדל מספר המאורעות כן יגדל החלק מהם המתאים להנחות המכונות בשם \"חוק\" - <b>בערך</b> וביחס לחלקם שאינו מתאים אל ה\"חוק\". וגם זה גופא אינו אלא אפשר, כאמור, ולא מוכרח.</p>\n<p>לדוגמא - אין כל סתירה להמדע אם יראו אבן עפה מלמטה למעלה ולא להיפך, ואינו אלא בסתירה אל הרגיל ולא למסקנות המדע.</p>\n<p>כן הוא בנוגע לכל \"חוקי הטבע\", אין יוצא מכלל זה. ועל אחת כמה וכמה בהנוגע לחוקי ההתפתחות, אשר בין אנשי המדע גופא - כמה שיטות ישנן וסותרות ושוללות אחת את רעותה.</p>\n<p>(ב) נוסף על הנ\"ל: אפילו אם הי' במציאות <b>עתה</b> חוק (אמתי, ולא השערה) וסדר התפתחות קבוע, אי אפשר הי' לדון ממנו בנין אב בהנוגע לחוק וסדר התפתחות של תקופה קדומה בכמה אלפי שנה לזמננו.</p>\n<p>כשבאים לדון על ההתפתחות מקדמא דנא הרי זקוקים להשערות שונות ומרובות ביותר ושאין להם יסוד <b>בנסיון.</b> והחוקרים עצמם - כלם מודים כי תנאי הטבע והחיים אז היו שונים לגמרי מאשר הם עתה, כגון מדת חום האויר, לחץ האויר, מציאות האלמנטים הרדיו-אקטיווים במדה גדולה הרבה יותר מאשר עתה, היחס שבין החי והצומח וכו' וכו'.</p>\n<p>ומתמי' איך משתמשים החוקרים בנתונים דאופן ההתפתחות עתה - ליסוד השערותיהם בהנוגע להעבר הכי רחוק - כאילו לא נשתנה דבר, ומניחים הנחות ומסיקים מסקנות (אף שמעולם לא ניסה שום חוקר לבחון השערותיו בכור מבחן התנאים שהיו אז), ומקבלים אותם בלי פקפוק ומכריזים על מסקנותיהם כחוקים.</p>\n<p>ואם עד לתקופה האחרונה עדיין הי' צל של אמתיות בזה, הנה בתקופתנו, תקופת משבר במדע ג\"כ - גם הצל חלף ואבד. ולדוגמא: נוכחו לדעת שכמות אפילו <b>קטנה</b> <b> ביותר</b> של קאטאליזאטור, או של אלמנט רדיו-אקטיווי משנה התופעות ומהירתם ולפעמים באופן הכי <b>מפתיע.</b> תגלית זו שוללת אפשריות של ראי' <b>מדעית</b> להסיק מסקנות מדעיות בהנוגע לתהליך התפתחות הצמחים ובע\"ח וכו' בסביבה ובתנאים שהיו אז אלמנטים רדיו-אקטיווים במדה גדולה הרבה יותר משל עכשו.</p>\n<p>וזהו רק חלק מהתנאים <b>שבודאי</b> נשתנו, כי נוסף על זה, הרי חלו עוד שנויים עקריים רבים אחרים וכמו בהרכבת האויר וקלישותי' (density) שזה משפיע באופן עקרי על קרני השמש ועל קרני האור - cosmic rays - מכל המינים באופן החדרתם ופעולתם על הארץ.</p>\n<p>(ג) נוסף על כל הנ\"ל: כל שיטות ההתפתחות (ובמילא כל הקושיות הנ\"ל) מיוסדות על ההנחה שבראשית הי' חומר פשוט, ובתקופה ורגע מסויים, הנה מפני סיבות שאינן ידועות כלל, התחילה ההתפתחות ע\"י הרכבת חלקי חומר פשוט זה, יותר ויותר, עד שכעבור תקופה מסויימה הגיע לדרגא של צומח, ואח\"כ לדרגת חי וכו'. ועל השאלה למקור החומר הפשוט הראשון, הנה המענה הוא שאין זה מתפקיד חוקרי המדע לענות עלי'. ואם הנשאל הוא חוקר מאמין, אומר שנברא יש מאין על ידי הבורא. וכן בהנוגע לשאלה היסודית: מה גרם שהתחילו סיבות הנ\"ל לפעול בתקופה זו ולא קודם לה או לאחרי'.</p>\n<p>ופשיטא שאינו מובן כלל מהי הנפקא מינא והמדעיות של השיטה והקס\"ד שהבורא ברא ביליונים אטומים והטביע בהם חוקים מסויימים והאטומים התפתחו מדרגא לדרגא על פי חוקים אלו, או אם נאמר - כפירוש הפשוט דספר בראשית - שהקב\"ה ברא ביום ראשון את השוה\"א כו' ביום שני כו' עד שברא ביום הששי את האדם בעל שכל, מדבר, וברמת התפתחות גבוה. ואדרבה, מנקודת המבט המדעי דימינו אלה - מופרכת יותר באין ערוך בריאת יש מאין ואפס המוחלט אפי' בריאה פשוטה בעל תא אחד, מיצירת יש בעל התפתחות גבוה מיש פשוט במשך זמן קצר ביותר.</p>\n<p>ה\"סתירה\", כביכול, היותר גדולה בין המדע והאמונה - הוא ענין בריאה יש מאין, כי מדע פירושו ביאור ע\"י דבר שראוהו על כל פנים פעם אחת, ובריאה יש מאין אי אפשר ל\"הוכיח\" באופן כזה. ואדרבה כפי \"המסקנות\" של החקירות בתקופה האחרונה השמדת היש שיחזור לאין והפכו, בריאת יש מאין - אי אפשרי שיהיו בטבע. והמאמין בבריאה יש מאין למרות \"מסקנא\" הנ\"ל, נקל לו להאמין בבריאת אדם מפותח וכן בנוגע לבע\"ח וכו'. וכמרז\"ל: כל מעשה בראשית בקומתן נבראו. - אין כל סברא ושכל להגביל יכולת הבורא רק לבריאת יש מאין. ומי שיכול לברוא יש מאין - על אחת כמה וכמה שיכול ליצור אדם גולם מן האדמה.</p>\n<p>וממילא נפלו כל ההשערות בענין תקופה הדרושה להתפתחות וכו', כיון שאין כל סברא מדעית, ראי' ותוכחה שלא בקומתן נבראו (אפילו את\"ל שנתוספו אח\"כ מיני צומח ובע\"ח שנתפתחו מאלו שקדמום).</p>\n<p>(ד) שמעתי מקשים על כגון דא, לאיזה טעם הי' לו להבורא לברוא במיוחד דומם ובמיוחד צומח חי ומדבר, בה בשעה שהי' יכול לברוא רק הדומם הפשוט ביותר ולהניח אותו להתפתח מתאים לחוקי ההתפתחות ולא להטריח את עצמו כביכול בבריאה של ששה ימים בזה אחר זה.</p>\n<p>ומובן אשר אין כל מדעיות בקושיא זו, וגם סתירה ישנה מני' ובי', שהרי אין כל טעם <b>במדע</b> לבריאת היש מאין ולחקיקה חוקי הטבע כמו שנראים לנו, ובמילא אין מקום להקשות למה לנו להניח שהיתה תופעה פלונית בלתי מובנת בשכל האדם בה בשעה שבמקומה היתה יכולה להיות תופעה אחרת - כיון שגם היא בלתי מובנת בשכל האדם. וכנ\"ל, הרי אדרבה, תופעה השני', היינו בריאה יש מאין, \"מופרכת\" מנקודת מבט המדע יותר מאשר יצירת האדם כמו שהוא מן הדומם, בלי דרגות שבינתים.</p>\n<p>(ה) דרך אגב, במה שיש רוצים עתה לפרש מרז\"ל בונה עולמות ומחריבן, וכן המובא בזהר ובספרי קבלה אודות אדם קדמון, כפשוטן, היינו שהי' אדם גשמי והיו עולמות גשמיים שנחרבו אח\"כ ואחריהם נברא העולם הזה שהוא בן ה'תשט\"ז שנה, וכמובא פירוש זה בכמה ספרים וגם בספרי המקובלים הראשונים (כמה מקומות שמדובר בזה צוינו בתורה שלימה בראשית א: ה, ס\"ק תכ\"ב ואילך).</p>\n<p>הנה בעניני קבלה, כמו בכל חלקי התורה, אימתי יש מקום לדיעות חלוקות - קודם שנפסק הדין על פי כללי התורה, אבל לאחר פסק דין כדיעה אחת, הרי, בנוגע <b>למעשה</b> <b> ולפועל</b><b>,</b> רק דעה זו אמתית היא. והוא הדין בשאלה הנ\"ל: עד שבא האריז\"ל היתה בזה מחלוקת (וכמובא בספרים המצויינים בתורה שלימה הנ\"ל), אבל לאחר שאמר האריז\"ל דעתו, שהוא הוא הפוסק האחרון בכגון דא המקובל על כל בני ישראל, הן האשכנזים (רבינו הזקן וגם הגר\"א) והן הספרדים, ואמר דעתו ברור דאין הכונה לומר שהי' עולם גשמי כמו עולם הזה דעכשיו כו', כי זה לא הי' אלא דוקא בשמיטה זו לבד, (הובא ג\"כ בתורה אור לרבנו הזקן נא, ד; ובתורת חיים שם) - אין לפרש ענינים של מעשה ומציאות (וכמו ענין הבריאה בפועל) כי אם מתאים לדבריו.</p>\n<h4><i><b>ד'תיד</b></i></h4>\n<p><b> מהוררי</b><b>\"</b><b>א</b><b>:</b> הרצוג. אגרות נוספות אליו - לעיל ד'שו, ובהנסמן בהערות שם.</p>\n<p><b> מברקי</b><b>:</b> דלעיל ד'שו.</p>\n<p><b> במכתב כהדר\"ג שליט\"א האחרון</b><b>:</b> ראה לעיל ח\"י אגרת ג'שיט.</p>\n<p><b> אי אפשר לסתור מהשערה בעלמא</b><b>:</b> ראה גם לעיל אגרת ד'תט, ובהנסמן בהערות שם.</p>"],[1200870145,"ד'תטו\n\n<p>ב\"ה, ד' סיון, תשט\"ז</p><p>ברוקלין.</p>\n<p> שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מעש\"ק נוסף על הידיעות ע\"י הטעלעפאן ועל כגון דא נאמר סגנון מרז\"ל הידוע, אילו זכינו כו' עכשיו שלא זכינו כו' כוונתי שבאם הי' מתעסק בהחזקת היהדות והפצתה במחנו הט' ובתפקידו המיוחד בתור תלמיד תומכי תמימים בהפצת המעינות, זוהי תורת החסידות, עד שיגיעו גם חוצה, בודאי הי' עומד בקישור מכתבים ובאופן של זכינו היינו לא בענינים דעגמת נפש, ועכשיו שלא זכינו מתלפן וכותב בענינים כאלו.</p>\n<p>ויהי רצון שרמז זה מהשגחה העליונה יספיק ויבריא בנם שליט\"א בקרוב ממש, כיון שמכאן ולהבא וועט ער זיך אריינוארפן (ישליך עצמו) בהעבודה האמורה, ובמילא לעתים תכופות יבשר טוב מפעולות הטובות ופירותיהן ומהתכניות איך להרחיבן, אף שזה הרבה זמן שלא כתב עד\"ז והוא מפני החלישות גדולה בזה, הרי אין לך דבר העומד בפני התשובה וכמרז\"ל (הובא באגרת התשובה לרבנו הזקן פרק ט') הי' רגיל לקרות דף אחד יקרא שני דפים, וק\"ל.</p>\n<p>ולקראת חג השבועות הבע\"ל, הנה בלשון הרב הוא כ\"ק מו\"ח אדמו\"ר, יה\"ר שנזכה בתכ\"י לקבלת התורה בשמחה ובפנימיות, ולהכנסת בנם שליט\"א לבריתו של אברהם אבינו בשעה טובה ומוצלחת.</p>\n<p>בברכת החג.</p>\n<p>נ.ב.</p>\n<p>במ\"ש אודות השם, כבר ידוע שצריך להיות בהסכם שני ההורים יחד ויהי' לאורך ימים ושנים טובות.</p>"],[1200870146,"ד'תטז\n\n<p>ב\"ה, ד' סיון, תשט\"ז</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה חיים<br>\nהלל שי'</p>\n<p> שלום וברכה!</p>\n<p>בטח כבר מתכוננים בתכנית לימי הקיץ הבע\"ל חופש הנוער מבתי הספר ולימודי חול, שאז כר נרחב ביותר לפעולות הת\"ת כו' וכו' וכבר נאמר ותשועה ברוב יועץ.</p>\n<p>בודאי למותר לעוררו אשר בהמקומות שמבקר יעמוד עמהם בקישור מכתבים גם אחרי כן כדי לחזק ההתעוררות ובפרט בההחלטות בהנוגע לפועל.</p>\n<p>ולקראת חג השבועות הבע\"ל, הנה בלשון כ\"ק מו\"ח אדמו\"ר יה\"ר שנזכה בתכ\"י לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ד'תטז</b></i></h4>\n<p><b> מו\"ה חיים הלל:</b> אזימוב, פריז. אגרות נוספות אליו - לעיל חי\"ב ג'תתכ, ובהנסמן בהערות שם.</p>"]]});
